const O={};globalThis.P=(en,ar)=>({en,ar});try{globalThis["D"]=O["D"]=({"sites":[{"id":"bahra-1","n":"Bahra 1","c":"archaeological","s":"Ubaid Settlement","lat":29.6363,"lng":47.9552,"p":"Ubaid Period","dr":"5500–4900 BC","el":"12.30–14.50 m a.s.l.","desc":"The largest Ubaid-period settlement discovered outside Mesopotamia. Bahra 1 is a sprawling site in the Al-Subiyah desert that served as a major center for shell ornament production and trade during the late 6th millennium BC. Rutkowski & Kiersnowski (2025) established that during the Ubaid period, the coastline was 1.5 km south of Bahra 1, and the site lay further inland from the sea than the fishing village of H3. The Bahra anticline — a domal structure related to Precambrian Hormuz salt tectonics — has caused tectonic uplift of 1.72–2.64 mm/yr in this area.","sig":"Largest Ubaid settlement outside Mesopotamia; evidence of the earliest cultural exchange networks between Southern Mesopotamia and Eastern Arabia across the Arabian Gulf. Radiocarbon dating of marine shells from the paleo-seabed confirms the mid-Holocene highstand reached this area.","ex":"Kuwaiti-Polish Archaeological Mission (KPAM), Polish Centre of Mediterranean Archaeology, University of Warsaw","conf":"","ev":"","an":"","val":"","disc":["Shell Crafting Workshop: A 7,700-year-old courtyard used for crafting shell ornaments, the oldest known specialized workshop of its kind in the Gulf region.","Ancient Kilns: More than 20 ancient kilns dating to approximately 7,700 years ago, providing evidence of early pyrotechnology and pottery production.","Owl Sculpture: A rare ancient owl sculpture, one of the earliest artistic representations found in the Arabian Peninsula.","Copper Pin Fragment: An extremely rare copper pin fragment, evidence of early metallurgy and longdistance trade with copper-producing regions.","Ubaid Pottery: Distinctive painted pottery with geometric patterns characteristic of the Ubaid culture, linking this site to Mesopotamian traditions.","Paleo-Seabed Shells: Radiocarbon-dated marine mollusk shells from the paleo-seabed south of Bahra 1, confirming the mid-Holocene highstand reached this area around 5700 BP (Rutkowski & Kiersnowski, 2025).","One of the largest collections of Ubaid pottery outside Mesopotamia","Multi-room structures with stone foundations — earliest permanent architecture in the Arabian Gulf","Extensive lithic assemblage including blades, scrapers, and projectile points","Imported obsidian and bitumen demonstrating connections to Mesopotamia"],"refs":["Carter, R. & Crawford, H. (2010). Maritime Interactions in the Arabian Neolithic. Leiden: Brill","Rutkowski, Ł. et al. (2016). Bahra 1: Excavation of a Ubaid Settlement in Kuwait. Polish Centre of Mediterranean Archaeology, University of Warsaw","Bieliński, P. (2018). Bahrah 1: Eight Years of Excavations of an Ubaid Culture-Related Settlement in the Al-Sabbiyah Desert (Kuwait). Proceedings of the Seminar for Arabian Studies, 51, 23–30","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269"],"ic":"shell","era":"P","te":"The Shell Workshop","ta":"ورشة الأصداف","se":"Seven and a half thousand years ago, this was a busy village of stone houses. People sat in a courtyard carving shells into ornaments, fired pottery in more than twenty kilns, and traded goods that travelled all the way to Mesopotamia. Look closely and you may picture the little owl figure someone shaped here, one of the oldest pieces of art found in Arabia.","sa":"قبل سبعة آلاف وخمسمئة عام كانت هنا قرية نابضة ببيوت من الحجر. جلس أهلها في فناء يحوّلون الأصداف إلى حُليّ، وأشعلوا أكثر من عشرين فرنًا لصناعة الفخار، وتاجروا بسلع وصلت إلى بلاد ما بين النهرين. تخيّل تمثال البومة الصغير الذي صنعه أحدهم هنا، وهو من أقدم الأعمال الفنية في جزيرة العرب.","na":"بحرة ١","t0":7526,"t1":6926},{"id":"h3-site","n":"H3 (Jazirat Dubaji)","c":"archaeological","s":"Ubaid Maritime Site","lat":29.6417,"lng":48.1506,"p":"Ubaid Period","dr":"5500–5000 BC","el":"5.00–6.50 m a.s.l.","desc":"H3 is located on Jazirat Dubaji, a low peninsula on the north side of Kuwait Bay. During the Ubaid 2/3 period (turn of the 6th and 5th millennia BC), the sea bordered this fishing village on a narrow peninsula, while Bahra 1 lay further inland (Rutkowski & Kiersnowski, 2025). The site is a cultural borderland between Mesopotamian and Arabian Neolithic traditions, yielding some of the most significant maritime archaeological finds in human history.","sig":"Contains the world’s earliest evidence for seagoing vessels and the oldest evidence for the use of masts and sails, fundamentally changing our understanding of prehistoric maritime technology.","ex":"Kuwaiti-British Archaeological Expedition, directed by Dr. Harriet Crawford (1998–2004)","conf":"","ev":"","an":"","val":"","disc":["World’s Earliest Boat Evidence: Bitumen pieces with barnacles on one side and reed impressions on the other — the earliest physical evidence for actual boats in Western Asia and seagoing vessels globally.","Reed-Bundle Boat Model: A detailed ceramic model of a reed-bundle boat with incisions mimicking reed bundles, more detailed than any similar Mesopotamian find.","Oldest Sail Evidence: A ceramic disc depicting a reed-bundle boat with two masts — the oldest evidence for the use of masts and sails in human history.","Date Stones: Among the earliest evidence of date palm cultivation, connecting to similar finds on Dalma Island in the UAE.","Bitumen pieces with barnacles on one side and reed impressions on the other — earliest physical evidence for seagoing vessels globally","A detailed ceramic model of a reed-bundle boat, more detailed than any Mesopotamian find","A ceramic disc depicting a reed-bundle boat with two masts — oldest evidence for masts and sails in human history","Among the earliest evidence of date palm cultivation"],"refs":["Carter, R. (2006). Boat Remains and Maritime Trade in the Arabian Gulf during the Sixth and Fifth Millennia BC. Antiquity, 80(307), 52–63. DOI: 10.1017/S0003598X0009325X","Carter, R. & Crawford, H. (2010). Maritime Interactions in the Arabian Neolithic: The Evidence From H3, As-Sabiyah. Brill (American School of Prehistoric Research Monograph Series 8)","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Carter, R. (2006). Boat Remains and Maritime Trade in the Persian Gulf during the Sixth and Fifth Millennia BC. Antiquity, 80(307), 52–63. DOI: 10.1017/S0003598X0009325X","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269"],"ic":"boat","era":"P","te":"Where Sailing Began","ta":"حيث بدأ الإبحار","se":"On a narrow tongue of land by the sea, fishermen left behind the oldest clues to seagoing boats anywhere on Earth. Lumps of tar still carry barnacles on one side and the print of reeds on the other. A clay disc shows a boat with two masts, the earliest picture of a sail ever found. Human sailing may have started right here.","sa":"على لسان ضيق من اليابسة بجوار البحر، ترك الصيادون أقدم دليل على القوارب البحرية في العالم. قطع من القار ما زالت تحمل محار البرنقيل على وجه وآثار القصب على الوجه الآخر. وقرص من الطين يصوّر قاربًا بصاريتين، وهو أقدم رسم لشراع عُثر عليه. ربما بدأ الإنسان رحلته مع الإبحار من هنا.","na":"H3 جزيرة دوباجي","t0":7526,"t1":7026},{"id":"subiyah-tumuli","n":"Al-Subiyah Tumuli Cemetery","c":"archaeological","s":"Bronze Age Cemetery","lat":29.645,"lng":48.05,"p":"Bronze Age","dr":"2900–1150 BC","el":"","desc":"A vast tumulus burial field stretching across the northern coast of Kuwait Bay, containing approximately 130 stone burial mounds and associated structures. Rutkowski & Kiersnowski (2025) established that tumuli are distributed along terraces parallel to the former sea bay and the Jal azZor hills, with most positioned above 18 m a.s.l. Radiocarbon dates concentrate from the end of the 4th millennium to the mid-2nd millennium BC, coinciding with the highest sea levels in Kuwait Bay. The absence of known Bronze Age settlements suggests the burial mounds were constructed by nomadic or semi-nomadic groups with close ties to the sea.","sig":"One of the largest Bronze Age burial complexes in the Arabian Gulf. Artefact-based dating spans from Early Dynastic I-II ( 2900 BC) through the Kassite period ( 1150 BC), with possible earlier Ubaid-period origins and later Iron Age reuse.","ex":"Kuwaiti-Polish Archaeological Mission (KPAM), directed by Dr. Łukasz Rutkowski","conf":"","ev":"","an":"","val":"","disc":["Tumuli with Outer Ring Walls: Impressive dry-stone funerary monuments with distinctive outer ring walls, a construction technique unique to this region.","Semi-Precious Stone Beads: Perforated pearls and beads of carnelian, agate, lapis lazuli, and chrysoprase — evidence of long-distance trade reaching Afghanistan and the Indus Valley.","Dilmun Shell Ornaments: Circular shell plaques with geometric decoration and ‘dot-in-circle’ motifs characteristic of the Umm an-Nar and Dilmun cultures.","Akkadian-Style Cylinder Seal: A cylinder seal dated 2300–2100 BC found between SBH 34 and Bahra 1, connecting the cemetery to Mesopotamian administrative traditions.","Kassite-Style Goblet: A goblet from SBH 34 dated 1600–1150 BC, evidence of continued use of the cemetery into the Late Bronze Age.","130 dry-stone funerary monuments with distinctive outer ring walls","Perforated pearls and beads of carnelian, agate, lapis lazuli, chrysoprase — trade reaching Afghanistan","Circular shell plaques with “dot-in-circle” motifs of Umm an-Nar and Dilmun cultures","Cylinder seal 2300–2100 BC connecting to Mesopotamian traditions","Goblet 1600–1150 BC showing continued Late Bronze Age use"],"refs":["Rutkowski, Ł. (2015). Bronze Age Funerary Landscapes of Northern Kuwait. Polish Centre of Mediterranean Archaeology","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269"],"ic":"mound","era":"P","te":"Hill of a Hundred Graves","ta":"تلال المئة قبر","se":"Across the terraces above the old bay rise about 130 stone burial mounds. They were built over nearly two thousand years by people who moved with the seasons and lived close to the sea. Inside, explorers found stone beads, shell ornaments and a tiny carved seal, gifts for a journey into the afterlife.","sa":"على المدرجات المطلّة على الجون القديم ترتفع نحو 130 تلة دفن حجرية. بناها على مدى قرابة ألفي عام أناسٌ تنقّلوا مع المواسم وعاشوا قريبًا من البحر. وفي داخلها وُجدت خرز من الأحجار الكريمة وحُليّ من الأصداف وختم صغير منقوش، هدايا لرحلة إلى العالم الآخر.","na":"مقبرة تلال الصبية","t0":4926,"t1":3176},{"id":"stone-platforms","n":"Enigmatic Stone Platforms","c":"archaeological","s":"Ritual / Ceremonial Structures","lat":29.638,"lng":48.08,"p":"Bronze Age","dr":"3000–1500 BC (inferred from sea-level alignment)","el":"11.30–19.11 m a.s.l.","desc":"A survey in Al-Subiyah identified 21 linear stone platforms along 16 km of coastline, making them the second most common stone structures after tumuli. These platforms are typically 6–21 m long and less than 2 m wide, with rounded ends, flat tops, and a curb of vertical stone slabs. One end is often broader and rounded, while the other resembles a boat’s bow or parabolic tip, giving them a silhouette akin to a longboat or spearhead when viewed from above (Rutkowski & Kiersnowski, 2025).","sig":"Their deliberate seaward orientation — perpendicular to the ancient coastline — suggests they were built during the Bronze Age highstand when the sea was visible from their location. They may represent funerary biers, ceremonial podia, or eschatological symbols of passage to the afterlife, evoking Dilmun’s association with paradise in Sumerian mythology.","ex":"Kuwaiti-Polish Archaeological Mission (KPAM), 7 excavated by KPAM, 2 by Kuwaiti/GCC teams","conf":"","ev":"","an":"","val":"","disc":["Boat-Shaped Silhouette: Elongated platforms with a distinct ‘bow end’ and broader ‘stern end’, resembling longboats when viewed from above — possibly symbolizing the passage to the afterlife.","Sunrise-Sunset Orientation: In the Bahra micro-region, five platforms are aligned east-west with the narrow end pointing westward, possibly reflecting afterlife beliefs.","Fan-Like Coastal Arrangement: Elsewhere, platforms follow a fan-like arrangement perpendicular to the former shoreline, with narrow ends facing the sea.","Association with Tumuli: Often found near tumuli, suggesting functional, ritual, or symbolic associations between the two types of structures.","Boat-shaped stone platforms oriented toward the ancient shoreline","Unique to Kuwait Bay with no parallels elsewhere","Possible ritual or navigational function","Associated with the Bronze Age tumuli cemetery complex"],"refs":["Rutkowski, Ł. (2015). Excavation of Stone Platforms in Al-Subiyah. KPAM Reports","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Rutkowski, Ł. (2015). Bronze Age Funerary Landscapes of Northern Kuwait. Polish Centre of Mediterranean Archaeology"],"ic":"platform","era":"P","te":"Stone Boats Facing the Sea","ta":"قوارب من حجر تواجه البحر","se":"Long stone platforms shaped like boats point straight toward where the shoreline used to be. Nothing quite like them is known anywhere else. Were they places to lay the dead before their final voyage, stages for ceremonies, or markers for sailors? Nobody knows for sure, and that is part of their magic.","sa":"منصات حجرية طويلة على هيئة قوارب، تتجه كلها نحو المكان الذي كان فيه الشاطئ قديمًا. ولا يُعرف لها مثيل في أي مكان آخر. هل كانت مكانًا يُسجّى عليه الموتى قبل رحلتهم الأخيرة، أم مسرحًا لطقوس، أم علامات للبحّارة؟ لا أحد يعرف يقينًا، وهذا جزء من سحرها.","na":"المنصات الحجرية الغامضة","t0":5026,"t1":3526},{"id":"shell-midden-smq24","n":"Shell Midden SMQ 24 (Mughaira)","c":"archaeological","s":"Shell Processing Site","lat":29.643,"lng":48.02,"p":"Ubaid to Late Bronze Age","dr":"5000–1500 BC","el":"11.00–11.50 m a.s.l.","desc":"An isolated shell midden approximately 20×20 m, composed almost exclusively of Conus persicus shells, discovered at the base of Terrace A in the Mughaira area. The site served as a shell processing location for bead production. Nearby finds include Ubaid pottery fragments and flint pieces. KPAM discovered oval quartz pebbles among the shells, resembling the ‘chipped quartz industry’ identified at Bahra 1 and H3 (Rutkowski & Kiersnowski, 2025).","sig":"Radiocarbon dating yielded a surprisingly late date (Late Bronze Age), suggesting prolonged or intermittent use across different periods. Located 3 km NW of H3 and 5.7 km east of Bahra 1, at a comparable elevation, suggesting potential existence of other Ubaid-period sites along the prehistoric coastline.","ex":"Kuwaiti team (discovery), KPAM (subsequent investigation)","conf":"","ev":"","an":"","val":"","disc":["Conus persicus Shell Concentration: Thousands of C. persicus shells — the raw material for ancient bead production — concentrated in a 20×20 m area.","Oval Quartz Pebbles: Whole, halved, or fragmented quartz pebbles resembling the ‘chipped quartz industry’ from Bahra 1 and H3, supporting the bead production hypothesis.","Ubaid Pottery Fragment: A fragment of Ubaid pottery found nearby, potentially linking the midden to the Ubaid-period settlements.","Stratified shell deposits indicating multiple occupation phases","Evidence of systematic shellfish harvesting","Associated stone tools and pottery fragments","Shell bead production workshop evidence"],"refs":["Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Kozłowski, S.K. & Białowarczuk, M. (2023). Chipped Quartz Industry from Bahra 1 and H3. KPAM Publications","Carter, R. & Crawford, H. (2010). Maritime Interactions in the Arabian Neolithic. Brill"],"ic":"shell","era":"P","te":"The Ancient Seafood Feast","ta":"وليمة البحر القديمة","se":"This mound is made of shells, the leftovers of countless meals eaten on the shore. Layer by layer it tells you what people ate, which season they came, and how they gathered food from the sea. They kept coming back for thousands of years, from the age of the first villages to the Bronze Age.","sa":"هذه التلة مكوّنة من الأصداف، بقايا وجبات لا تُحصى أُكلت على الشاطئ. طبقة بعد طبقة تخبرك بما أكله الناس، وفي أي موسم جاؤوا، وكيف جمعوا طعامهم من البحر. وقد ظلوا يعودون إليها آلاف السنين، من عصر القرى الأولى حتى العصر البرونزي.","na":"كومة الأصداف SMQ 24","t0":7026,"t1":3526},{"id":"coastal-wells","n":"Coastal Wells (SM 12 & SB 23)","c":"archaeological","s":"Early Islamic Infrastructure","lat":29.635,"lng":48.12,"p":"Early Islamic","dr":"7th–9th century AD","el":"SM 12: 6.80–3.70 m; SB 23: 5.80–2.25 m a.s.l.","desc":"Two stone-lined wells along the Al-Subiyah coast, part of a larger network of wellstations along a coastal communication route. SM 12 in Muhaita lies in the path of a wadi from Terrace B; SB 23 in Dubaij lies at the foot of Terrace A. Both feature durable stone linings and auxiliary features (descending steps in SM 12, a water-lifting column in SB 23). Their low elevations indicate they could only function after significant sea regression, placing their construction in the Early Islamic period (Rutkowski & Kiersnowski, 2025).","sig":"Part of a trade or pilgrimage route network extending from Dubaij to Muhaita to Mudaira and Kadhima (30 km further west). The wells’ construction coincides with the rise of Islam and the hajj pilgrimage, possibly serving an alternative coastal route to the main Darb Zubaydah.","ex":"Kuwaiti-Polish Archaeological Mission (KPAM)","conf":"","ev":"","an":"","val":"","disc":["Well SM 12 (Muhaita): Stone-lined well with descending steps, positioned in a wadi path to collect rainwater runoff. Remained in use until recent times with modern renovations.","Well SB 23 (Dubaij): Well complex with a water-lifting column and an elongated stone pavement — possibly a large animal drinking trough similar to those found in Kadhima.","Trade Route Evidence: The wells form a network of designated well-stations along a coastal route, with Kadhima (5 animal troughs) as a caravan hub.","Wells dug into beach rock during Early Islamic period ( 7th–9th century AD)","Became functional after major sea retreat 1,200 years ago","Evidence of fresh groundwater access following coastline regression","Latest phase of human activity in Al-Subiyah"],"refs":["Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Kennet, D. (2014). Kadhima: Kuwait in the Early Centuries of Islam. National Council for Culture, Arts and Letters, Kuwait / Durham University","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269"],"ic":"well","era":"H","te":"Wells of the Retreating Sea","ta":"آبار البحر المنحسر","se":"About 1,200 years ago the sea pulled back and fresh water appeared under the beach. Travellers dug wells straight into the beach rock. They may have watered caravans and pilgrims following a coastal route, hopping from well to well toward the head of the bay.","sa":"قبل نحو 1,200 عام انحسر البحر وظهرت المياه العذبة تحت الشاطئ. فحفر المسافرون آبارًا في صخر الشاطئ مباشرة. ولعلها سقت القوافل والحجاج على طريق ساحلي، ينتقلون من بئر إلى بئر حتى رأس الجون.","na":"آبار ساحلية","t0":1426,"t1":1126},{"id":"torpedo-jar-scatters","n":"Torpedo Jar Pottery Scatters","c":"archaeological","s":"Late Pre-Islamic Maritime Trade","lat":29.62,"lng":48.22,"p":"Parthian / Sasanian / Early Islamic","dr":"1st–7th century AD","el":"4.10–4.60 m a.s.l. (RS 8)","desc":"Fragments of torpedo jars — elongated storage vessels widely used in the Parthian, Sasanian, and Early Islamic periods in Iraq and southwestern Iran — found scattered along the northern coast of Kuwait Bay from Kadhima in the west to Ras al-Subiyah in the east. These containers were distributed across the western Indian Ocean by sea and discarded after use along former beach strandlines (Rutkowski & Kiersnowski, 2025).","sig":"Evidence of interactions between Mesopotamian seafaring traders and local communities during the late pre-Islamic era. Ceramic analysis indicates at least some jars date to the 5th–6th centuries AD, suggesting the coastline remained accessible until the end of the Sasanian period.","ex":"","conf":"","ev":"","an":"","val":"","disc":["RS 7, RS 10, RS 11 Pottery Scatters: Multiple sites surveyed by KPAM along former beach strandlines in the Ras al-Subiyah area, containing torpedo jar fragments.","RS 8 Stone Mound: A stone mound at 4.10–4.60 m a.s.l. on the same coastal strip as the pottery scatters, possibly a navigation marker.","Sasanian-Period Ceramics: At least some torpedo jars date to the 5th–6th centuries AD, indicating the coastline was still accessible during the Sasanian period.","Torpedo-shaped pottery — standard shipping containers of the Parthian/Sasanian era","Evidence of active maritime trade route along Kuwait Bay","Used to transport wine, oil, and commodities","Confirms late pre-Islamic maritime activity"],"refs":["Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Blair, A., Kennet, D. & Al-Duwīsh, S. (2012). Investigating an Early Islamic Landscape on Kuwait Bay. Proceedings of the Seminar for Arabian Studies, 42, 13–26","Kennet, D. (2007). The Decline of Eastern Arabia in the Sasanian Period. Arabian Archaeology and Epigraphy, 18(1), 86–122"],"ic":"jar","era":"H","te":"Jars of the Merchant Ships","ta":"جرار السفن التجارية","se":"Scattered along the shore lie broken pieces of long, pointed jars. Nearly two thousand years ago these were the shipping containers of the Gulf, packed with wine, oil and goods. Each shard is a sign that trading ships once pulled up on this coast.","sa":"تتناثر على الساحل كسرات جرار طويلة مدببة. قبل نحو ألفي عام كانت هذه حاويات الشحن في الخليج، تُملأ بالخمر والزيت والبضائع. وكل كسرة منها علامة على أن سفن التجارة رست يومًا على هذا الساحل.","na":"مواقع جرار الطوربيد","t0":2025,"t1":1426},{"id":"kadhima","n":"Kadhima (Kazma)","c":"archaeological","s":"Early Islamic Caravan Hub","lat":29.3929,"lng":47.6713,"p":"Early Islamic / Prehistoric","dr":"Late 7th – mid-9th century AD (also prehistoric remains)","el":"","desc":"Kadhima is an Early Islamic settlement located near the western corner of Kuwait Bay. Kennet (2014) documented five animal troughs here, suggesting its role as a caravan hub. Early Islamic settlements dated between the late 7th and mid-9th century AD align with habitation remains in the Mughaira region. The site sits on a potential alternative coastal pilgrimage route to the main Darb Zubaydah (Rutkowski & Kiersnowski, 2025).","sig":"A key waypoint on ancient caravan trade routes connecting southern Arabia to Mesopotamia. The discovery of a similar well here reinforces the concept of an interconnected network of well-stations along the Al-Subiyah coast.","ex":"British mission (Kennet, 2014); NCCAL, Kuwait","conf":"","ev":"","an":"","val":"","disc":["Prehistoric Skeleton: The first full prehistoric skeleton found in Kuwait, excavated in 2002 from one of three graves at the site.","Five Animal Troughs: Large stone troughs for watering caravan animals, confirming Kadhima’s role as a major rest stop (Kennet, 2014).","Early Islamic Settlements: Remains dated to the late 7th–mid-9th century AD, coinciding with the rise of Islam and the hajj pilgrimage.","Site of the Battle of Dhat al-Salasil (630 AD)","Major pre-Islamic trading port at the head of Kuwait Bay","Strategic location where freshwater springs meet the sea","Evidence of continuous occupation from pre-Islamic through Early Islamic periods"],"refs":["Kennet, D. (2014). Kadhima: Kuwait in the Early Centuries of Islam. National Council for Culture, Arts and Letters, Kuwait / Durham University","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Al-Jassar, H. (2009). Kadhima: A Historical and Archaeological Study. Kuwait National Museum Publications"],"ic":"caravan","era":"H","te":"The Caravan Gateway","ta":"بوابة القوافل","se":"Where springs of fresh water meet the sea at the head of the bay, caravans from southern Arabia stopped to rest before heading north. Explorers found stone troughs where animals drank, traces of early Islamic villages, and even a skeleton far older than all of it.","sa":"حيث تلتقي ينابيع الماء العذب بالبحر عند رأس الجون، كانت القوافل القادمة من جنوب الجزيرة العربية تتوقف للراحة قبل أن تمضي شمالًا. وُجدت هنا أحواض حجرية لسقي الدواب، وآثار قرى إسلامية مبكرة، بل وهيكل عظمي أقدم من ذلك كله.","na":"كاظمة","t0":1350,"t1":1176},{"id":"failaka-island","n":"Failaka Island","c":"archaeological","s":"Multi-Period Island","lat":29.45,"lng":48.33,"p":"Bronze Age to Islamic","dr":"3000 BC – 17th century AD","el":"","desc":"Failaka Island lies approximately 20 km off the Kuwaiti mainland in the Arabian Gulf. It contains some of the richest and most diverse archaeological remains in the Gulf region, spanning from the Bronze Age Dilmun civilization through the Hellenistic period to Late Islamic fishing settlements.","sig":"A key node in the Dilmun trade network and later a Hellenistic outpost connected to Alexander the Great’s campaigns; nominated for UNESCO World Heritage status.","ex":"Danish, French, Italian, Kuwaiti-Polish, and Kuwaiti-Georgian expeditions (1958–present)","conf":"","ev":"","an":"","val":"","disc":["Dilmun Bronze Age Town: The Sa’ad and Sae’ed area contains extensive Dilmun-period remains including temples, residential areas, and stamp seals — on the UNESCO Tentative List.","Hellenistic Buildings: The Al-Qurainiya site yielded Hellenistic courtyard buildings and Greek inscriptions, evidence of the island’s role in Alexander’s eastern campaigns.","Dilmun Stamp Seals: Numerous stamp seals with depictions of local wildlife including gazelles, connecting to the broader Dilmun trade network.","Late Islamic Fishing Settlement: Kharaib el-Desht on the northwestern coast reveals a Late Islamic fishing community with a recently discovered mosque.","Dilmun Temple Complex with stamp seals and cuneiform inscriptions","Greek Fortress (Ikaros) with Greek inscriptions from Alexander’s campaigns","Dilmun Stamp Seals with distinctive Gulf-style iconography","Evidence of continuous occupation spanning 4,000 years"],"refs":["Bibby, G. (1970). Looking for Dilmun. Knopf, New York","Calvet, Y. & Pic, M. (1986). Un bâtiment Hellénistique à Failaka. Travaux de la Maison de l’Orient, 12, 277–298","Potts, D.T. (1990). The Arabian Gulf in Antiquity. Oxford: Clarendon Press"],"ic":"island","era":"P","te":"The Island of Four Thousand Years","ta":"جزيرة الأربعة آلاف عام","se":"Twenty kilometres out to sea, this island has welcomed people for about four thousand years. Bronze Age traders built a temple and stamped their goods with carved seals. Later, Greek soldiers raised a fortress and called the island Ikaros. Fishing villages followed. Few places in the Gulf hold so many layers of history in one spot.","sa":"على بُعد عشرين كيلومترًا في البحر، استقبلت هذه الجزيرة البشر نحو أربعة آلاف عام. بنى تجار العصر البرونزي معبدًا وختموا بضائعهم بأختام منقوشة. ثم شيّد جنود إغريق قلعة وأسموا الجزيرة إيكاروس، وتلتهم قرى الصيادين. قليلة هي الأماكن في الخليج التي تجمع كل هذه الطبقات من التاريخ.","na":"جزيرة فيلكا","t0":5026,"t1":326},{"id":"akkaz-island","n":"Akkaz (Shuwaikh Island)","c":"archaeological","s":"Dilmun Settlement","lat":29.3601,"lng":47.7835,"p":"Dilmun Period","dr":"4000–2000 BC","el":"","desc":"Akkaz, also known as Shuwaikh Island, is a former island within Kuwait Bay that has been connected to the mainland through land reclamation. It was recognized as an archaeological site in 1958 by the Danish mission and contains Dilmun-period remains.","sig":"Part of the Dilmun civilization’s network of settlements controlling Kuwait Bay; one of the earliest identified archaeological sites in Kuwait.","ex":"Danish Archaeological Mission (1958), subsequent Kuwaiti expeditions","conf":"","ev":"","an":"","val":"","disc":["Dilmun Period Remains: Archaeological evidence of Dilmun-era occupation, including pottery and structural remains.","Danish Mission Discovery: First identified as an archaeological site in 1958 during the pioneering Danish archaeological expedition to Kuwait.","Dilmun-period remains 4000–2000 BC","Recognized in 1958 by the Danish mission","Former island now connected to mainland","Located within modern Shuwaikh industrial area"],"refs":["Glob, P.V. (1959). Archaeological Investigations in Four Arab States. Kuml, 9, 234–240","Bibby, G. (1970). Looking for Dilmun. Knopf, New York"],"ic":"island","era":"P","te":"The Island That Joined the Land","ta":"الجزيرة التي التحقت باليابسة","se":"This was once an island inside the bay, home to people of the ancient Dilmun world. Today it is joined to the mainland, but it was one of the very first archaeological sites ever recognised in Kuwait.","sa":"كانت يومًا جزيرة داخل الجون، يسكنها أناس من عالم دلمون القديم. واليوم صارت متصلة باليابسة، لكنها من أوائل المواقع الأثرية التي عُرفت في الكويت.","na":"جزيرة عكاز / الشويخ","t0":6026,"t1":4026},{"id":"umm-an-namil","n":"Umm an Namil Island","c":"archaeological","s":"Dilmun / Parthian Settlement","lat":29.3817,"lng":47.8669,"p":"Dilmun to Parthian","dr":"3000 BC – 3rd century AD","el":"","desc":"A small drumstick-shaped island in Kuwait Bay, approximately 57 hectares in area and rising only 2 meters above sea level. Umm an Namil contains multi-period archaeological remains spanning from the Dilmun civilization through the Parthian-Characene era.","sig":"Key island in the Dilmun trade network within Kuwait Bay; evidence of continuous occupation from the Bronze Age through the Parthian period.","ex":"Various Kuwaiti and international expeditions","conf":"","ev":"","an":"","val":"","disc":["Multi-Period Occupation: Archaeological layers spanning from the Dilmun period through the ParthianCharacene era, showing continuous habitation over millennia.","Parthian-Era Remains: Evidence of occupation during the Parthian period when the region was part of the Characene kingdom.","Multi-period remains spanning over 5,000 years","Dilmun through Parthian-Characene occupation","Strategic anchorage in Kuwait Bay","57 hectares, only 2 m above sea level"],"refs":["Patitucci, S. & Uggeri, G. (1984). Failakah: Insediamenti Medievali Islamici. Rome","Kennet, D. (2007). The Decline of Eastern Arabia in the Sasanian Period. Arabian Archaeology and Epigraphy, 18(1), 86–122"],"ic":"island","era":"P","te":"The Little Drumstick Island","ta":"الجزيرة الصغيرة","se":"Shaped like a drumstick and only two metres above the waves, this tiny island was a safe anchorage for sailors for thousands of years. Traders of the Bronze Age and later empires all left something behind.","sa":"جزيرة صغيرة على هيئة عصا الطبل، لا ترتفع عن الموج إلا مترين، كانت مرسى آمنًا للبحّارة آلاف السنين. وقد ترك فيها تجار العصر البرونزي ومن جاء بعدهم من الإمبراطوريات شيئًا من آثارهم.","na":"جزيرة أم النمل","t0":5026,"t1":1776},{"id":"bubiyan-island","n":"Bubiyan Island","c":"archaeological","s":"Delta Island / Historical","lat":29.783,"lng":48.183,"p":"Holocene","dr":"Late Holocene to present","el":"","desc":"The largest island in the Kuwaiti coastal chain at 863 km², Bubiyan is the westernmost lobe of the Shatt Al-Arab delta. This low-lying, isolated island developed during the Late Holocene and is characterized by extensive mudflats, tidal channels, and gypseous nabkha clusters.","sig":"Represents the active delta formation of the Tigris-Euphrates river system; Reinink-Smith & Carter (2022) suggest a sea-level stillstand on southeastern Bubiyan Island.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Holocene Delta Formation: Geological evidence of the island’s formation as part of the Shatt Al-Arab delta during the Late Holocene period.","Gypseous Nabkha Clusters: Distinctive wind-formed sand mounds cemented by gypsum along the southern coastal ridges.","Largest Kuwaiti island at 863 km²","Westernmost lobe of the Shatt Al-Arab delta","Extensive mudflats, tidal channels, gypseous nabkha","Still actively growing as the delta expands"],"refs":["Al-Zamel, A. & Al-Sarawi, M. (2002). Coastal Geomorphology of Kuwait. Kuwait University Press","Reinink-Smith, L.M. & Carter, R. (2022). Sea-Level Stillstand on Southeastern Bubiyan Island. Quaternary Research"],"ic":"delta","era":"N","te":"Gift of the Great Rivers","ta":"هدية النهرين العظيمين","se":"The biggest of Kuwait’s islands was built by rivers. Mud carried down by the Tigris and Euphrates settled here over the last few thousand years, forming a vast, flat land of mudflats, winding tidal channels and salty mounds.","sa":"أكبر جزر الكويت صنعتها الأنهار. فالطمي الذي حمله دجلة والفرات استقر هنا على مدى آلاف السنين الأخيرة، فتكوّنت أرض منبسطة واسعة من المسطحات الطينية والقنوات المدّية المتعرجة والتلال المالحة.","na":"جزيرة بوبيان","t0":4200,"t1":0},{"id":"kazma-shoreline","n":"Kazma 6k Shoreline Transition","c":"archaeological","s":"Paleo-Geography","lat":29.3912,"lng":47.762,"p":"Ubaid / Neolithic","dr":"6,000 BP","el":"","desc":"This coordinate marks the ‘6k Highstand’ — the exact position of the coastline 6,000 years ago when sea levels were approximately 2–3 meters higher than today. Recent excavations uncovered Ubaid-related bitumen-coated reed baskets, suggesting this was a port for ‘sea-faring Neolithic’ groups long before the Islamic period. The discovery of bitumen waterproofing technology indicates sophisticated maritime knowledge and trade connections with Mesopotamia.","sig":"Proves that the Jahra area was a maritime hub during the Neolithic period, with direct evidence of seafaring technology (bitumen-coated baskets) predating known Islamic-era ports by 5,000 years. Redefines the archaeological timeline of Kuwait’s western coast.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Bitumen-Coated Reed Baskets: Ubaid-period waterproofing technology for maritime containers","6k Highstand Shoreline: Precise mapping of the 6,000-year-old coastline position","Neolithic Port Evidence: Artifacts suggesting organized maritime trade at this location","Mid-Holocene ( 6,000 BP) shoreline position","Evidence of sea-level highstand","Critical for understanding settlement patterns","Paleo-shoreline indicators preserved in landscape"],"refs":["Carter, R. & Crawford, H. (2020). Maritime Communities of the Arabian Gulf: The Kazma Context. Proceedings of the Seminar for Arabian Studies","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269"],"ic":"wave","era":"P","te":"Where the Sea Used to Be","ta":"حيث كان البحر","se":"Six thousand years ago the sea reached much farther inland than it does today. This line marks that old shore. People here coated reed baskets with tar to make them waterproof, a sign that this coast was already a busy maritime place long before later ports.","sa":"قبل ستة آلاف عام كان البحر يمتد إلى الداخل أبعد بكثير مما هو عليه اليوم. وهذا الخط يرسم ذلك الشاطئ القديم. هنا طلى الناس سلال القصب بالقار لتصبح مانعة للماء، دليلًا على أن هذا الساحل كان مكانًا بحريًا نشطًا قبل الموانئ اللاحقة بزمن طويل.","na":"خط ساحل كاظمة القديم","t0":6000,"t1":6000},{"id":"smq-49-tomb","n":"SMQ 49 Family Tomb","c":"archaeological","s":"Bronze Age Burial","lat":29.639,"lng":47.925,"p":"Bronze Age","dr":"3000–2000 BC","el":"","desc":"A complex Bronze Age burial mound with internal chambers and equid (horselike) remains discovered by the Polish Centre of Mediterranean Archaeology (PCMA UW, 2024). Makowski (2010) documented the elaborate multi-chamber construction and the significance of equid burials, which indicate high social status and long-distance trade connections.","sig":"The presence of equid remains in a Bronze Age tomb suggests elite status and connections to horse-trading networks extending from Central Asia to the Gulf.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Multi-Chamber Tomb: Complex internal architecture indicating elaborate burial practices","Equid Remains: Horse-like animal bones suggesting elite status burial","Bronze Age Social Hierarchy: Tomb construction indicates stratified society in ancient Kuwait","Multi-chamber tomb with elaborate Bronze Age architecture","Equid (horse-like) remains indicating elite status burial","Evidence of stratified society in ancient Kuwait"],"refs":["PCMA UW (2024). Excavation Report: SMQ 49 Bronze Age Burial Complex. Polish Centre of Mediterranean Archaeology","Makowski, M. (2010). Bronze Age Burial Mounds of Northern Kuwait. Proceedings of the Seminar for Arabian Studies"],"ic":"mound","era":"P","te":"The Tomb of the Honoured Family","ta":"قبر العائلة الرفيعة","se":"Inside this mound are several rooms built for the dead, a sign that the family buried here was important. Beside them lay the bones of horse-like animals, rare treasures linked to trade routes that stretched as far as Central Asia.","sa":"داخل هذه التلة عدة غرف بُنيت للموتى، دليلًا على مكانة العائلة المدفونة هنا. وإلى جوارهم عظام حيوانات من فصيلة الخيل، كنوز نادرة ترتبط بطرق تجارة امتدت حتى آسيا الوسطى.","na":"مقبرة SMQ 49 العائلية","t0":5026,"t1":4026},{"id":"atraf-ancient-wells","n":"Al-Atraf Ancient Wells","c":"archaeological","s":"Hydro-Archaeology","lat":29.412,"lng":47.655,"p":"Pre-Islamic to Islamic","dr":"500 BC – 1800 AD","el":"","desc":"Hand-dug wells tapping into perched water tables within the Fars Formation clay lenses. Al-Mishwat (2021) documented how ancient communities exploited geological knowledge to locate freshwater trapped above impermeable clay layers, demonstrating sophisticated understanding of hydrogeology centuries before modern science.","sig":"Evidence of ancient hydrogeological knowledge — these wells demonstrate that pre-Islamic communities understood the concept of perched aquifers.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Perched Aquifer Exploitation: Wells targeted freshwater trapped above clay lenses","Ancient Hydrogeology: Pre-Islamic communities understood subsurface water flow","Fars Formation Water Sources: Clay layers in the Fars Formation create natural water traps","Wells targeted freshwater trapped above clay lenses","Pre-Islamic communities understood subsurface water flow","Fars Formation clay layers create natural water traps"],"refs":["Al-Mishwat, A.T. (2021). Ancient Water Management in Northern Kuwait. International Journal of Geosciences","Kuwait Heritage Society (2022). Traditional Wells of Kuwait: Archaeological Survey. KHS Technical Report"],"ic":"well","era":"H","te":"The Water Finders","ta":"باحثو الماء","se":"Long ago people knew where to dig. They found pockets of fresh water trapped above layers of clay and reached them with hand-dug wells. It is a quiet record of clever desert knowledge used for more than two thousand years.","sa":"منذ زمن بعيد عرف الناس أين يحفرون. اكتشفوا جيوبًا من الماء العذب محبوسة فوق طبقات الطين، فوصلوا إليها بآبار حفروها بأيديهم. إنه سجل هادئ لمعرفة صحراوية ذكية استُخدمت أكثر من ألفي عام.","na":"آبار العطرف القديمة","t0":2526,"t1":226},{"id":"ghanim-paleochannel","n":"Ghanim Paleochannel","c":"archaeological","s":"Hydro-Archaeology","lat":29.6,"lng":48.05,"p":"Ubaid – Bronze Age","dr":"6000–2000 BC","el":"","desc":"A buried river channel that provided the freshwater supply for the Ubaid settlers at Bahra 1. Bielinski (2021) and Hansman (1978) documented this paleochannel as the critical water source that made permanent settlement possible in the otherwise arid Al-Subiyah region, connecting geological water resources to archaeological settlement patterns.","sig":"Solves the mystery of how Ubaid settlers survived in the desert — this buried river provided the freshwater that sustained Kuwait’s earliest civilization.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Buried River Channel: Ancient freshwater source hidden beneath desert sediments","Ubaid Settlement Water Supply: Explains how Bahra 1 settlers obtained freshwater","Hydro-Archaeological Connection: Links geological water resources to human settlement patterns","Buried river channel beneath desert sediments","Freshwater source enabling Bahra 1 settlement","Links geological water resources to human settlement patterns"],"refs":["Bielinski, P. (2021). Water Sources and Settlement Patterns at Bahra 1. Polish Centre of Mediterranean Archaeology","Hansman, J. (1978). The Ancient Water Supply of Kuwait. Journal of the Royal Asiatic Society"],"ic":"river","era":"P","te":"The Hidden River","ta":"النهر الخفي","se":"How did the first villagers survive in the desert? Beneath the sand runs a buried river channel. Its fresh water may have kept the shell-carving village alive seven thousand years ago.","sa":"كيف عاش أوائل القرويين في الصحراء؟ تحت الرمال تجري قناة نهر مدفونة. ولعل ماءها العذب هو ما أبقى قرية صانعي الأصداف حيّة قبل سبعة آلاف عام.","na":"القناة القديمة في غانم","t0":8026,"t1":4026},{"id":"faydhat-nayif-smelter","n":"Faydhat Nayif Smelter","c":"archaeological","s":"Industrial Archaeology","lat":29.664,"lng":47.881,"p":"Islamic Period","dr":"8th–12th century AD","el":"","desc":"An Islamic-era industrial site featuring iron slag heaps and stone gallery foundations. Al-Mishwat (2021) documented this smelting facility where iron ore was processed using local fuel sources, providing evidence of medieval industrial activity in Kuwait’s desert interior.","sig":"Evidence of medieval industrial activity in Kuwait — iron smelting required sophisticated technology, fuel management, and trade networks.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Iron Slag Heaps: Large accumulations of smelting waste indicating sustained industrial activity","Stone Gallery Foundations: Structural remains of the smelting facility","Medieval Industry: Evidence of sophisticated metallurgical technology in Islamic-era Kuwait","Iron slag heaps indicating sustained industrial smelting","Stone gallery foundations of the smelting facility","Evidence of sophisticated medieval metallurgical technology"],"refs":["Al-Mishwat, A.T. (2021). Islamic-Era Industrial Sites in Northern Kuwait. International Journal of Geosciences","GCC Archaeology (2020). Medieval Industrial Sites of the Arabian Gulf. GCC Archaeological Survey"],"ic":"flame","era":"H","te":"The Iron Furnaces","ta":"أفران الحديد","se":"A thousand years ago fires roared here. Heaps of iron slag and stone foundations show that people smelted metal in the desert, a job that needed skill, fuel and trade to keep going.","sa":"قبل ألف عام كانت النيران تتأجج هنا. أكوام من خبث الحديد وأساسات حجرية تدل على أن الناس صهروا المعدن في الصحراء، وهي مهنة احتاجت إلى مهارة ووقود وتجارة كي تستمر.","na":"مصهر فيضة نايف","t0":1326,"t1":826},{"id":"kazima-battle-site","n":"Kazima Battle Site","c":"archaeological","s":"Islamic Military History","lat":29.38,"lng":47.75,"p":"Early Islamic","dr":"633 AD","el":"","desc":"The location of the 633 AD Battle of the Chains (Dhat al-Salasil), where the Muslim general Khalid ibn al-Walid defeated the Sasanian Persian army. Donner (1981) documented how the escarpment acted as a strategic funnel, channeling the Persian forces into a disadvantageous position. This was the first major battle of the Islamic conquest of Mesopotamia.","sig":"One of the most significant battles in Islamic history — the first major victory that opened the path to the conquest of the Sasanian Empire.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Battle of the Chains: 633 AD clash between Muslim and Sasanian forces","Strategic Escarpment: Natural terrain funneled Persian forces into a trap","Islamic Conquest Gateway: First major victory leading to the fall of the Sasanian Empire","Battle of the Chains (Dhat al-Salasil) 633 AD","Natural terrain used as strategic military funnel","First major victory of the Islamic conquest of Mesopotamia"],"refs":["Donner, F.M. (1981). The Early Islamic Conquests. Princeton University Press","Kuwait Heritage Society (2022). Historical Battlefields of Kuwait. KHS Technical Report"],"ic":"sword","era":"H","te":"The Battle of the Chains","ta":"معركة ذات السلاسل","se":"In 633 AD the landscape itself shaped history. The slope of the escarpment funnelled armies together in one of the first great battles of the Islamic conquests, a victory that opened the road north.","sa":"في عام 633م صنعت الأرض نفسها التاريخ. فقد جمع انحدار الجرف الجيوش في ممر واحد، في واحدة من أولى المعارك الكبرى في الفتوحات الإسلامية، وكان النصر فيها فاتحة الطريق نحو الشمال.","na":"موقع معركة كاظمة","t0":1393,"t1":1393},{"id":"subbiya-desert-wall","n":"Subbiya Desert Wall","c":"archaeological","s":"Early Islamic / Territorial","lat":29.65,"lng":48.0,"p":"Early Islamic","dr":"7th–9th century AD","el":"","desc":"A long, linear stone feature thought to be an Early Islamic territorial marker, sometimes compared to Jordan’s Khatt Shebib. Ibn Seray (2000) and PCMA UW (2009) documented this enigmatic wall stretching across the desert, possibly marking tribal boundaries, controlling animal movement, or serving as a route marker for caravans.","sig":"One of Kuwait’s most mysterious archaeological features — its exact purpose remains debated, but it demonstrates organized territorial control in the Early Islamic period.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Linear Stone Feature: Extends for kilometers across the desert landscape","Territorial Marker: Possibly marking tribal boundaries or grazing rights","Caravan Route Marker: May have guided travelers along the coastal trade route","Linear stone feature extending kilometers across the desert","Possibly marking tribal boundaries or grazing rights","May have guided caravans along the coastal trade route"],"refs":["Ibn Seray, H. (2000). Linear Stone Features of the Subiyah Region. Kuwait National Museum","PCMA UW (2009). Archaeological Survey of the Al-Subiyah Desert. Polish Centre of Mediterranean Archaeology 3 Geological Features This section contains 33 Kuwait record(s)."],"ic":"wall","era":"H","te":"The Wall Across the Sand","ta":"الجدار العابر للرمال","se":"A line of stones runs for kilometres across the desert. Was it a border, a guide for caravans, or a mark of grazing land? More than a thousand years later, it is still one of Kuwait’s great puzzles.","sa":"خط من الحجارة يمتد كيلومترات عبر الصحراء. هل كان حدًّا، أم دليلًا للقوافل، أم علامة لأراضي الرعي؟ بعد أكثر من ألف عام ما زال من أكبر ألغاز الكويت.","na":"جدار الصبية الصحراوي","t0":1426,"t1":1126},{"id":"jal-az-zor","n":"Jal Az-Zor Escarpment","c":"geological","s":"Escarpment / Tectonic Uplift","lat":29.55,"lng":47.85,"p":"Miocene (with Quaternary uplift)","dr":"23–5 Ma (marine deposits at 40 ka and 30 ka)","el":"","desc":"The Jal Az-Zor escarpment is the most prominent rock exposure in Kuwait, trending NE-SW for over 60 km along the northern side of Kuwait Bay, reaching up to 36 m in height. It exposes the Lower Fars Formation from the Lower to Middle Miocene. Rutkowski & Kiersnowski (2025) report marine deposits aged 40 ka and 30 ka now found 10–30 m above sea level, indicating significant tectonic uplift. Amer & Al-Hajeri (2020) demonstrated the escarpment is a product of complex duplex folding and strike-slip tectonics.","sig":"The most pronounced geological feature in Kuwait. Tectonic uplift rates of 1.72–2.64 mm/ yr in the Bahra area (driven by the Bahra anticline and Precambrian Hormuz salt tectonics) have raised marine deposits far above their original position, complicating sea-level reconstructions.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Lower Fars Formation Exposure: The largest outcrop of the Lower Fars Formation in Kuwait, revealing Miocene-era sedimentary sequences.","Duplex Folding & Strike-Slip Tectonics: Complex geological folding and strike-slip faulting created the escarpment (Amer & Al-Hajeri, 2020).","Uplifted Marine Deposits: Marine deposits aged 40 ka and 30 ka found 10–30 m above sea level, evidence of rapid tectonic uplift (Rutkowski & Kiersnowski, 2025).","Terraces A and B: Two stepped terraces oriented NW-SE, gradually decreasing in elevation eastward, serving as the framework for archaeological site distribution.","Polychrome geological exposure revealing millions of years of Earth history","Tilted strata and unconformities showing tectonic deformation","Miocene-age Fars/Ghar Formation exposures","Evidence of Zagros fold-thrust belt influence on Kuwait geology"],"refs":["Amer, A. & Al-Hajeri, M. (2020). The Jal Az-Zor Escarpment as a Product of Complex Duplex Folding and Strike-Slip Tectonics. Journal of Structural Geology, 135, 104024. DOI: 10.1016/j.jsg.2020.104024","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Behbehani, S. et al. (2019). Bahrah Field: Hydrothermal Dolomite, Faults, and Basement Coupling in Kuwait. GeoArabia, 24(4), 135–164","Khalaf, F.I. (2011). Quaternary Geology of Kuwait. Kuwait University Press","Milton, D.I. (1967). Geology of the Arabian Peninsula: Kuwait. USGS Professional Paper 560-F"],"ic":"cliff","era":"D","te":"The Great Cliff","ta":"الجرف العظيم","se":"Kuwait’s most dramatic landform rises 145 metres above the bay. Its cliff face is striped in many colours, each band a chapter of Earth’s story written over millions of years. Slow forces deep underground are still lifting it, raising old sea beds high into the air.","sa":"أبرز تضاريس الكويت يرتفع 145 مترًا فوق الجون. واجهته مخططة بألوان كثيرة، وكل شريط منها فصل من قصة الأرض كُتب على مدى ملايين السنين. وما زالت قوى بطيئة في باطن الأرض ترفعه، حاملةً قيعان بحار قديمة إلى الأعالي.","na":"جال الزور","t0":23000000.0,"t1":5000000.0},{"id":"mud-volcano-z1","n":"Mud Volcano Zone 1 (Z1) — NW Cluster","c":"geological","s":"Mud Volcano Complex — Zone 1","lat":29.6233,"lng":48.02,"p":"Miocene–Quaternary","dr":"20 Ma to present (reactivated)","el":"","desc":"The northwestern zone of the Al-Subiyah mud volcano seep complex (MVSC), mapped by Duane et al. (2015) at approximately 29°37.4′N, 48°01.2′E. Z1 contains the most concentrated cluster of mud volcanoes along the coast, situated on the upper tidal flat surface adjacent to remnant flood channels. Features include small craters, abundant gypsum deposits, and skeletal marine fossils. Bedding dip measurements of 10°–60° indicate significant deformation. The zone preserves evidence of focused brine ascent through unconsolidated sediments.","sig":"The densest concentration of mud volcanoes in the Al-Subiyah complex, with the strongest evidence for repeated seepage events. The association with remnant flood channels suggests fluid pathways were controlled by pre-existing drainage patterns.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Dense Mud Volcano Cluster: The highest concentration of mud volcanoes in the MVSC, with multiple overlapping craters and mounds indicating repeated eruption cycles.","Gypsum Deposits: Abundant gypsum crystals and crusts precipitated from hypersaline brines expelled during mud volcano activity.","Skeletal Marine Fossils: Shallow marine fossils entrained in mud volcano ejecta, indicating the source sediments were originally deposited in a marine environment.","Steep Bedding Dips (10°–60°): Highly deformed bedding around vents, with dip angles up to 60° — far exceeding normal depositional angles, confirming forceful fluid injection.","Most active mud volcano zone in Kuwait Bay","Pressurized subsurface fluid emissions along fault planes","Indicators of active tectonic processes","Potential hydrocarbon seepage evidence"],"refs":["Duane, M.J. et al. (2015). Mud Volcanoes, Seismites, and Other Features of Soft-Sediment Deformation in Coastal Sabkhas, Kuwait. Arabian Journal of Geosciences, 8, 1169–1186. DOI: 10.1007/s12517-013-1236-3","Reinink-Smith, L.M. (2015). Mud volcanoes and evaporite seismites in a tidal flat of northern Kuwait. Sedimentary Geology"],"ic":"mudvolc","era":"D","te":"Where the Earth Bubbles","ta":"حيث تغلي الأرض","se":"Here the ground breathes. Pressure deep below pushes gas, water and mud up through cracks, building little cones and craters. This is the busiest cluster of mud volcanoes on the coast, and they have erupted again and again.","sa":"هنا تتنفس الأرض. ضغط عميق يدفع الغاز والماء والطين عبر الشقوق، فتتشكل مخاريط وفوهات صغيرة. وهذه أنشط مجموعة من البراكين الطينية على الساحل، وقد ثارت مرة بعد مرة.","na":"منطقة البراكين الطينية 1 — الشمالية الغربية","t0":20000000.0,"t1":0},{"id":"mud-volcano-z2","n":"Mud Volcano Zone 2 (Z2) — Central Tidal Flat","c":"geological","s":"Mud Volcano Complex — Zone 2","lat":29.6167,"lng":48.025,"p":"Holocene","dr":"10,000 years ago to present","el":"","desc":"The central zone of the MVSC, mapped by Duane et al. (2015) at approximately 29°37.0′N, 48°01.5′E. Z2 occupies the Holocene tidal flat between Z1 and Z3, characterized by medium-sized craters, mound formations, and large seismites. A suspected faulted contact runs diagonally (NE–SW) through this zone, separating it from Z3 to the southeast. Bedding measurements (5°–44°) show variable deformation. The zone transitions from tidal flat sediments to a wind-deflated surface inland.","sig":"Z2 provides the critical link between the older Z1/Z3 features and active Holocene processes. The faulted contact cutting through this zone suggests ongoing tectonic control on fluid migration, and the seismites here are among the best-preserved earthquake records in soft sediments worldwide.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Large Seismites: Spectacular soft-sediment deformation structures formed by earthquake-triggered liquefaction — some of the best-preserved examples in the Arabian Gulf region.","Suspected Faulted Contact: A diagonal (NE–SW) structural discontinuity mapped by Duane et al. separating Z2 from Z3, suggesting active tectonic control on the distribution of deformation features.","Medium-Sized Craters & Mounds: Intermediate-scale eruption features between the small Z1 craters and the large Z3 craters, suggesting a gradient in subsurface pressure.","Variable Bedding Dips (5°–44°): Wide range of deformation intensities within a single zone, indicating multiple episodes of fluid injection at different pressures.","Mud volcanoes in intertidal sabkha environment","Interaction between tidal processes and fluid emissions","Unique geomorphological features","Evidence of subsurface gas migration"],"refs":["Duane, M.J. et al. (2015). Mud Volcanoes, Seismites, and Other Features of Soft-Sediment Deformation in Coastal Sabkhas, Kuwait. Arabian Journal of Geosciences, 8, 1169–1186. DOI: 10.1007/s12517-013-1236-3"],"ic":"mudvolc","era":"N","te":"Craters on the Tidal Flat","ta":"فوهات على المسطح المدّي","se":"Out on the salty flats, where the tide comes and goes, mud volcanoes rise from the sand. The layers here also hold some of the clearest records of ancient earthquakes preserved anywhere in soft ground.","sa":"على المسطحات المالحة حيث يأتي المد ويذهب، ترتفع براكين طينية من الرمل. وتحفظ الطبقات هنا أيضًا بعضًا من أوضح سجلات الزلازل القديمة المحفوظة في الأرض الرخوة.","na":"منطقة البراكين الطينية 2 — السبخة المركزية","t0":10000.0,"t1":0},{"id":"mud-volcano-z3","n":"Mud Volcano Zone 3 (Z3) — SE Marine Terrace","c":"geological","s":"Mud Volcano Complex — Zone 3","lat":29.605,"lng":48.0333,"p":"Quaternary","dr":"Pleistocene–Holocene","el":"","desc":"The southeastern zone of the MVSC, mapped by Duane et al. (2015) at approximately 29°36.3′N, 48°02.0′E. Z3 sits on the Quaternary marine terrace — older, more consolidated substrate than the Holocene tidal flat of Z2. This zone contains the largest craters, giant seismites, and distinctive polygonal fracture patterns. Bedding dips reach 60° and bioturbation zones are present nearby. Prominent remnant flood channels cut through the zone, and the dense fish-scale pattern of mud volcano features indicates the most intense subsurface fluid activity in the entire complex.","sig":"Z3 represents the most powerful expressions of subsurface fluid dynamics in the MVSC. The giant seismites and polygonal fractures indicate extreme pore-pressure events, possibly linked to major seismic episodes. Its position on the Quaternary marine terrace means these features have been preserved for tens of thousands of years.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Giant Seismites: The largest soft-sediment deformation structures in the MVSC — massive contorted layers recording powerful seismic events that liquefied the entire sediment column.","Polygonal Fracture Networks: Distinctive geometric fracture patterns formed by desiccation and dewatering of mud volcano ejecta, indicating repeated cycles of eruption and drying.","Large Craters (>2 m diameter): The biggest eruption craters in the complex, formed by violent upward expulsion of fluidized sediment during major seismic or pressure events.","Remnant Flood Channels: Ancient drainage channels that cut through the mud volcano field, suggesting the features pre-date or were contemporaneous with major flooding events.","Bioturbation Zones: Areas of biological reworking adjacent to the mud volcanoes, indicating that organisms colonized the margins of the volcanic field between eruption events.","Both active and dormant mud volcanic features","Temporal variability of subsurface fluid emissions","Southernmost mud volcano zone on Al-Subiyah coast","Evidence of episodic eruption cycles"],"refs":["Duane, M.J. et al. (2015). Mud Volcanoes, Seismites, and Other Features of Soft-Sediment Deformation in Coastal Sabkhas, Kuwait. Arabian Journal of Geosciences, 8, 1169–1186. DOI: 10.1007/s12517-013-1236-3","Reinink-Smith, L.M. (2015). Mud volcanoes and evaporite seismites in a tidal flat of northern Kuwait. Sedimentary Geology"],"ic":"mudvolc","era":"D","te":"The Giant Craters","ta":"الفوهات العملاقة","se":"The most powerful of the mud volcano zones. Craters wider than two metres and huge folded layers show moments when pressure underground became extreme, perhaps during great earthquakes.","sa":"أقوى مناطق البراكين الطينية. فوهات يزيد عرضها على مترين وطبقات ضخمة مطويّة تكشف لحظات بلغ فيها الضغط تحت الأرض أقصاه، ربما خلال زلازل عظيمة.","na":"منطقة البراكين الطينية 3 — المصطبة البحرية الجنوبية الشرقية","t0":2580000.0,"t1":0},{"id":"khor-subiyah","n":"Khor Al-Subiyah","c":"geological","s":"Tidal Channel / Ancient River","lat":29.6,"lng":48.2,"p":"Holocene / Ancient","dr":"Active since antiquity","el":"","desc":"A long tidal channel stretching approximately 60 km in length and 1.5 km in width, separating the Kuwait mainland from Bubiyan Island. In antiquity, this channel served as the outlet of the Euphrates River into the Arabian Gulf.","sig":"The ancient channel through which the Euphrates River flowed into the Arabian Gulf during the time of Alexander the Great; Failaka Island was located 15 km from its mouth.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Ancient Euphrates Outlet: Geological and historical evidence confirming this was the Euphrates River’s outlet to the Gulf during the 4th century BC.","Tidal Geomorphology: Active tidal processes creating distinctive coastal landforms and sedimentary deposits.","Major tidal inlet with strong currents","Extensive mudflats and mangrove-fringed channels","Critical nursery habitat for fish and shrimp","Dynamic sediment transport system"],"refs":["Aqrawi, A.A.M. (2001). Stratigraphic Signatures of Climatic Change during the Holocene Evolution of the Tigris-Euphrates Delta. Global and Planetary Change, 28, 267–283","Potts, D.T. (1990). The Arabian Gulf in Antiquity. Oxford: Clarendon Press","Al-Zamel, A. & Al-Sarawi, M. (2002). Coastal Geomorphology of Kuwait. Kuwait University Press"],"ic":"river","era":"N","te":"The Lost River Mouth","ta":"مصبّ النهر المفقود","se":"This strong tidal channel between the coast and Bubiyan was once where a great river poured into the Arabian Gulf. Today its mudflats and channels are a nursery where young fish and shrimp grow up.","sa":"هذه القناة المدّية القوية بين الساحل وبوبيان كانت يومًا مصبّ نهر عظيم في الخليج العربي. واليوم صارت مسطحاتها وقنواتها حضانة تكبر فيها صغار الأسماك والروبيان.","na":"خور الصبية","t0":6000,"t1":0},{"id":"coastal-sabkha","n":"Kuwait Bay Coastal Sabkha","c":"geological","s":"Evaporitic Coastal Flat","lat":29.5,"lng":47.9,"p":"Holocene","dr":"10,000 years ago to present","el":"","desc":"Extensive hypersaline coastal flats surrounding Kuwait Bay, characterized by evaporitic mineral deposits. Khalaf & Al-Zamel (2014) documented multiple gypcrete types — massive crusts, gypsum roses, rhyzocretes, and powdery crusts. Rutkowski & Kiersnowski (2025) note that Iron Age coastal progradation ( 3040 BP) created unfavourable sabkha conditions, contributing to a decline in human activity.","sig":"Living geological laboratories for studying evaporite mineral formation. The formation of the sabkha belt in the former bay during the Iron Age created conditions unfavourable for settlement, explaining the archaeological gap in the first millennium BC.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Active Dolomite Formation: Ongoing dolomite formation in hypersaline conditions, providing modern analogs for understanding ancient dolomite deposits worldwide.","Holocene Beach Ridges: Ancient beach ridges and berms separated from the present shoreline by 4–6 km of sabkha, documenting Holocene sea-level changes.","Multiple Gypcrete Types: Massive crusts, desert roses, rhyzocretes, and powdery gypsum crusts — a complete catalogue of gypcrete morphologies (Khalaf & Al-Zamel, 2014).","Evaporite minerals: halite, gypsum, anhydrite","Modern analogue for ancient evaporite sequences","Repeated marine flooding and evaporation cycles","Distinctive polygonal salt crust patterns"],"refs":["Khalaf, F.I. & Al-Zamel, A. (2014). Petrography and Mineralogy of Quaternary Gypcrete from Northern Kuwait. Journal of African Earth Sciences, 95, 1–14. DOI: 10.1016/j.jafrearsci.2014.02.007","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Khalaf, F.I. (2011). Quaternary Geology of Kuwait. Kuwait University Press"],"ic":"salt","era":"N","te":"The Salt Flats","ta":"السبخات الملحية","se":"The sea floods in, the sun bakes it dry, and salt crystals grow. Repeated over thousands of years, this cycle made a shining salt crust. It may also explain why people stopped living on this coast for a thousand years.","sa":"يغمر البحر الأرض، ثم تجففها الشمس، فتنمو بلورات الملح. وتكرار ذلك آلاف السنين صنع قشرة ملحية لامعة. وقد يفسّر ذلك سبب هجر الناس هذا الساحل ألف عام.","na":"سبخات ساحل جون الكويت","t0":10000.0,"t1":0},{"id":"kuwait-geopark","n":"Kuwait Geopark","c":"geological","s":"Geopark / Protected Area","lat":29.6,"lng":48.0,"p":"Multi-Period","dr":"Miocene to Present","el":"","desc":"Kuwait’s first geological park in the Al-Subbiya area, integrating geological, natural, and cultural heritage into an open-air museum. The vertical story from deep crust to surface landforms — faults, fluids, sediments, landforms — makes it exceptional for geopark designation.","sig":"Kuwait’s bid for UNESCO Global Geopark recognition; the first facility in Kuwait dedicated to geological heritage preservation and education.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Integrated Heritage Site: Combines geological formations (Jal Az-Zor escarpment, mud volcanoes) with archaeological sites in a unified educational experience.","UNESCO Geopark Candidacy: Kuwait’s formal bid for UNESCO Global Geopark recognition.","Proposed UNESCO Global Geopark designation","Integrates geological, archaeological, and ecological heritage","43+ documented sites of scientific significance","Framework for conservation, education, and sustainable tourism"],"refs":["Kuwait National Committee for UNESCO (2025). Kuwait Geopark: Nomination Dossier for UNESCO Global Geopark. Kuwait Ministry of Information","UNESCO (2015). UNESCO Global Geoparks: Celebrating Earth Heritage, Sustaining Local Communities. UNESCO Publishing"],"ic":"map","era":"N","te":"The Living Museum","ta":"المتحف الحي","se":"Imagine one park that holds mud volcanoes, great cliffs, ancient shorelines, prehistoric villages, Bronze Age graves and salt-loving plants. That is the dream of the Kuwait Geopark, a candidate to join the world’s family of UNESCO Global Geoparks.","sa":"تخيّل حديقة واحدة تضم براكين طينية وجروفًا عظيمة وشواطئ قديمة وقرى من عصور ما قبل التاريخ وقبورًا من العصر البرونزي ونباتات تحب الملح. هذا هو حلم الحديقة الجيولوجية الكويتية، المرشحة للانضمام إلى شبكة اليونسكو العالمية للحدائق الجيولوجية.","na":"الحديقة الجيولوجية الكويتية","t0":23000000.0,"t1":0},{"id":"paleo-liquefaction","n":"Paleo-Liquefaction Dikes (Bou-Rabee Field Stops)","c":"geological","s":"Seismic Evidence / Sand Boils","lat":29.6125,"lng":48.04,"p":"Pleisto-Holocene","dr":"7,000 years ago (single catastrophic event)","el":"","desc":"Bou-Rabee, Young & Okal (2020) documented cemented sand and gravel-filled dikes of Pleisto-Holocene age along the Jazirat Dubaij / Jal Az-Zor coast, with appearance and composition similar to typical ‘sandstone pipes.’ The significant age difference between the cemented dikes and surrounding loose sand, their size and spatial distribution, and the local geologic setting suggest they result from a single large event of seismic origin — either shaking during a large earthquake or seiching of tsunami-like waves. The research may help explain the disappearance of an ancient civilization that lived in the region 7,000 years ago.","sig":"First documented evidence of prehistoric liquefaction in Kuwait, with major implications for seismic hazard assessment in the Arabian Gulf. The catastrophic event may explain the abandonment of Ubaid-period coastal settlements like H3.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Cemented Sand Dikes: Sandstone pipe-like features where liquefied sand was injected upward through cracks during seismic shaking, then cemented in place.","Sand Boils at Jal Az-Zor: Photographs of sand boils found near the Jazirat Dubaij site, at the Jal Az-Zor escarpment — surface expressions of subsurface liquefaction.","8 Documented Field Stops: Eight field stops with precise coordinates documented along the coast from Ras al-Subiyah to Jazirat Dubaij.","Civilization Disappearance Link: The seismic event may explain the disappearance of the Ubaid-era coastal civilization 7,000 years ago.","Cemented sand dikes in loose Pleisto-Holocene sand","Evidence of powerful ancient earthquake","Liquefaction features in a region not typically seismically active","8 documented field stops along a transect"],"refs":["Bou-Rabee, F., Young, Y.L. & Okal, E.A. (2020). Evidence of Prehistoric Liquefaction in Kuwait and Implications for the Seismic Vulnerability of the Arabian Gulf Countries. Natural Hazards. DOI: 10.1007/ s11069-020-04013-9"],"ic":"quake","era":"P","te":"The Day the Ground Turned to Liquid","ta":"يوم سالت الأرض","se":"About seven thousand years ago a powerful earthquake shook the soaked sand so hard that it flowed like water. Sand shot upward and hardened into walls that you can still see. Some think this disaster may be why the seaside villages were abandoned.","sa":"قبل نحو سبعة آلاف عام هزّ زلزال قوي الرمال المشبعة بالماء حتى جرت كالسائل. اندفع الرمل إلى الأعلى وتصلّب في جدران ما زالت تُرى. ويرى بعضهم أن هذه الكارثة ربما كانت سبب هجر القرى الساحلية.","na":"سدود التسييل القديمة","t0":7000,"t1":7000},{"id":"wadi-al-batin","n":"Wadi Al-Batin (Pishon River)","c":"geological","s":"Ancient River Channel","lat":29.3,"lng":47.5,"p":"Pleistocene to Holocene","dr":"2 million years ago to present (dry)","el":"","desc":"A major dry river valley running 72 km in a NE-SW direction through the AlDibdibah plain, forming the border between Kuwait and Iraq. The wadi is the remnant of an ancient river system that once flowed from Saudi Arabia through Kuwait. Some scholars identify it as the biblical Pishon River. Rutkowski & Kiersnowski (2025) note limited evidence of an alternative coastal route serving travellers along this wadi.","sig":"Identified by geologists Juris Zarins and James A. Sauer as the biblical Pishon River; traced via LANDSAT satellite imagery by Farouk El-Baz.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Garden of Eden Theory: Geologist Juris Zarins argued this was the Pishon River from Genesis, with the Garden of Eden located at the head of the Arabian Gulf.","Alluvial Fan System: A massive alluvial fan extending from Wadi Al-Rummah in Saudi Arabia through Kuwait and into Iraq.","LANDSAT Satellite Tracing: Farouk El-Baz used satellite imagery to trace the dry channel from Kuwait up through the wadi.","Major dry river valley forming Kuwait’s western border","Proposed biblical “Pishon River” identification","Active river during wetter Pleistocene climates","Drained interior Arabia toward Kuwait Bay ."],"refs":["Zarins, J. (1997). Atlantis of the Sands: The Search for the Lost City of Ubar. Archaeology, 50(3), 44–53","El-Baz, F. (1993). Kuwait as an Alluvial Fan of a Paleo-River. Zeitschrift für Geomorphologie, 37, 49–59","Zarins, J. (1997). Atlantis of the Sands: The Search for the Lost Arabian Civilization. Archaeology, 50(3), 50–53"],"ic":"river","era":"D","te":"The River of Legend","ta":"نهر الأسطورة","se":"This long, dry valley forms Kuwait’s western border. In wetter times it was a mighty river draining the heart of Arabia. Some have even linked it to the Pishon, one of the four rivers of Eden.","sa":"هذا الوادي الطويل الجاف يشكّل حدود الكويت الغربية. وفي العصور الأكثر مطرًا كان نهرًا عظيمًا يصرّف مياه قلب الجزيرة العربية. بل ربطه بعضهم بنهر فيشون، أحد أنهار الجنة الأربعة.","na":"وادي الباطن","t0":2000000.0,"t1":0},{"id":"bahrah-hydrothermal","n":"Bahrah Deep-Fault Hydrothermal System","c":"geological","s":"Hydrothermal / Tectonic","lat":29.62,"lng":47.93,"p":"Cretaceous to Present","dr":"100 million years ago to present (active)","el":"","desc":"Integrated seismic, petrographic, and noble-gas data reveal deep-seated faults and seismic pipes beneath the Bahrah area that enable hydrothermal fluids to rise from the basement, breaching seals and causing oil leakage, baroque dolomite formation, helium isotope anomalies, and surface sag structures (Behbehani et al., 2019). Bahrah is dynamically linked to basement tectonics and hydrothermal circulation.","sig":"Demonstrates direct coupling between deep crustal processes and surface features in Kuwait — invisible faults act as conduits moving hot fluids from kilometers deep to the surface.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Deep-Seated Fault Network: Seismic data reveal faults extending from the Precambrian basement through the entire sedimentary column.","Baroque Dolomite: Saddle-shaped dolomite crystals formed by hot fluids rising from depth — a diagnostic indicator of hydrothermal activity.","Helium Isotope Anomalies: Noble gas analysis shows anomalous ³He/⁴He ratios indicating mantlederived fluids reaching the surface.","Surface Sag Structures: Circular collapse features at the surface caused by dissolution and fluid withdrawal at depth.","Oil Leakage Evidence: Hydrocarbon seepage along fault planes, demonstrating that the fault system breaches reservoir seals.","Anomalous geothermal activity in southern Kuwait","Warm springs and elevated ground temperatures","Deep fluid circulation along fault systems","One of few known hydrothermal systems in Arabian lowlands"],"refs":["Behbehani, S. et al. (2019). Bahrah Field: Hydrothermal Dolomite, Faults, and Basement Coupling in Kuwait. GeoArabia, 24(4), 135–164"],"ic":"steam","era":"D","te":"Heat from the Deep","ta":"حرارة من الأعماق","se":"Hidden faults act like pipes, carrying hot fluids from kilometres underground up to the surface. Warm ground, unusual minerals and gases from deep inside the Earth make this one of very few hot systems in the Arabian lowlands.","sa":"صدوع خفية تعمل كأنابيب تنقل سوائل حارة من أعماق تبلغ كيلومترات إلى السطح. أرض دافئة ومعادن غريبة وغازات من باطن الأرض تجعل هذا المكان من الأنظمة الحرارية النادرة في سهول الجزيرة العربية.","na":"نظام بحرة الحراري المائي العميق","t0":100000000.0,"t1":0},{"id":"gypcrete-formations","n":"Northern Kuwait Gypcrete Formations","c":"geological","s":"Evaporite Crust / Desert Pavement","lat":29.65,"lng":47.88,"p":"Quaternary","dr":"2.6 million years ago to present","el":"","desc":"Detailed petrographic and mineralogical analysis by Khalaf & Al-Zamel (2014) reveals multiple gypcrete types across northern Kuwait: massive crusts, spectacular gypsum roses (desert roses), rhyzocretes (root-cast gypsum), and powdery crusts. These formed through evaporation, saline brine interaction, and extreme aridity, with remarkable gypsum–bassanite transformations occurring naturally.","sig":"The surface of northern Kuwait records desert climate in stone, preserving chemical reactions driven by heat, salinity, and groundwater evaporation.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Massive Gypcrete Crusts: Thick, continuous gypsum-cemented surface crusts forming a durable desert pavement.","Desert Rose Formations: Spectacular rosette-shaped gypsum crystal clusters formed by evaporation of saline groundwater.","Rhyzocretes: Gypsum crusts formed around ancient plant roots, preserving ghost outlines of vegetation from wetter climate periods.","Natural Bassanite Transformation: Gypsum partially dehydrating into bassanite under natural desert conditions — normally requires industrial kilns.","Gypsum-cemented surface crusts","Formed through evaporative processes","Paleoclimate indicators for past conditions","Evidence of historical groundwater levels"],"refs":["Khalaf, F.I. & Al-Zamel, A. (2014). Petrography and Mineralogy of Quaternary Gypcrete from Northern Kuwait. Journal of African Earth Sciences, 95, 1–14. DOI: 10.1016/j.jafrearsci.2014.02.007","Khalaf, F.I. (2011). Quaternary Geology of Kuwait. Kuwait University Press"],"ic":"salt","era":"D","te":"Desert Roses","ta":"ورود الصحراء","se":"Heat, salt and evaporating groundwater have turned the surface of the north into stone crusts. In places gypsum crystals grow into flower-like shapes known as desert roses.","sa":"حوّلت الحرارة والملح وتبخّر المياه الجوفية سطح الشمال إلى قشور حجرية. وفي بعض الأماكن تنمو بلورات الجبس على هيئة زهور تُعرف بورود الصحراء.","na":"تكوينات الجبسكريت في شمال الكويت","t0":2600000.0,"t1":0},{"id":"sabkha-seismites","n":"Sabkha Seismite & Mud Pillow Field","c":"geological","s":"Seismite / Soft-Sediment Deformation","lat":29.61,"lng":48.06,"p":"Quaternary","dr":"Quaternary (multiple events)","el":"","desc":"Field mapping by Duane et al. (2015) documented a remarkable assemblage of soft-sediment deformation features in the coastal sabkhas north of Kuwait Bay: mud pillows, fluidized craters, flame structures, and convolute bedding. These formed by earthquake-triggered liquefaction and focused brine ascent through unconsolidated tidal flat sediments.","sig":"Kuwait’s tidal flats preserve rare onshore evidence of seismic shaking recorded directly in soft sediments — among the best-preserved examples worldwide.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Mud Pillows: Rounded, pillow-shaped masses of mud formed when liquefied sediment was injected upward during seismic shaking.","Fluidized Craters: Circular depressions formed by violent upward expulsion of fluidized sediment during earthquakes, some exceeding 2 meters in diameter.","Flame Structures: Upward-pointing tongues of fine sediment injected into overlying coarser layers during liquefaction events.","Convolute Bedding: Intricately folded and contorted sedimentary layers caused by differential liquefaction during seismic events.","Deformation structures from seismic shaking","Convoluted bedding, flame structures, sand dikes","Evidence of paleoseismic activity","Formed in water-saturated evaporite deposits"],"refs":["Duane, M.J. et al. (2015). Mud Volcanoes, Seismites, and Other Features of Soft-Sediment Deformation in Coastal Sabkhas, Kuwait. Arabian Journal of Geosciences, 8, 1169–1186. DOI: 10.1007/s12517-013-1236-3"],"ic":"quake","era":"D","te":"Footprints of Earthquakes","ta":"بصمات الزلازل","se":"Soft mud remembers. When earthquakes shook these salt flats, the layers curled, rose like flames and formed pillows of mud. They are among the best examples of quake marks preserved anywhere.","sa":"الطين الرخو يتذكّر. حين هزّت الزلازل هذه السبخات التفّت الطبقات وارتفعت كألسنة اللهب وتكوّنت وسائد من الطين. وهي من أفضل أمثلة آثار الزلازل المحفوظة في العالم.","na":"حقل الزلزاليات والوسائد الطينية","t0":2580000.0,"t1":0},{"id":"holocene-sea-level","n":"Holocene Paleo-Shoreline & Sea-Level Record","c":"geological","s":"Paleo-Shoreline / Sea-Level Change","lat":29.58,"lng":47.97,"p":"Holocene","dr":"7400 BP – present","el":"","desc":"Radiocarbon dating of marine mollusk shells from the Bahra area by Rutkowski & Kiersnowski (2025) has significantly enhanced understanding of Holocene sea transgression. The earliest transgression at Bahra dates to 7400–7100 cal BP. The long-term highstand included two or three peaks (around 5700 BP and 4000 BP), with sea levels +3.5 m or more above present in the Bahra area. A notable concentration of dates from the end of the 4th millennium to the mid-2nd millennium BC suggests the highest sea levels coincided with the Bronze Age cemetery use. A late pre-Islamic minor highstand ( 2000– 1500 cal BP) temporarily halted regression.","sig":"The most comprehensive Holocene sea-level reconstruction for northern Kuwait Bay, integrating neotectonic influences. Demonstrates that the mid-Holocene highstand shaped the entire archaeological landscape — from settlement locations to cemetery placement to ritual platform orientation.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Earliest Transgression (7400–7100 cal BP): Persistent depressions facilitated earlier marine intrusion than previously estimated.","Highstand Peaks (5700 BP & 4000 BP): Two or three sea-level peaks during the long-term highstand, with levels +3.5 m above present.","Bronze Age Correlation: Highest sea levels coincided with the use of the coastal tumulus cemetery during the Early and Middle Bronze Age.","Iron Age Regression ( 3040 BP): Coastal progradation began, creating sabkha conditions unfavourable for human presence.","Late Pre-Islamic Minor Highstand: A temporary halt in regression ( 2000–1500 cal BP) coinciding with torpedo jar pottery scatters along the coast.","Multiple paleo-shoreline indicators documented","Raised beach deposits and marine terraces","Fossil coral reefs recording sea-level history","Complex 10,000-year sea-level fluctuation record"],"refs":["Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah, Kuwait Bay. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269","Reinink-Smith, L.M. & Carter, R. (2022). Sea-Level Stillstand on Southeastern Bubiyan Island. Quaternary Research","Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record of Al-Subiyah. Arabian Archaeology and Epigraphy. DOI: 10.1111/aae.12269"],"ic":"wave","era":"P","te":"The Rising and Falling Sea","ta":"البحر بين المد والجزر الطويل","se":"Over the last ten thousand years the sea crept in, peaked twice and then drew back. Raised beaches and old reefs record every step. These changes decided where people built villages, where they buried their dead and which way their stone platforms faced.","sa":"خلال العشرة آلاف عام الأخيرة زحف البحر، وبلغ ذروته مرتين، ثم انحسر. وتسجّل الشواطئ المرتفعة والشعاب القديمة كل خطوة. وقد حددت هذه التغيرات أين بنى الناس قراهم، وأين دفنوا موتاهم، وإلى أين اتجهت منصاتهم الحجرية.","na":"خط الساحل القديم وسجل مستوى البحر","t0":7400,"t1":0},{"id":"jahra-escarpment-interface","n":"Mutla-Jahra Escarpment Interface","c":"geological","s":"Structural Geology","lat":29.4314,"lng":47.7359,"p":"Pliocene–Pleistocene","dr":"2 Ma – Present","el":"","desc":"This point marks where the Al-Khafji High, a deep tectonic structure, influences surface drainage. The gravels here are clastic influxes from the ancient Wadi Al-Batin system, proving this was a major delta mouth approximately 2 million years ago. Morphometric analysis reveals that the escarpment interface is not simply an erosional feature but is structurally controlled by basement tectonics, creating a natural boundary between the coastal plain and the interior desert plateau.","sig":"Demonstrates direct coupling between deep basement tectonics (Al-Khafji High) and modern surface geomorphology. Proves the existence of a major Plio-Pleistocene delta system that once drained the interior of Arabia through what is now Kuwait.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Paleo-Batin Delta Gravels: Clastic deposits proving a major river delta existed here 2 million years ago","Al-Khafji High Influence: Deep tectonic structure controls surface drainage patterns visible today","Escarpment Structural Control: The interface is fault-controlled, not purely erosional","Geological transition between escarpment and coastal plain","Evidence of tectonic uplift and erosion interplay","Complex sedimentation history","Key to understanding Kuwait Bay landscape evolution"],"refs":["Al-Anzi, B. et al. (2025). Morphometric Analysis of the Northern Coastal Plains. Kuwait Journal of Science","Milton, D.I. (1967). Geology of the Arabian Peninsula: Kuwait. USGS Professional Paper 560-F"],"ic":"cliff","era":"D","te":"Where the Ridge Meets the Plain","ta":"حيث يلتقي الجرف بالسهل","se":"At the foot of the ridge, rivers that once drained Arabia dropped gravel in a giant delta. Uplift and erosion have been shaping this meeting point for millions of years.","sa":"عند سفح الجرف ألقت أنهار كانت تصرّف مياه الجزيرة العربية حصاها في دلتا عملاقة. وما زال الارتفاع والتعرية يشكّلان نقطة الالتقاء هذه منذ ملايين السنين.","na":"واجهة جرف المطلاع - الجهراء","t0":2000000.0,"t1":0},{"id":"dextral-slip-fault","n":"Jal Az-Zor Dextral-Slip Fault Zone","c":"geological","s":"Structural Tectonics","lat":29.6177,"lng":48.0551,"p":"Eocene – Present","dr":"40 Ma – Active","el":"","desc":"Structural mapping by Naqi & Amer (2021) identifies this section of the Jal Az-Zor escarpment as a ‘Principal Displacement Zone’ — not merely an erosional cliff but an active dextral-slip (right-lateral) fault. The ground is physically moving laterally while also being pushed upward by the Arabian Plate’s collision with Iran. This creates the distinctive ‘step’ in the landscape visible on satellite imagery. The exposed Dammam Formation limestone here shows Eocene marine fossils with significant karst (cave/sinkhole) potential, analogous to the Edwards Plateau in Texas.","sig":"Redefines the Jal Az-Zor escarpment from a passive erosional feature to an active tectonic frontier. The strike-slip motion has implications for seismic hazard assessment across Kuwait and explains the concentration of geological anomalies along the ridge.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Strike-Slip Motion Confirmed: Structural mapping proves lateral ground movement, not just vertical uplift","Principal Displacement Zone: The escarpment is a major structural boundary, not simple erosion","Eocene Fossil Carbonates: Exposed Dammam Formation with marine fossils and karst features","Right-lateral strike-slip fault in Kuwait Bay","Part of Zagros fold-thrust belt framework","Significant for seismic hazard assessment","Evidence of active tectonic deformation"],"refs":["Naqi, A. & Amer, M. (2021). Structural Mapping of the Jal Az-Zor Escarpment: Evidence for Dextral-Slip Faulting. Arabian Journal of Geosciences"],"ic":"fault","era":"D","te":"The Sliding Fault","ta":"الصدع المنزلق","se":"Two blocks of the Earth are sliding past each other along this line. It turns the great cliff from a quiet slope into an active edge, and it helps explain why so many strange features gather along the ridge.","sa":"كتلتان من الأرض تنزلقان إحداهما بجوار الأخرى على امتداد هذا الخط. وهذا يحوّل الجرف العظيم من منحدر هادئ إلى حافة نشطة، ويفسّر تجمّع ظواهر غريبة كثيرة على امتداده.","na":"نطاق صدع جال الزور الانزلاقي الأيمن","t0":40000000.0,"t1":0},{"id":"had-safah-sinkholes","n":"Had Safah Sinkhole Complex","c":"geological","s":"Karst Hazards","lat":29.5695,"lng":47.8875,"p":"Quaternary – Present","dr":"Active (Feb 2026 reports)","el":"","desc":"A high-density fracture field in the Dammam Limestone where recent ‘covercollapse’ sinkholes are actively forming as rainwater exploits vertical joints. Al-Rashed & Al-Sarawi (2018) documented karst features and sinkholes in northern Kuwait, establishing the geological framework. February 2026 field reports document new collapse events within rainwater channels, with deep shadows and cracks trending northeast. The mechanism is identical to cenote formation in the Yucatan Peninsula: the limestone roof of subsurface caverns becomes too thin to support the overlying desert gravels, causing sudden collapse. The Karst Susceptibility Index (KSI) here is among the highest in Kuwait due to steep slopes (>25 degrees), proximity to the main escarpment fault, and high solubility of the Dammam Limestone.","sig":"Represents an active geological hazard with implications for infrastructure planning. Also provides a ‘window’ into the subsurface karst system that may connect to deeper aquifer networks. Analogous to the Pennyroyal Plain sinkholes in Kentucky and the Nullarbor Plain in Australia.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Active Cover-Collapse Events: New sinkholes documented in February 2026 field surveys","NE-Trending Fracture System: Cracks aligned with regional tectonic stress field","High Karst Susceptibility: KSI modeling identifies this as Kuwait’s highest-risk sinkhole zone","Active sinkhole complex from limestone/gypsum dissolution","Karst features indicating ongoing subsurface processes","Geological hazard requiring monitoring","Evidence of groundwater-rock interaction"],"refs":["Al-Rashed, M. & Al-Sarawi, M. (2018). Karst Features and Sinkholes in Northern Kuwait. Kuwait Journal of Science","Kuwait Society for Earth Sciences (2026). Field Report: Had Safah Fracture Field and Recent Collapse Events. KSES Technical Bulletin"],"ic":"sinkhole","era":"N","te":"When the Ground Opens","ta":"حين تنفتح الأرض","se":"Underground, water slowly dissolves limestone and gypsum. Then one day the surface collapses and a sinkhole appears. New collapses were reported here in 2026, a window into a hidden world beneath your feet.","sa":"في باطن الأرض يذيب الماء الحجر الجيري والجبس ببطء. ثم ينهار السطح يومًا فتظهر حفرة. وقد سُجّلت انهيارات جديدة هنا في عام 2026، نافذة على عالم خفي تحت قدميك.","na":"مجمع حفر حد صفاة","t0":30,"t1":0},{"id":"petrified-wood-field","n":"Permineralized Wood Field (Petrified Forest)","c":"geological","s":"Palaeontology","lat":29.6406,"lng":47.9398,"p":"Oligo-Miocene to Pleistocene","dr":"30 Ma – 2 Ma","el":"","desc":"The primary outcrop of Kuwait Group gravels containing abundant permineralized (petrified) wood. These fossilized tree limbs were transported by the ancient PaleoBatin river system from the interior of Arabia and buried in fluvial sandstone environments. Diagnostic features include ferruginous (iron-rich) pseudomorphic replacement where original cellulose was replaced by Goethite or Hematite through mineral-rich groundwater seepage. Critically, many specimens contain Teredolite ichnofossils — borings made by marine wood-boring organisms — proving the wood floated in estuarine (brackish) water before burial. This is the ‘smoking gun’ evidence that this area was a massive river delta where fresh river water met the salty ancient Gulf.","sig":"Proves the existence of a major ancient river delta system in northern Kuwait. The Teredolite ichnofossils are globally significant as they demonstrate the transition from fluvial to marine environments. Analogous to the Nubian Sandstone petrified forests of North Africa.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Teredolite Ichnofossils: Marine wood-borer traces proving estuarine environment — the ‘smoking gun’","Ferruginous Pseudomorphs: Iron-rich mineral replacement preserving original wood fiber structure","Paleo-Batin River Evidence: Wood transported hundreds of kilometers from Arabia’s interior forests","Growth Ring Analysis: Preserved rings indicate seasonal climate during the Miocene","Petrified wood with cellular-level preservation","Silica mineral replacement of ancient trees","Evidence of wetter paleoclimate supporting forests","Significant paleobotanical specimens"],"refs":["Amer, M. et al. (2019). Petrified Wood Occurrences in the Kuwait Group: Fluvial Archives of the PaleoBatin System. Arabian Journal of Geosciences","Khalaf, F.I. (2011). Quaternary Geology of Kuwait. Kuwait University Press"],"ic":"wood","era":"D","te":"The Stone Forest","ta":"الغابة الحجرية","se":"Kuwait once had forests. Tree trunks that fell into ancient rivers were slowly replaced by stone, so perfectly that you can still count their growth rings. Some even carry the tunnels of marine wood-boring creatures.","sa":"كانت في الكويت غابات يومًا. جذوع أشجار سقطت في أنهار قديمة تحوّلت ببطء إلى حجر، بإتقان يجعلك تعدّ حلقات نموها حتى اليوم. وبعضها يحمل أنفاق كائنات بحرية حفرت في الخشب.","na":"حقل الأخشاب المتحجرة","t0":30000000.0,"t1":2000000.0},{"id":"sand-injectite-biotope","n":"Sand Injectite Field & Desert Biotope","c":"geological","s":"Fluid Mechanics / Ecology","lat":29.6529,"lng":47.9982,"p":"Miocene – Present","dr":"15 Ma (formation) – Present (ecology)","el":"","desc":"Globally rare vertical sandstone pipes (‘chimneys’) formed when overpressured sand slurry ‘blasted’ through overlying rock layers millions of years ago. Al-Hajeri et al. (2020) documented enigmatic clastic injectite outcrops associated with forced-folds in the Al-Bahrah area. These sand injectites are surface analogues for deep oil and gas reservoir connectivity, making them scientifically valuable to the energy industry. The ‘Martian-red’ iron-stained outcrops at nearby coordinates (29.6141°N, 48.0540°E) are particularly photogenic. Ecologically, these vertical structures create ‘micro-relief’ that traps moisture in an otherwise barren landscape, supporting specialized desert lichen, mosses, and even small shrubs — a rare desert biotope. The zone also exhibits intense vertical fracturing near the cliff edge, with high risk for future sinkhole development.","sig":"A dual-purpose scientific site: the injectites serve as world-class analogues for subsurface fluid flow (used by petroleum geologists globally), while simultaneously creating rare ecological microhabitats. Analogous to the Panoche Hills Injectite Complex in California.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Vertical Sandstone Pipes: Rare fluid-escape structures formed by overpressured sand injection","Oil Reservoir Analogues: Used by petroleum industry to model deep reservoir connectivity","Desert Lichen Biotope: Moisture-trapping micro-relief supports specialized desert organisms","Intense Fracture Field: Vertical fracturing near cliff edge indicates active tectonic stress","Sand injectite features from seismic liquefaction","Coexistence of geological and ecological features","Specialized desert flora and fauna","Evidence of ancient seismic activity )"],"refs":["Al-Hajeri, M. et al. (2020). Origin of Enigmatic Clastic Injectite Outcrops Associated with Forced-Folds in Al-Bahrah Area. Marine and Petroleum Geology, 113, 104153"],"ic":"quake","era":"N","te":"Sand Fountains Frozen in Stone","ta":"نوافير رمل متجمدة في الحجر","se":"During ancient earthquakes, liquid sand was forced up through cracks and hardened into pipes and sheets. Today lichens and desert creatures make their homes among these stone fountains.","sa":"خلال زلازل قديمة اندفع الرمل السائل عبر الشقوق وتصلّب في أنابيب وصفائح. واليوم تتخذ الأشنات وكائنات الصحراء من هذه النوافير الحجرية بيوتًا لها.","na":"حقل حقن الرمال والموئل الصحراوي","t0":15000000.0,"t1":0},{"id":"positive-flower-structure","n":"Positive Flower Structure","c":"geological","s":"Structural Geology","lat":29.4815,"lng":47.7749,"p":"Neogene – Present","dr":"5 Ma – Active","el":"","desc":"A ‘Positive Flower Structure’ forms when strike-slip tectonic motion ‘squeezes’ the ground upward, creating a localized topographic high. At these coordinates, a distinctive V-shaped drainage pattern points away from a central high point, which is the diagnostic signature of compressional uplift along a strike-slip fault. This is a smaller-scale version of the pressure ridges found along the San Andreas Fault in California. The structure confirms that the tectonic forces affecting the Jal Az-Zor escarpment extend southwestward into the Jahra area, connecting the two project zones into a single tectonic system.","sig":"Provides the ‘missing link’ connecting the Jal Az-Zor fault system to the Jahra area. Confirms that both project zones are part of the same active tectonic system, with implications for regional seismic hazard assessment.","ex":"","conf":"","ev":"","an":"","val":"","disc":["V-Shaped Drainage Pattern: Diagnostic signature of compressional uplift along a strike-slip fault","Pressure Ridge Identification: Small hills formed by tectonic ‘squeezing’ — analogous to San Andreas features","Tectonic Connectivity: Links the Jal Az-Zor and Jahra fault systems into one regional structure","Positive flower structure at restraining bend","Evidence of active transpressional tectonics","Uplifted zone from converging fault strands","Flower-like cross-sectional profile"],"refs":["Naqi, A. & Amer, M. (2025). Structural Mapping of the Jal Az-Zor Escarpment: Evidence for Dextral-Slip Faulting. Arabian Journal of Geosciences","Naqi, A. & Amer, M. (2021). Structural Mapping of the Jal Az-Zor Escarpment: Evidence for Dextral-Slip Faulting. Arabian Journal of Geosciences"],"ic":"fault","era":"D","te":"The Stone Flower","ta":"الزهرة الحجرية","se":"Where a fault bends, rock gets squeezed and pushed upward. Seen in cross-section it opens like a flower. This one links two parts of the same active fault system.","sa":"حيث ينحني الصدع ينضغط الصخر ويندفع إلى الأعلى. وإذا نظرت إلى مقطعه رأيته يتفتح كزهرة. وهذه الزهرة تربط جزأين من منظومة صدوع نشطة واحدة.","na":"تركيب الزهرة الموجب","t0":5000000.0,"t1":0},{"id":"karst-sinkhole-zone","n":"Karst Plain Sinkhole Discovery Zone","c":"geological","s":"Karst Geomorphology","lat":29.6215,"lng":48.0122,"p":"Quaternary – Present","dr":"Active dissolution","el":"","desc":"Satellite imagery analysis reveals circular, darkened depressions that do not align with natural drainage wadis — the hallmark signature of karst dissolution features. These depressions form where rainwater percolates through fractures in the Dammam Limestone, gradually dissolving the rock and creating subsurface voids. When the roof becomes too thin, the surface collapses. The area shows ‘Green Spot’ anomalies where vegetation grows inside sinkholes due to trapped moisture, providing a natural detection method. Shadow analysis at low sun angles (7:00 AM) reveals additional subtle lineaments and circular features invisible at midday.","sig":"Represents a previously unmapped karst field with potential for significant subsurface cavern systems. The ‘Green Spot’ detection method provides a low-cost remote sensing technique for identifying hidden sinkholes across Kuwait’s limestone terrain. Analogous to the Nullarbor Plain in Australia.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Circular Depression Field: Multiple darkened depressions not aligned with natural drainage — karst signature","Green Spot Anomalies: Vegetation growing inside sinkholes where moisture is trapped","Shadow Analysis Detection: Low sun angle reveals subtle features invisible at midday","Active karst topography with sinkholes and dolines","Dissolution of carbonate and evaporite rocks","Geological hazard requiring monitoring","Ongoing groundwater dissolution of bedrock"],"refs":["Kuwait Society for Earth Sciences (2026). Remote Sensing Detection of Karst Features in Northern Kuwait. KSES Technical Bulletin","Al-Rashed, M. & Al-Sarawi, M. (2018). Karst Features and Sinkholes in Northern Kuwait. Kuwait Journal of Science"],"ic":"sinkhole","era":"N","te":"The Hidden Hollows","ta":"التجاويف الخفية","se":"A whole field of round hollows that was never mapped before. Hidden sinkholes can give themselves away with a green spot of plants, and from space that is how they were found.","sa":"حقل كامل من التجاويف الدائرية لم يُرسم على الخرائط من قبل. فالحفر الخفية قد تكشف نفسها ببقعة خضراء من النبات، وهكذا عُثر عليها من الفضاء.","na":"منطقة اكتشاف الحفر الكارستية","t0":30,"t1":0},{"id":"wadi-batin-fault","n":"Wadi Al-Batin Fault","c":"geological","s":"Structural Tectonics","lat":29.18,"lng":46.55,"p":"Neogene – Present","dr":"23 Ma – Active","el":"","desc":"A principal displacement zone aligning with the Abu Jir-Euphrates fault system. This major tectonic lineament influences the remarkably straight geomorphology of Wadi Al-Batin, which forms the Kuwait-Iraq border. Al-Hurban & Hassan (2025) identified this as a morphotectonic feature where deep crustal faults control surface drainage patterns across hundreds of kilometers.","sig":"Demonstrates the direct link between deep crustal structure and surface geomorphology in Kuwait. The fault alignment explains why Wadi Al-Batin maintains its unusually straight course over 72 km.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Abu Jir Fault Alignment: The wadi follows the trace of the deep Abu Jir-Euphrates fault system","Morphotectonic Control: Deep faults dictate surface drainage patterns across the Dibdibba plain","Active Displacement Zone: Ongoing tectonic activity influences modern geomorphology","Abu Jir-Euphrates fault alignment controls wadi geomorphology","Deep crustal structure dictates surface drainage over 72 km","Active morphotectonic displacement zone )"],"refs":["Al-Hurban, A. & Hassan, M. (2025). Morphotectonic Analysis of the Wadi Al-Batin Region. Kuwait Journal of Science"],"ic":"fault","era":"D","te":"The Ruler-Straight Valley","ta":"الوادي المستقيم","se":"Why does the great valley run so straight for 72 kilometres? A deep crack in the Earth’s crust guides it, like a ruler drawn beneath the desert.","sa":"لماذا يمتد الوادي العظيم مستقيمًا 72 كيلومترًا؟ شقّ عميق في قشرة الأرض يوجّهه، كمسطرة مرسومة تحت الصحراء.","na":"صدع وادي الباطن","t0":23000000.0,"t1":0},{"id":"dibdibba-alluvial-fan","n":"Dibdibba Alluvial Fan","c":"geological","s":"Fluvial Geomorphology","lat":29.15,"lng":46.51,"p":"Neogene – Quaternary","dr":"23 Ma – Present","el":"","desc":"The largest gravel fan in Arabia, the Dibdibba Formation is composed of Neogeneage pebbles transported from the Arabian Shield by ancient river systems. Al-Hurban & Hassan (2025) and Al-Sulaimi (1988) documented this massive alluvial fan that underlies much of northern Kuwait, recording millions of years of sediment transport from the interior of Arabia.","sig":"The foundation upon which Kuwait is built — this ancient gravel fan records the history of Arabia’s river systems and climate changes over millions of years.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Largest Arabian Gravel Fan: Extends across most of northern Kuwait and into Iraq","Arabian Shield Pebbles: Neogene-age gravels transported hundreds of kilometers from source","Climate Archive: Sediment layers record alternating wet and dry periods across millions of years","Largest gravel fan in Arabia extending across northern Kuwait","Neogene-age pebbles transported from the Arabian Shield","Climate archive recording millions of years of wet-dry cycles ."],"refs":["Al-Hurban, A. & Hassan, M. (2025). Morphotectonic Analysis of the Wadi Al-Batin Region. Kuwait Journal of Science","Al-Sulaimi, J. (1988). The Dibdibba Formation in Kuwait. Journal of the University of Kuwait (Science)"],"ic":"river","era":"D","te":"The Pebble Highway","ta":"طريق الحصى","se":"The largest gravel fan in Arabia lies under northern Kuwait. Its pebbles were carried by rivers from mountains far to the south-west, millions of years ago. It is the ground Kuwait stands on.","sa":"أكبر مروحة حصوية في الجزيرة العربية تمتد تحت شمال الكويت. حملت الأنهار حصاها من جبال بعيدة في الجنوب الغربي قبل ملايين السنين. إنها الأرض التي تقوم عليها الكويت.","na":"مروحة الدبدبة الفيضية","t0":23000000.0,"t1":0},{"id":"subbiya-sandstone-pipes","n":"Subbiya Sandstone Pipes","c":"geological","s":"Fluid Mechanics / UNESCO Geowonder","lat":29.6231,"lng":48.0125,"p":"Miocene – Quaternary","dr":"15 Ma – Present","el":"","desc":"Vertical sand injectites caused by fluid overpressure, formally described as a primary UNESCO-bid ‘Geowonder.’ These spectacular vertical sandstone pipes formed when overpressured sand slurry was injected upward through overlying rock layers. They serve as surface analogues for deep oil and gas reservoir connectivity, making them invaluable to the petroleum industry.","sig":"A primary feature in Kuwait’s UNESCO Global Geopark bid. These structures are among the best-preserved surface examples of sand injection features worldwide.","ex":"","conf":"","ev":"","an":"","val":"","disc":["UNESCO Geowonder Designation: Primary feature in Kuwait’s Geopark UNESCO bid","Fluid Overpressure Evidence: Vertical pipes formed by explosive sand injection from depth","Petroleum Industry Analogues: Used to model subsurface reservoir connectivity","Primary UNESCO Geopark bid feature — Geowonder designation","Vertical sand injection from fluid overpressure","Surface analogues for petroleum reservoir connectivity"],"refs":["Al-Hajeri, M. et al. (2020). Origin of Enigmatic Clastic Injectite Outcrops Associated with Forced-Folds in Al-Bahrah Area. Marine and Petroleum Geology, 113, 104153"],"ic":"quake","era":"D","te":"The Sandstone Chimneys","ta":"مداخن الحجر الرملي","se":"Upright pipes of sandstone stand where pressurised sand once burst upward. They are among the best examples on Earth and a star of Kuwait’s geopark bid.","sa":"أنابيب من الحجر الرملي تقف منتصبة حيث انفجر الرمل المضغوط إلى الأعلى يومًا. وهي من أفضل الأمثلة على وجه الأرض، ونجمة في ملف الحديقة الجيولوجية الكويتية.","na":"أنابيب الحجر الرملي في الصبية","t0":15000000.0,"t1":0},{"id":"huwaimiliyah-fossils","n":"Al-Huwaimiliyah Fossils","c":"geological","s":"Palaeontology","lat":29.815,"lng":47.62,"p":"Miocene","dr":"20–5 Ma","el":"","desc":"Miocene vertebrate remains including Deinotherium (an ancient elephant relative) discovered in northern Kuwait. Al-Sulaimi (2024) and Thomas et al. (1982) documented these fossils as evidence of Kuwait’s ancient tropical savanna environment, when the region supported large mammals, forests, and rivers rather than the arid desert of today.","sig":"Proves that Kuwait was once a lush tropical savanna with elephants, rivers, and forests — a dramatically different landscape from today’s desert.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Deinotherium Remains: Ancient elephant relative fossils proving tropical savanna conditions","Tropical Savanna Evidence: Kuwait was once covered in forests and grasslands","Miocene Climate Record: Fossils document the transition from wet to arid conditions","Deinotherium remains — ancient elephant relative fossils","Evidence of tropical savanna environment in Kuwait","Miocene climate transition from wet to arid recorded in fossils"],"refs":["Al-Sulaimi, J. (2024). Miocene Vertebrate Fossils of Northern Kuwait. Kuwait Journal of Science","Thomas, H. et al. (1982). Miocene Vertebrate Remains from Kuwait. Journal of Vertebrate Paleontology"],"ic":"fossil","era":"D","te":"When Elephants Roamed Kuwait","ta":"حين جابت الأفيال الكويت","se":"Picture a green savanna with rivers and trees. Millions of years ago a giant relative of the elephant, with tusks curving downward, walked here. Its bones are the proof.","sa":"تخيّل سافانا خضراء فيها أنهار وأشجار. قبل ملايين السنين سار هنا قريب عملاق للفيل، أنيابه منحنية نحو الأسفل. وعظامه هي الدليل.","na":"أحافير الحويملية","t0":20000000.0,"t1":5000000.0},{"id":"anthropic-slope-markers","n":"Anthropic Slope Markers","c":"geological","s":"Anthropogenic Geomorphology","lat":29.28,"lng":46.72,"p":"Modern","dr":"1990s – Present","el":"","desc":"Human-induced changes to the natural wadi slopes via military trenches and oil activities documented by Al-Hurban & Hassan (2025). These anthropogenic modifications have altered natural drainage patterns, accelerated erosion in some areas, and created artificial microhabitats in others. The features provide a modern analogue for understanding how human activity reshapes desert landscapes.","sig":"Documents the geological footprint of human activity in Kuwait’s desert — military operations and oil infrastructure permanently alter the landscape.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Military Trench Erosion: Gulf War trenches have altered natural drainage patterns","Oil Activity Scarring: Pipeline corridors and well pads create permanent landscape modifications","Accelerated Erosion: Human disturbance increases wind and water erosion rates","Military trench erosion altering natural drainage patterns","Oil infrastructure creating permanent landscape modifications","Accelerated wind and water erosion from human disturbance"],"refs":["Al-Hurban, A. & Hassan, M. (2025). Morphotectonic and Anthropogenic Geomorphology of the Wadi Al-Batin Region. Kuwait Journal of Science"],"ic":"trench","era":"N","te":"Scars of Our Time","ta":"ندوب عصرنا","se":"Not every landform is ancient. Trenches dug in wartime and tracks from oil work have changed how water flows and how fast the land wears away. People are now shaping geology too.","sa":"ليست كل التضاريس قديمة. فالخنادق التي حُفرت في الحرب ومسارات أعمال النفط غيّرت جريان الماء وسرعة تآكل الأرض. صار الإنسان أيضًا يشكّل الجيولوجيا.","na":"علامات المنحدرات البشرية","t0":36,"t1":0},{"id":"um-al-rimam-yardangs","n":"Um Al-Rimam Yardangs","c":"geological","s":"Aeolian Geomorphology","lat":29.56,"lng":47.81,"p":"Quaternary","dr":"100,000 years – Present","el":"","desc":"Wind-sculpted rock ridges formed by the North-West Shamal winds over thousands of years. Al-Dousari (2009/2016) documented these aerodynamically shaped landforms where persistent wind erosion has carved soft rock into streamlined ridges aligned with the prevailing wind direction. These yardangs are natural wind gauges, recording the dominant wind patterns of the last 100,000 years.","sig":"Natural archives of Kuwait’s wind history — the shape and alignment of these ridges record the direction and intensity of Shamal winds over millennia.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Shamal Wind Sculpting: Ridges aligned with the dominant NW Shamal wind direction","Natural Wind Gauges: Shape records wind intensity over 100,000 years","Ventifact Surfaces: Wind-polished rock surfaces with diagnostic abrasion patterns","Shamal wind-sculpted ridges aligned with dominant NW wind direction","Natural wind gauges recording 100,000 years of wind intensity","Ventifact surfaces with diagnostic abrasion patterns"],"refs":["Al-Dousari, A.M. (2009). Aeolian Geomorphology of Northern Kuwait. Kuwait Journal of Science","Al-Dousari, A.M. (2016). Dominant Sandy Landforms of Northern Kuwait. Geography Journal"],"ic":"dune","era":"D","te":"Sculptures of the Wind","ta":"منحوتات الريح","se":"For about 100,000 years the north-west Shamal wind has been carving these ridges. Their shape and direction work like a natural weather vane, recording the wind’s history.","sa":"منذ نحو 100,000 عام وريح الشمال الغربية تنحت هذه الحواف. وشكلها واتجاهها يعملان كدوّارة رياح طبيعية تسجّل تاريخ الريح.","na":"ياردانغ أم الرمام","t0":100000.0,"t1":0},{"id":"sabbiya-varnish-ridge","n":"As-Sabbiya Varnish Ridge","c":"geological","s":"Desert Geochemistry","lat":29.628,"lng":47.985,"p":"Quaternary","dr":"10,000 years – Present","el":"","desc":"Dark Manganese/Iron patina (Desert Varnish) protecting the ridge crests from rapid erosion. Al-Dousari (2009) and Khalaf (1988) documented this natural coating where bacteria concentrate manganese and iron oxides on exposed rock surfaces over thousands of years, creating a dark protective layer that slows erosion and records environmental changes in its chemical composition.","sig":"Desert varnish is a natural time capsule — its chemical layers record changes in climate, dust sources, and atmospheric conditions over thousands of years.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Manganese-Iron Patina: Bacterial concentration of metals creates protective dark coating","Erosion Protection: Varnished surfaces erode 10x slower than uncoated rock","Climate Archive: Chemical layers in the varnish record environmental changes","Manganese-Iron patina created by bacterial metal concentration","Varnished surfaces erode 10x slower than uncoated rock","Chemical layers record environmental changes over millennia"],"refs":["Al-Dousari, A.M. (2009). Desert Varnish on Rock Surfaces in Northern Kuwait. Kuwait Journal of Science","Khalaf, F.I. (1988). Desert Varnish and Weathering Processes in Northern Kuwait. Journal of Arid Environments"],"ic":"cliff","era":"N","te":"The Painted Ridge","ta":"الحافة المطلية","se":"A dark, shiny coat covers these rocks. Tiny bacteria built it by collecting iron and manganese, and it protects the ridge so well that coated rock wears away ten times slower.","sa":"غلاف داكن لامع يكسو هذه الصخور. صنعته بكتيريا دقيقة بتجميع الحديد والمنغنيز، وهو يحمي الحافة حتى إن الصخر المكسوّ به يتآكل أبطأ بعشر مرات.","na":"حافة الصبية المطلية","t0":10000.0,"t1":0},{"id":"volcanic-flood-erratics","n":"Volcanic Flood Erratics","c":"geological","s":"Flood Geology","lat":30.05,"lng":47.01,"p":"Pleistocene","dr":"2 Ma – 100,000 years ago","el":"","desc":"Rhyolite and dacite fragments transported from Saudi Arabia by massive prehistoric floods. Al-Hurban & Hassan (2025) and Al-Dousari (2021) documented these exotic volcanic rock fragments found far from their source, carried hundreds of kilometers by catastrophic flood events during wetter climate periods.","sig":"Proof of catastrophic prehistoric floods that transported volcanic rocks hundreds of kilometers from the Arabian Shield to northern Kuwait.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Exotic Volcanic Fragments: Rhyolite and dacite from the Arabian Shield found in Kuwait","Catastrophic Flood Evidence: Rocks too large for normal river transport, requiring flood conditions","Climate Change Record: Floods occurred during wetter Pleistocene climate periods","Exotic rhyolite and dacite from the Arabian Shield","Catastrophic flood transport over hundreds of kilometers","Climate change evidence from wetter Pleistocene periods"],"refs":["Al-Hurban, A. & Hassan, M. (2025). Morphotectonic Analysis of the Wadi Al-Batin Region. Kuwait Journal of Science","Al-Dousari, A.M. (2021). Volcanic Erratics in Northern Kuwait. Arabian Journal of Geosciences"],"ic":"river","era":"D","te":"Rocks from Far Away","ta":"صخور من بعيد","se":"These volcanic stones do not belong here. Huge floods carried them hundreds of kilometres from the mountains of Arabia, at a time when the desert saw rains we can hardly imagine.","sa":"هذه الحجارة البركانية ليست من هنا. حملتها فيضانات هائلة مئات الكيلومترات من جبال الجزيرة العربية، في زمن عرفت فيه الصحراء أمطارًا يصعب تخيّلها.","na":"الصخور البركانية المنقولة","t0":2000000.0,"t1":100000.0},{"id":"bubiyan-coastal-sabkha","n":"Bubiyan Coastal Sabkha","c":"geological","s":"Evaporite Geomorphology","lat":29.86,"lng":48.38,"p":"Holocene","dr":"6,000 years – Present","el":"","desc":"Massive salt flats formed by Holocene pro-delta deposits from the ancient TigrisEuphrates river system. Reinink-Smith & Carter (2022) documented these extensive sabkha surfaces as records of the interplay between river sedimentation, tidal processes, and evaporation in the northern Gulf.","sig":"Records the geological history of the Tigris-Euphrates delta system and its interaction with the Arabian Gulf over the last 6,000 years.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Pro-Delta Salt Flats: Sabkha formed from ancient river delta deposits","Holocene Delta History: Records 6,000 years of Tigris-Euphrates sedimentation","Evaporite Sequences: Multiple layers of salt and gypsum recording climate cycles","Pro-delta salt flats from ancient river deposits","6,000 years of Tigris-Euphrates sedimentation history","Multiple evaporite layers recording climate cycles"],"refs":["Reinink-Smith, L.M. & Carter, R. (2022). Sea-Level Stillstand on Southeastern Bubiyan Island. Quaternary Research"],"ic":"salt","era":"N","te":"Salt Plains of the Delta","ta":"سهول الملح في الدلتا","se":"Wide salt flats cover the island, laid down from river mud over the last 6,000 years. They hold the story of how the great rivers and the Gulf have met.","sa":"سبخات واسعة تغطي الجزيرة، ترسّبت من طمي الأنهار خلال الستة آلاف عام الأخيرة. وهي تحفظ قصة لقاء النهرين العظيمين بالخليج.","na":"سبخة بوبيان الساحلية","t0":6000,"t1":0},{"id":"jal-al-liyah-dunes","n":"Jal Al-Liyah Dunes","c":"geological","s":"Aeolian Geomorphology","lat":29.682,"lng":47.551,"p":"Quaternary – Present","dr":"Active migration","el":"","desc":"Mobile barchan dunes used to measure the current migration rates of the AlShamal wind. These crescent-shaped dunes move across the desert surface at measurable rates, providing real-time data on wind erosion and sand transport that is critical for infrastructure planning and environmental management.","sig":"Natural speedometers for Kuwait’s wind — these moving dunes measure how fast the Shamal wind reshapes the desert landscape.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Barchan Dune Migration: Crescent dunes moving at measurable rates across the desert","Shamal Wind Measurement: Dune movement rates calibrate wind erosion models","Infrastructure Hazard: Migrating dunes threaten roads and structures in their path","Barchan dune migration at measurable rates","Shamal wind erosion calibration from dune movement","Infrastructure hazard from migrating sand dunes"],"refs":["SCIRP (2024). Barchan Dune Migration Rates in Northern Kuwait. Scientific Research Publishing","Remote Sensing (2023). Satellite Monitoring of Dune Migration in Kuwait. Remote Sensing of Environment"],"ic":"dune","era":"N","te":"The Walking Dunes","ta":"الكثبان المتنقلة","se":"Crescent-shaped dunes creep across the desert, pushed by the Shamal. Measure how far they move and you know how hard the wind has blown.","sa":"كثبان على هيئة الهلال تزحف عبر الصحراء تدفعها ريح الشمال. قِس المسافة التي تقطعها تعرف كم كانت الريح شديدة.","na":"كثبان جال الليا","t0":30,"t1":0},{"id":"lower-fars-marine-bed","n":"Lower Fars Marine Bed","c":"geological","s":"Stratigraphy / Palaeontology","lat":29.44,"lng":47.74,"p":"Miocene","dr":"23–5 Ma","el":"","desc":"Exposure of fossiliferous marine layers containing echinoderms and shells reflecting Miocene sea levels. Tanoli et al. (2014) and Al-Sarawi (1995) documented these outcrops as evidence that Kuwait was submerged beneath a shallow tropical sea during the Miocene epoch, with abundant marine life including sea urchins, clams, and corals.","sig":"Direct evidence that Kuwait was once underwater — these marine fossils prove the Arabian Gulf was much larger during the Miocene.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Echinoderm Fossils: Sea urchin remains from the Miocene tropical sea","Marine Shell Beds: Abundant bivalve and gastropod fossils in limestone layers","Miocene Sea Level Record: Fossil layers mark the extent of the ancient Gulf","Echinoderm fossils from the Miocene tropical sea","Abundant bivalve and gastropod shells in limestone","Fossil layers marking the extent of the ancient Gulf"],"refs":["Tanoli, S.K. et al. (2014). Stratigraphy of the Lower Fars Formation in Kuwait. Arabian Journal of Geosciences","Al-Sarawi, M. (1995). Marine Fossils of the Kuwait Region. Kuwait University Press"],"ic":"fossil","era":"D","te":"The Sea That Was Here","ta":"البحر الذي كان هنا","se":"Sea urchins and shells set in limestone prove that this desert was once under a warm sea, back when the Gulf was much larger.","sa":"قنافذ بحر وأصداف مطمورة في الحجر الجيري تثبت أن هذه الصحراء كانت يومًا تحت بحر دافئ، حين كان الخليج أوسع بكثير.","na":"طبقة فارس البحرية السفلى","t0":23000000.0,"t1":5000000.0},{"id":"mud-volcano-outcrops","n":"Mud-Volcano Outcrops (Northern)","c":"geological","s":"Piercement Structures","lat":29.742,"lng":48.092,"p":"Neogene – Quaternary","dr":"20 Ma – Present","el":"","desc":"Localized piercement structures where ancient muds were pushed through sandstone layers by overpressure from depth. These outcrops represent a northern extension of the AlSubiyah mud volcano complex, demonstrating that the subsurface fluid migration system extends further than previously mapped.","sig":"Extends the known range of Kuwait’s mud volcano system northward, suggesting a larger subsurface fluid migration network than previously recognized.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Northern Extension: Mud volcanism extends further north than previously mapped","Piercement Structures: Ancient muds forced through overlying sandstone layers","Subsurface Fluid Network: Evidence of extensive deep fluid migration system","Northern extension of Kuwaits mud volcano system","Piercement structures through overlying sandstone","Evidence of extensive deep fluid migration network"],"refs":["Duane, M.J. et al. (2015). Mud Volcanoes, Seismites, and Other Features of Soft-Sediment Deformation in Coastal Sabkhas, Kuwait. Arabian Journal of Geosciences, 8, 1169-1186"],"ic":"mudvolc","era":"D","te":"The Northern Mud Vents","ta":"منافذ الطين الشمالية","se":"Old mud has pushed up through layers of sandstone here, showing that the hidden plumbing of the mud volcanoes reaches farther north than anyone thought.","sa":"اندفع طين قديم هنا عبر طبقات الحجر الرملي، ليكشف أن الشبكة الخفية للبراكين الطينية تمتد شمالًا أبعد مما ظُن.","na":"نتوءات البراكين الطينية الشمالية","t0":20000000.0,"t1":0},{"id":"wadi-batin-playas","n":"Wadi Al-Batin Playas","c":"geological","s":"Lacustrine Geomorphology","lat":29.3,"lng":46.66,"p":"Quaternary – Present","dr":"Seasonal activity","el":"","desc":"Internally draining basins (Khubrat) that accumulate fine silt and seasonal flora. Al-Hurban & Hassan (2025) and Al-Dousari (2009) documented these ephemeral lake beds where rainwater collects in closed depressions, creating temporary oases that support seasonal wildflowers and provide critical water sources for desert wildlife.","sig":"Desert oases that appear and disappear with the rains — these playas are critical water sources for wildlife and record climate variability in their sediment layers.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Ephemeral Lake Beds: Seasonal water accumulation in closed desert depressions","Seasonal Flora Blooms: Wildflowers emerge after rain, creating temporary green patches","Climate Variability Record: Sediment layers in playas record wet and dry periods","Ephemeral lake beds with seasonal water accumulation","Wildflower blooms creating temporary green patches","Sediment layers recording climate variability"],"refs":["Al-Hurban, A. & Hassan, M. (2025). Morphotectonic Analysis of the Wadi Al-Batin Region. Kuwait Journal of Science","Al-Dousari, A.M. (2009). Playa Lakes and Ephemeral Drainage in Northern Kuwait. Kuwait Journal of Science 4 Ecology & Biology Sites This section contains 16 Kuwait record(s)."],"ic":"plant","era":"N","te":"Lakes That Come and Go","ta":"بحيرات تأتي وتذهب","se":"After the rains, shallow basins fill with water and bloom with wildflowers. Then they dry out again. For desert animals they are precious oases.","sa":"بعد الأمطار تمتلئ أحواض ضحلة بالماء وتزهر بالأزهار البرية، ثم تجف من جديد. وهي لحيوانات الصحراء واحات ثمينة.","na":"بحيرات وادي الباطن الجافة","t0":30,"t1":0},{"id":"jahra-freshwater-lens","n":"Jahra Freshwater Lens & Red Palace Wells","c":"ecology","s":"Hydrology","lat":29.3621,"lng":47.6931,"p":"Holocene – Present","dr":"10,000 BP – Present","el":"","desc":"Below the Jahra Reserve lies a rare geological ‘hydro-trap’ — a freshwater lens floating on denser saltwater. KISR monitoring studies (2024) track the drawdown of this lens, which is critical for the reserve’s ecology. The historic Red Palace (Qasr Al-Ahmar) was strategically built atop this freshwater source, demonstrating that ancient inhabitants understood the hydrogeology. The lens forms where permeable Quaternary sands overlie impermeable clay layers, creating a natural freshwater reservoir in an otherwise arid, saline environment.","sig":"Explains why Jahra has been continuously inhabited for millennia — it sits atop one of Kuwait’s few natural freshwater sources. The freshwater lens is the hydrological engine driving the entire Jahra wetland ecosystem.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Freshwater Lens Mapping: KISR identified a buoyant freshwater body floating on saline groundwater","Red Palace Hydro-Trap: Historic fortress built directly above the freshwater source — ancient hydrogeological knowledge","Lens Drawdown Monitoring: Ongoing studies show the lens is shrinking due to extraction pressure","Freshwater body floating atop saline groundwater","Sustained historic Red Palace wells and Jahra oasis","Foundation of human settlement for millennia","Critical hydrogeological feature of Kuwait Bay"],"refs":["KISR (2024). Groundwater Monitoring Report: Jahra Freshwater Lens Dynamics. Kuwait Institute for Scientific Research","Mukhopadhyay, A. (1995). Groundwater Resources of Kuwait. Kuwait Institute for Scientific Research"],"ic":"well","era":"N","te":"The Floating Sweet Water","ta":"الماء العذب الطافي","se":"Beneath Jahra, fresh water floats on top of heavier salty water like oil on vinegar. This hidden lens fed the wells of the Red Palace and the oasis, which is why people have lived here for thousands of years.","sa":"تحت الجهراء يطفو الماء العذب فوق الماء المالح الأثقل كما يطفو الزيت على الخل. وهذه العدسة الخفية سقت آبار القصر الأحمر والواحة، ولهذا عاش الناس هنا آلاف السنين.","na":"عدسة المياه العذبة - آبار الجهراء","t0":10000.0,"t1":0},{"id":"jahra-halophytes","n":"Halophytic Succession Zone","c":"ecology","s":"Botany","lat":29.3659,"lng":47.6441,"p":"Modern","dr":"Ongoing monitoring","el":"","desc":"This zone hosts Halocnemum strobilaceum, a remarkable ‘biological sensor’ plant whose health directly indicates groundwater salinity levels. The plant survives extreme conditions by sequestering salt in specialized leaf structures, which eventually drop and enrich the surrounding soil. The halophytic succession here follows a precise gradient from the most salt-tolerant species near the coast to less tolerant species inland, creating a living map of the subsurface salinity profile. Acacias and Tamarisks in the reserve act as a natural phytoremediation system, filtering excess nitrates and phosphates from treated water before it reaches the marine mudflats.","sig":"A living laboratory for studying plant adaptation to extreme salinity. The halophytic gradient serves as a biological proxy for mapping invisible groundwater chemistry, and the phytoremediation function protects the marine ecosystem downstream.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Halocnemum Salinity Sensor: Plant health directly correlates with groundwater salinity measurements","Salt Sequestration Mechanism: Leaves accumulate and drop salt, creating enriched soil microhabitats","Natural Phytoremediation: Acacias and Tamarisks filter nitrates/phosphates from treated water inflows","Distinct plant zonation based on salinity gradients","Salt-tolerant species succession from bare sabkha to meadows","Ecological adaptation to extreme saline conditions","Important habitat for migratory birds"],"refs":["Al-Henaidi, M. (2023). Salinity Tolerance of Native Flora in the Jahra Protected Zone. Kuwait Journal of Botany","Omar, S.A.S. (2001). Vegetation of Kuwait. Kuwait Institute for Scientific Research"],"ic":"plant","era":"N","te":"Gardens That Love Salt","ta":"حدائق تحب الملح","se":"Walk from the bare salt flat inland and the plants change in neat bands, each one suited to a different level of salt. They even soak up salt and clean the water before it reaches the sea.","sa":"امشِ من السبخة الجرداء نحو الداخل فترى النباتات تتغير في أشرطة منتظمة، كل منها يناسب درجة مختلفة من الملوحة. بل إنها تمتص الملح وتنقّي الماء قبل أن يصل إلى البحر.","na":"منطقة التعاقب الملحي النباتي","t0":30,"t1":0},{"id":"basra-reed-warbler","n":"Basra Reed Warbler Breeding Pocket","c":"ecology","s":"Ornithology","lat":29.3585,"lng":47.7012,"p":"Modern","dr":"Annual breeding season","el":"","desc":"This is a high-resolution nesting site for the globally threatened Basra Reed Warbler (Acrocephalus griseldis). Census data shows that the density of nesting pairs here is among the highest in the Middle East, directly linked to the specific height (2.5–3 meters) of the Phragmites reeds. The site is part of a broader avian corridor: recent satellite tracking (2023–2025) of the Greater Spotted Eagle shows that raptors use thermal updrafts created by the Jal Az-Zor ridge to the north, then ‘drop in’ to the Jahra Reserve for hydration — making this area literally a ‘gas station’ for international migratory travelers.","sig":"One of the most important breeding sites in the Middle East for the globally threatened Basra Reed Warbler. The reserve’s position on the migratory flyway, combined with its thermal corridor from Jal Az-Zor, makes it a critical node in the international avian migration network.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Record Nesting Density: Among the highest Basra Reed Warbler nesting densities recorded in the Middle East","Reed Height Dependency: Nesting success directly linked to Phragmites reed height of 2.5–3 meters","Raptor Thermal Corridor: Greater Spotted Eagles use Jal Az-Zor updrafts to reach this ‘refueling station’","Breeding habitat for IUCN Endangered Basra Reed Warbler","One of southernmost breeding sites for the species","Critical reed bed habitat along Jahra coast","Species primarily found in southern Iraq marshes"],"refs":["BirdLife International (2024). Special Report: The Basra Reed Warbler in the Kuwaiti Wetlands. BirdLife Conservation Series","BirdLife International (2023). Acrocephalus griseldis. IUCN Red List of Threatened Species"],"ic":"bird","era":"N","te":"Home of a Rare Songbird","ta":"موطن طائر مغرّد نادر","se":"In a small patch of reeds, an endangered songbird comes to raise its young. This is one of the southernmost places it nests, a precious stop for a bird that mostly lives in the marshes to the north.","sa":"في رقعة صغيرة من القصب يأتي طائر مغرّد مهدد بالانقراض ليربّي صغاره. وهذا من أبعد أماكن تعشيشه جنوبًا، محطة ثمينة لطائر يعيش في الغالب في الأهوار شمالًا.","na":"جيب تكاثر هازجة البصرة","t0":30,"t1":0},{"id":"jahra-mudflat-nursery","n":"Mudflat Benthic Nursery","c":"ecology","s":"Marine Biology","lat":29.3675,"lng":47.762,"p":"Modern","dr":"Ongoing monitoring","el":"","desc":"This zone is studied for its Benthic Macroinvertebrates — crabs, snails, and polychaete worms that form the base of the food chain sustaining migratory birds. The specific mud chemistry (high organic content, moderate salinity, anaerobic subsurface) creates ideal conditions for these organisms. Without this precise biochemical cocktail, the eagles, flamingos, and waders that depend on this food source would not survive their stopovers. The mudflat also serves as a nursery for juvenile fish and crustaceans that later populate Kuwait Bay.","sig":"The invisible engine of the entire Jahra ecosystem. The benthic community converts detritus into biomass that feeds the charismatic megafauna (birds, fish) that make the reserve internationally significant.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Benthic Biodiversity Hotspot: High density of macroinvertebrates supporting the entire food web","Mud Chemistry Profile: Specific organic/salinity/oxygen conditions creating ideal nursery habitat","Juvenile Fish Nursery: Critical spawning ground for species that populate Kuwait Bay","Critical nursery for juvenile fish and shrimp","Nutrient-rich benthic habitat","Dense populations of worms, crustaceans, mollusks","Base of the marine food web in Kuwait Bay"],"refs":["EPA Kuwait (2024). Benthic Ecology of the Jahra Coastal Mudflats. Environment Public Authority Technical Report","Al-Yamani, F. (2004). Oceanographic Atlas of Kuwait’s Waters. Kuwait Institute for Scientific Research"],"ic":"crab","era":"N","te":"The Mud Nursery","ta":"حضانة الطين","se":"The mud may look empty, but it is packed with worms, crabs and tiny shellfish. They feed young fish and shrimp, which feed the birds. Everything here starts in the mud.","sa":"قد يبدو الطين خاليًا، لكنه يعجّ بالديدان والسرطانات والرخويات الصغيرة. وهي غذاء صغار الأسماك والروبيان، التي تصبح بدورها غذاءً للطيور. كل شيء هنا يبدأ من الطين.","na":"حضانة القاع الطيني","t0":30,"t1":0},{"id":"iris-playa-meadow","n":"Iris Playa Meadow (Khabra)","c":"ecology","s":"Biological Refugia","lat":29.5262,"lng":47.8138,"p":"Seasonal","dr":"Annual bloom cycle","el":"","desc":"A natural depression (Khabra) where seasonal moisture collects, creating a ‘Biological Refugia’ — a pocket of life that survives because the underlying clay layers hold rainwater like a bowl. During the brief spring season, Desert Iris and native grasses bloom here, creating a striking green anomaly visible on satellite imagery (high NDVI signature). The depression also marks a sharp change in the strike direction of the escarpment ridge, with a high Sinuosity Index indicating tectonic deformation rather than simple wind erosion. This makes the Khabra both a botanical wonder and a structural geology indicator.","sig":"Demonstrates how geology controls ecology: the clay-lined depression is a product of differential erosion along a fault bend, and the trapped water creates a micro-ecosystem in the desert. Analogous to the Playa Lakes of the Texas High Plains.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Desert Iris Bloom: Seasonal flowering of rare desert iris species in a moisture-trapping depression","NDVI Vegetation Anomaly: Visible as a ‘green spot’ on satellite imagery in an otherwise barren landscape","Fault Bend Indicator: The depression marks a change in escarpment strike direction — tectonic, not erosional","Seasonal playa with wild iris blooms","Ephemeral desert ecosystem","Remarkable resilience of desert flora","Iris bulbs survive extreme summer heat underground"],"refs":["EPA Kuwait (2024). Flora Survey of the Jal Az-Zor Biological Refugia. Environment Public Authority Technical Report","Omar, S.A.S. (2001). Vegetation of Kuwait. Kuwait Institute for Scientific Research"],"ic":"plant","era":"N","te":"The Iris Meadow","ta":"مرج السوسن","se":"For most of the year this dry lake bed looks lifeless. After winter rain it turns purple with wild irises, whose bulbs waited underground through the scorching summer.","sa":"معظم أيام السنة يبدو قاع البحيرة الجاف هذا بلا حياة. وبعد مطر الشتاء يكتسي بالبنفسجي بأزهار السوسن البري، التي انتظرت أبصالها تحت الأرض طوال الصيف الحارق.","na":"مرج السوسن - الخبرة","t0":30,"t1":0},{"id":"sabriya-oil-ecology","n":"Sabriya Oil Field Ecology","c":"ecology","s":"Industrial Ecology","lat":29.721,"lng":47.854,"p":"Modern","dr":"1950s – Present","el":"","desc":"Dr. Sarah Al-Ateeqi’s research documents the ecological footprint of the Sabriya Oil Field in northern Kuwait. The study reveals how decades of hydrocarbon extraction have created a unique industrial-ecological interface where native desert flora and fauna adapt to chronic lowlevel contamination. Soil sampling shows elevated heavy metal concentrations (Cd, Pb, Cr, Ni) in a gradient pattern radiating from wellheads and gathering centers. Remarkably, certain halophytic species (Zygophyllum qatarense, Haloxylon salicornicum) show phytoremediation capacity, accumulating metals in their tissues. The site demonstrates both the environmental cost of oil production and nature’s resilience.","sig":"Provides baseline ecological data for Kuwait’s largest northern oil field. Al-Ateeqi’s heavy metal gradient mapping enables targeted remediation planning and demonstrates that native desert plants can serve as biomonitors and phytoremediators for petroleum-contaminated soils.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Heavy Metal Gradient Mapping: Systematic soil sampling reveals Cd, Pb, Cr, Ni concentration gradients radiating from wellheads","Phytoremediation Capacity: Native halophytes accumulate heavy metals, offering natural soil cleanup potential","Adapted Desert Fauna: Certain lizard and insect species persist in contaminated zones, showing behavioral adaptation","Heavy metal gradient mapping reveals Cd, Pb, Cr, Ni concentration patterns radiating from wellheads","Native halophytes demonstrate phytoremediation capacity, accumulating metals in tissues","Certain lizard and insect species persist in contaminated zones, showing behavioral adaptation"],"refs":["Al-Ateeqi, S. (2024). Heavy Metal Contamination and Phytoremediation Potential in Kuwait’s Northern Oil Fields. Kuwait University Environmental Science Thesis"],"ic":"oil","era":"N","te":"Plants That Clean the Soil","ta":"نباتات تنظّف التربة","se":"Around the oil wells, metals have built up in the soil. Yet some tough desert plants pull those metals into their leaves and stems. Nature is helping to heal the land.","sa":"حول آبار النفط تراكمت المعادن في التربة. ومع ذلك تسحب بعض نباتات الصحراء الصلبة هذه المعادن إلى أوراقها وسيقانها. الطبيعة تساعد في شفاء الأرض.","na":"بيئة حقل الصابرية النفطي","t0":76,"t1":0},{"id":"bahra-ecology","n":"Bahra Area Ecology","c":"ecology","s":"Desert Ecology","lat":29.635,"lng":47.92,"p":"Modern","dr":"Ongoing monitoring","el":"","desc":"The Bahra area, famous for its archaeological sites, also hosts a distinctive desert ecosystem studied by Dr. Al-Ateeqi. The transition zone between the coastal sabkha and inland desert creates a unique ecological gradient. Soil analysis reveals that the ancient Ubaid-period occupation layers have altered the soil chemistry, creating ‘anthropogenic soil islands’ with higher organic content and different microbial communities compared to surrounding virgin desert. These enriched patches support denser vegetation, creating a visible ‘green halo’ effect around archaeological sites — a phenomenon that could aid remote sensing detection of undiscovered sites.","sig":"Demonstrates the deep interconnection between archaeology and ecology — 7,000-year-old human activity has permanently altered the desert soil, creating ecological hotspots that persist to this day. This ‘archaeological ecology’ concept has implications for site discovery using vegetation indices.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Anthropogenic Soil Islands: Ancient occupation layers create enriched soil patches with higher organic content","Green Halo Effect: Denser vegetation around archaeological sites visible on satellite imagery","Microbial Community Shifts: Distinct soil microbiome in ancient occupation zones vs. virgin desert","Anthropogenic soil islands with higher organic content from 7,000-year-old occupation layers","Green halo effect: denser vegetation around archaeological sites visible on satellite imagery","Distinct soil microbiome in ancient occupation zones vs. virgin desert"],"refs":["Al-Ateeqi, S. (2024). Ecological Assessment of the Bahra Desert Transition Zone. Kuwait University Environmental Science Thesis"],"ic":"plant","era":"N","te":"The Green Halo","ta":"الهالة الخضراء","se":"Seven thousand years after the first villagers left, their old homes still change the soil. Plants grow thicker over these spots, drawing a green halo around ancient sites that can even help reveal new ones.","sa":"بعد سبعة آلاف عام من رحيل أوائل القرويين، ما زالت بيوتهم القديمة تغيّر التربة. فالنباتات تنمو أكثف فوق هذه البقع، راسمةً هالة خضراء حول المواقع القديمة قد تساعد في كشف مواقع جديدة.","na":"بيئة منطقة بحرة","t0":30,"t1":0},{"id":"um-al-aish-ecology","n":"Um Al-Aish Ecology","c":"ecology","s":"Wetland Ecology","lat":29.568,"lng":47.735,"p":"Modern","dr":"Ongoing monitoring","el":"","desc":"Um Al-Aish is a critical wetland area in northern Kuwait where Dr. Al-Ateeqi’s research focuses on the interaction between groundwater discharge and surface ecology. The site features seasonal marshes fed by shallow aquifer seepage, creating a rare freshwater-to-brackish gradient in the desert. The wetland supports a surprisingly diverse invertebrate community including dragonflies, water beetles, and freshwater snails — species typically absent from Kuwait’s arid landscape. The area also serves as a stopover for migratory waterbirds on the Central Asian Flyway, with recent surveys recording over 40 bird species during peak migration.","sig":"One of Kuwait’s few natural wetland ecosystems, Um Al-Aish demonstrates how subsurface hydrology creates surface biodiversity hotspots in arid environments. The site is critical for understanding groundwater-ecology linkages and for migratory bird conservation.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Freshwater-Brackish Gradient: Rare salinity gradient supporting diverse aquatic invertebrate communities","Migratory Bird Stopover: Over 40 bird species recorded during peak migration seasons","Aquifer Seepage Mapping: Groundwater discharge zones identified through vegetation and temperature anomalies","Rare freshwater-to-brackish salinity gradient supporting diverse aquatic invertebrate communities","Over 40 migratory bird species recorded during peak migration seasons","Groundwater discharge zones identified through vegetation and temperature anomalies"],"refs":["Al-Ateeqi, S. (2024). Wetland Ecology and Groundwater Interactions at Um Al-Aish, Northern Kuwait. Kuwait University Environmental Science Thesis"],"ic":"bird","era":"N","te":"The Desert Wetland","ta":"الأهوار الصحراوية","se":"Water seeping from underground forms seasonal marshes in the middle of the desert. Dragonflies, water beetles and snails thrive here, and more than 40 kinds of birds stop by on their long migration.","sa":"ماء يتسرب من باطن الأرض يكوّن أهوارًا موسمية في قلب الصحراء. تزدهر هنا اليعاسيب وخنافس الماء والقواقع، وتتوقف أكثر من 40 نوعًا من الطيور في رحلة هجرتها الطويلة.","na":"بيئة أم العيش","t0":30,"t1":0},{"id":"sabah-al-ahmad-reserve","n":"Sabah Al-Ahmad Natural Reserve","c":"ecology","s":"Conservation Ecology","lat":29.576,"lng":47.804,"p":"Modern","dr":"Established 2004 – Present","el":"","desc":"The Sabah Al-Ahmad Natural Reserve is Kuwait’s largest protected area, spanning over 330 km². Dr. Al-Ateeqi’s research here focuses on ecosystem recovery following protection from grazing and off-road vehicle damage. Long-term vegetation monitoring plots show that native perennial grasses (Stipagrostis plumosa, Panicum turgidum) have increased by 340% since protection began, while invasive species have declined. The reserve also hosts reintroduced Arabian oryx and sand gazelle populations. Soil crust studies reveal that biological soil crusts (cyanobacteria, mosses, lichens) — destroyed by decades of overgrazing — are slowly reforming, stabilizing the soil and reducing dust emissions.","sig":"Provides the most comprehensive long-term dataset on desert ecosystem recovery in the Arabian Peninsula. The biological soil crust recovery data is particularly significant as it demonstrates that even severely degraded desert ecosystems can regenerate when protected.","ex":"","conf":"","ev":"","an":"","val":"","disc":["340% Vegetation Recovery: Native perennial grasses tripled since protection from grazing began","Biological Soil Crust Reformation: Cyanobacteria and lichen crusts slowly rebuilding after decades of destruction","Reintroduced Species Success: Arabian oryx and sand gazelle populations establishing viable breeding groups","340% increase in native perennial grasses since protection from grazing began","Biological soil crust reformation: cyanobacteria and lichen crusts slowly rebuilding","Reintroduced Arabian oryx and sand gazelle establishing viable breeding groups"],"refs":["Al-Ateeqi, S. (2024). Long-term Vegetation Recovery in the Sabah Al-Ahmad Natural Reserve. Kuwait University Environmental Science Thesis"],"ic":"gazelle","era":"N","te":"The Desert Comes Back to Life","ta":"عودة الحياة إلى الصحراء","se":"Protect a piece of desert and watch what happens. Since grazing and off-road driving stopped, native grasses have grown more than four times over. Oryx and gazelles have returned, and the living crust that holds the soil together is slowly coming back.","sa":"احمِ قطعة من الصحراء وراقب ما يحدث. منذ توقف الرعي وقيادة السيارات خارج الطرق، تضاعفت الأعشاب المحلية أكثر من أربع مرات. وعادت المها والغزلان، والقشرة الحية التي تمسك التربة تعود ببطء.","na":"محمية صباح الأحمد الطبيعية","t0":22,"t1":0},{"id":"burgan-oil-ecology","n":"Burgan Oil Field Ecology","c":"ecology","s":"Post-War Ecology","lat":29.068,"lng":47.978,"p":"Modern","dr":"1991 – Present","el":"","desc":"The Burgan Oil Field — the world’s second-largest oil field — suffered catastrophic environmental damage during the 1991 Gulf War when over 700 oil wells were set ablaze. Dr. Al-Ateeqi’s research documents the 35-year ecological recovery trajectory. Soil contamination from oil lakes and soot fallout created a ‘dead zone’ that is slowly being recolonized by pioneer species. Remarkably, certain areas show accelerated recovery where oil-degrading bacteria (Pseudomonas, Bacillus) have naturally bioaugmented the soil. The research also tracks heavy metal (V, Ni, Cr) bioaccumulation in desert plants growing on contaminated soil, providing critical data for human health risk assessment.","sig":"The longest-running study of post-war ecological recovery in the Arabian Gulf. Demonstrates that natural bioremediation by soil bacteria can significantly reduce petroleum contamination over decades, but heavy metal persistence remains a long-term concern.","ex":"","conf":"","ev":"","an":"","val":"","disc":["35-Year Recovery Trajectory: Systematic documentation of ecological succession on oil-contaminated desert soil","Natural Bioremediation: Oil-degrading bacteria (Pseudomonas, Bacillus) naturally cleaning contaminated soil","Heavy Metal Bioaccumulation: Desert plants accumulating V, Ni, Cr from contaminated soil — health risk data","35-year systematic documentation of ecological succession on oil-contaminated desert soil","Natural bioremediation by oil-degrading bacteria (Pseudomonas, Bacillus) cleaning contaminated soil","Heavy metal bioaccumulation (V, Ni, Cr) in desert plants providing health risk data 700"],"refs":["Al-Ateeqi, S. (2024). Post-War Ecological Recovery in the Greater Burgan Oil Field. Kuwait University Environmental Science Thesis"],"ic":"oil","era":"N","te":"Healing After the Fires","ta":"التعافي بعد الحرائق","se":"In 1991 more than 700 oil wells were set on fire here. Since then, tiny soil bacteria have been quietly eating the oil, and the desert has been recovering for over three decades.","sa":"في عام 1991 أُشعلت النيران في أكثر من 700 بئر نفطية هنا. ومنذ ذلك الحين تلتهم بكتيريا التربة الدقيقة النفط بصمت، والصحراء تتعافى منذ أكثر من ثلاثة عقود.","na":"بيئة حقل برقان النفطي","t0":35,"t1":0},{"id":"umm-gudair-ecology","n":"Umm Gudair Field Ecology","c":"ecology","s":"Arid Zone Ecology","lat":28.985,"lng":47.762,"p":"Modern","dr":"Ongoing monitoring","el":"","desc":"The Umm Gudair oil field in southwestern Kuwait represents one of the most extreme arid environments in the country. Dr. Al-Ateeqi’s research here examines how oil field infrastructure (pipelines, roads, gathering centers) inadvertently creates microhabitats for desert wildlife. Pipeline berms trap windblown sand and moisture, creating linear ‘oases’ where vegetation density is 5x higher than surrounding desert. These green corridors serve as movement pathways for desert foxes, hedgehogs, and dhub lizards. The study also documents the impact of gas flaring on nocturnal insect behavior, with moths and beetles attracted to flare stacks from distances exceeding 10 km.","sig":"Reveals the unintended ecological consequences of oil field infrastructure — both positive (microhabitat creation) and negative (light pollution disrupting nocturnal fauna). Provides practical recommendations for ‘ecological engineering’ of future oil field developments.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Pipeline Oasis Effect: Pipeline berms create linear microhabitats with 5x vegetation density","Wildlife Corridors: Desert foxes and hedgehogs use pipeline berms as movement pathways","Gas Flare Light Pollution: Nocturnal insects attracted from 10+ km, disrupting desert food webs","Pipeline berms create linear microhabitats with 5x vegetation density","Desert foxes and hedgehogs use pipeline berms as movement corridors","Gas flare light pollution attracts nocturnal insects from 10+ km, disrupting desert food webs"],"refs":["Al-Ateeqi, S. (2024). Ecological Impacts of Oil Field Infrastructure in Southwestern Kuwait. Kuwait University Environmental Science Thesis"],"ic":"oil","era":"N","te":"Oases Along the Pipelines","ta":"واحات على امتداد الأنابيب","se":"Pipeline banks trap sand and moisture, so plants grow five times thicker along them. Foxes, hedgehogs and dhub lizards use these green lines as roads across the desert.","sa":"تحبس ضفاف الأنابيب الرمل والرطوبة، فتنمو النباتات على امتدادها أكثف بخمس مرات. وتتخذ الثعالب والقنافذ والضبّان من هذه الخطوط الخضراء طرقًا عبر الصحراء.","na":"بيئة حقل أم قدير","t0":30,"t1":0},{"id":"um-al-rros-ecology","n":"Um Al-Rros Military Base Ecology","c":"ecology","s":"Military Ecology","lat":29.152,"lng":47.538,"p":"Modern","dr":"Ongoing monitoring","el":"","desc":"The Um Al-Rros area in western Kuwait hosts military training grounds where Dr. Al-Ateeqi’s research examines the ecological impact of military vehicle traffic on desert soil and vegetation. Heavy tracked vehicles compact the desert surface, destroying the biological soil crust and creating ‘deflation hollows’ where wind erosion accelerates. However, abandoned tank berms and foxholes from the 1991 Gulf War have inadvertently become wildlife refugia — the depressions trap rainwater and windblown seeds, creating micro-ecosystems. Desert monitors (Varanus griseus) and spiny-tailed lizards (Uromastyx aegyptia) preferentially use old military structures for thermoregulation and nesting.","sig":"Demonstrates the dual nature of military land use — destruction of soil crusts and vegetation by active training, but creation of wildlife habitat in abandoned structures. Provides data for balancing military readiness with environmental conservation in Kuwait’s western desert.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Soil Crust Destruction Mapping: Tracked vehicle paths destroy biological soil crusts, accelerating erosion","Foxhole Wildlife Refugia: Abandoned Gulf War structures now serve as lizard nesting and thermoregulation sites","Deflation Hollow Formation: Vehicle compaction creates wind erosion features that reshape the desert surface","Tracked vehicle paths destroy biological soil crusts, accelerating wind erosion","Abandoned Gulf War foxholes and berms now serve as lizard nesting and thermoregulation sites","Deflation hollows from vehicle compaction reshape the desert surface topography"],"refs":["Al-Ateeqi, S. (2024). Military Land Use and Desert Ecology in Western Kuwait. Kuwait University Environmental Science Thesis"],"ic":"trench","era":"N","te":"Lizards in the Old Trenches","ta":"سحالي في الخنادق القديمة","se":"Heavy vehicles crush the fragile desert crust. Yet old wartime trenches and berms have become shelters where desert monitors and spiny-tailed lizards warm up and nest.","sa":"تسحق المركبات الثقيلة قشرة الصحراء الهشة. ومع ذلك صارت الخنادق والسواتر القديمة من زمن الحرب ملاجئ يتدفأ فيها الورل والضبّ ويعششان.","na":"بيئة قاعدة أم الروس العسكرية","t0":30,"t1":0},{"id":"khor-sabiyah-marsh","n":"Khor As-Sabiyah Marsh","c":"ecology","s":"RAMSAR Wetland","lat":29.584,"lng":48.156,"p":"Holocene – Present","dr":"6,000 years – Present","el":"","desc":"A RAMSAR-designated wetland critical for Blue Carbon storage and migratory bird biodiversity. Omar & Roy (2024) documented this marsh as one of Kuwait’s most important ecological sites, supporting hundreds of migratory bird species and serving as a significant carbon sink through its saltmarsh and mangrove vegetation.","sig":"Kuwait’s most important wetland for biodiversity and climate change mitigation through Blue Carbon sequestration.","ex":"","conf":"","ev":"","an":"","val":"","disc":["RAMSAR Designation: Internationally recognized wetland of global importance","Blue Carbon Storage: Saltmarsh vegetation sequesters significant atmospheric carbon","Migratory Bird Hub: Critical stopover for hundreds of species on the Central Asian Flyway","RAMSAR-designated wetland of international importance","Blue Carbon storage through saltmarsh vegetation","Critical stopover for migratory birds on Central Asian Flyway"],"refs":["Ramsar Convention (2015). Khor As-Sabiyah Wetland: RAMSAR Site Designation. Ramsar Convention Secretariat","Omar, S. & Roy, S. (2024). Blue Carbon Ecosystems of Kuwait Bay. Kuwait Institute for Scientific Research"],"ic":"bird","era":"N","te":"The Marsh That Stores Carbon","ta":"الهور الذي يخزّن الكربون","se":"A wetland of international importance where migrating birds gather in great numbers. Its salt-marsh plants also lock carbon away in the mud, helping fight climate change.","sa":"أراضٍ رطبة ذات أهمية دولية تتجمع فيها الطيور المهاجرة بأعداد كبيرة. كما تحبس نباتات الهور الملحي الكربون في الطين، فتساعد في مواجهة تغيّر المناخ.","na":"هور خور الصبية","t0":6000,"t1":0},{"id":"mubarak-reserve","n":"Mubarak Reserve","c":"ecology","s":"Marine Conservation","lat":29.932,"lng":48.181,"p":"Modern","dr":"Ongoing conservation","el":"","desc":"Habitat for the Indo-Pacific humpback dolphin and the Bubiyan Cow oyster reefs. This marine reserve on Kuwait’s northern coast supports some of the Gulf’s most important marine biodiversity, including endangered dolphin populations and unique oyster reef ecosystems that filter water and provide habitat for hundreds of species.","sig":"Kuwait’s most important marine conservation area, protecting endangered dolphins and unique oyster reef ecosystems found nowhere else in the northern Gulf.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Humpback Dolphin Habitat: Resident population of endangered Indo-Pacific humpback dolphins","Bubiyan Cow Oyster Reefs: Unique oyster reef ecosystem filtering water and supporting biodiversity","UNESCO Tentative List: Nominated for UNESCO recognition as a marine heritage site","Endangered Indo-Pacific humpback dolphin resident population","Bubiyan Cow oyster reef ecosystem","UNESCO Tentative List marine heritage nomination )"],"refs":["UNESCO Tentative List (2024). Mubarak Reserve Marine Heritage Nomination. UNESCO World Heritage Centre","MMPA (2024). Marine Mammal Protection in Kuwait Waters. Marine Mammal Protection Authority"],"ic":"dolphin","era":"N","te":"Where Dolphins Live","ta":"حيث تعيش الدلافين","se":"Humpback dolphins live in these waters, and rare oyster reefs grow on the sea floor. It is one of Kuwait’s most precious marine treasures.","sa":"تعيش الدلافين الحدباء في هذه المياه، وتنمو شعاب محار نادرة على قاع البحر. إنها من أثمن كنوز الكويت البحرية.","na":"محمية مبارك","t0":30,"t1":0},{"id":"arfaj-steppe-habitat","n":"Arfaj Steppe Habitat","c":"ecology","s":"Desert Ecology","lat":29.5,"lng":47.8,"p":"Holocene – Present","dr":"Ongoing ecosystem","el":"","desc":"Dense Rhanterium epapposum (Arfaj) communities that biologically stabilize the sandy Dibdibba surface. Omar & Roy (2013) and Brown (2001) documented how these hardy desert shrubs form the backbone of Kuwait’s desert ecosystem, preventing sand movement and supporting diverse wildlife communities.","sig":"Kuwait’s national flower (Arfaj) is also its most important ecological engineer — stabilizing desert surfaces and supporting the entire food web.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Biological Sand Stabilization: Arfaj roots bind sand particles, preventing desertification","National Flower Ecosystem: Rhanterium communities support Kuwait’s desert food web","Grazing Impact Studies: Overgrazing by camels threatens Arfaj steppe integrity","Biological sand stabilization by Arfaj root systems","Kuwaits national flower supporting the desert food web","Overgrazing threatens Arfaj steppe integrity"],"refs":["Omar, S. & Roy, S. (2013). Rhanterium Steppe Communities of Kuwait. Kuwait Institute for Scientific Research","Brown, G. (2001). Desert Vegetation of Kuwait. Kuwait University Press"],"ic":"plant","era":"N","te":"The National Flower at Work","ta":"الزهرة الوطنية في عملها","se":"The arfaj is Kuwait’s national flower, and it is also a hard worker. Its roots hold the sand in place, and its shelter feeds and protects a whole web of desert life.","sa":"العرفج زهرة الكويت الوطنية، وهو أيضًا عامل مجتهد. فجذوره تثبّت الرمال، وظلّه يطعم ويحمي شبكة كاملة من حياة الصحراء.","na":"موئل سهوب العرفج","t0":30,"t1":0},{"id":"bubiyan-mangrove-plot","n":"Bubiyan Mangrove Plot","c":"ecology","s":"Marine Ecology / Carbon Sequestration","lat":29.895,"lng":48.31,"p":"Modern","dr":"Ongoing research","el":"","desc":"Avicennia marina re-introduction site and study area for carbon sequestration in northern deltas. KFAS Research (2024) and Omar (2014) documented efforts to restore mangrove forests on Bubiyan Island, which serve as critical nursery habitats for fish and shrimp while sequestering atmospheric carbon at rates far exceeding terrestrial forests.","sig":"Kuwait’s frontline in the fight against climate change — mangrove restoration on Bubiyan could sequester thousands of tonnes of carbon annually.","ex":"","conf":"","ev":"","an":"","val":"","disc":["Mangrove Re-Introduction: Avicennia marina successfully replanted on Bubiyan Island","Carbon Sequestration: Mangroves store carbon 5x faster than terrestrial forests","Fish Nursery Habitat: Restored mangroves support juvenile fish and shrimp populations","Avicennia marina successfully replanted on Bubiyan Island","Carbon sequestration rates 5x faster than terrestrial forests","Restored mangroves support juvenile fish and shrimp populations"],"refs":["KFAS Research (2024). Mangrove Restoration and Carbon Sequestration on Bubiyan Island. Kuwait Foundation for the Advancement of Sciences","Omar, S. (2014). Mangrove Ecosystems of Kuwait. Kuwait Institute for Scientific Research 5 Speculative / AI-Detected Features This section contains 5 Kuwait record(s)."],"ic":"mangrove","era":"N","te":"The Young Mangrove Forest","ta":"غابة القرم الفتية","se":"Mangrove trees are being planted again on Bubiyan. They grow with their roots in salt water, shelter baby fish and pull carbon from the air faster than forests on land.","sa":"تُزرع أشجار القرم من جديد في بوبيان. تنمو وجذورها في الماء المالح، وتؤوي صغار الأسماك، وتسحب الكربون من الهواء أسرع من غابات اليابسة.","na":"قطعة أشجار القرم في بوبيان","t0":30,"t1":0},{"id":"spec-seepage-mounds","n":"Dark Seepage Mounds","c":"speculative","s":"Possible Fluid Seepage","lat":29.59,"lng":48.08,"p":"Active / Ongoing","dr":"Pleistocene–Present","el":"","desc":"Satellite imagery reveals several dark reddish-brown circular mound features (10– 30 m diameter) on the lighter desert surface south of Subiyah. These features are distinctly different from the surrounding terrain in both color and texture, appearing as a loose cluster. The surrounding terrain shows lighter patches of possible gypcrete or salt crust, while the mounds themselves are anomalously dark — suggesting iron-oxide staining, bitumen seepage, or cemented sand from paleo-liquefaction events.","sig":"If confirmed as fluid seepage features, these mounds would extend the known footprint of Behbehani et al.‘s (2019) deep-fault hydrothermal system southward, demonstrating that basementto-surface fluid migration is more widespread than previously documented. Alternatively, if they are paleo-liquefaction features, they would expand the spatial extent of Bou-Rabee et al.’s (2020) prehistoric earthquake evidence.","ex":"","conf":"Untested AI speculation (shape seen on satellite imagery)","ev":"Satellite imagery shows distinct dark circular features (10–30 m) on lighter desert surface. Color and morphology are inconsistent with aeolian or sabkha processes. Located in the structural corridor between known hydrothermal (Behbehani) and liquefaction (Bou-Rabee) sites.","an":"Similar dark seepage mounds are documented at the Bahrah oil seep area (Behbehani et al., 2019) and at onshore mud volcano sites in Azerbaijan’s Absheron Peninsula, where subsurface fluids stain surface sediments. Kuwait’s own oil history is the closest analogue: surface bitumen seeps at Burgan (reported 1912) guided Burgan No. 1, spudded at a seep in 1936 and successful on 23 February 1938 (GeoExpro). Remote sensing of hydrocarbon microseepage (e.g. bleached red beds in Lisbon Valley, Utah; Petrovic et al. 2006) shows such alteration can be mapped from imagery.","val":"Ground-truth visit to check for hydrocarbon odor or mineral crusts. Portable XRF analysis of the dark material. Shallow auger drilling to test for cemented sand or bitumen. Helium soil gas survey following Behbehani et al.‘s methodology.","disc":["Circular Dark Mounds: Multiple dark reddish-brown features visible on satellite imagery, roughly circular and 10–30 m in diameter, clustered on the desert surface","Color Anomaly: The dark coloration is inconsistent with typical aeolian sand or sabkha deposits, suggesting either mineral staining from subsurface fluids or cemented sediment","Proximity to Known Features: Located between the documented Bahrah hydrothermal system and the Bou-Rabee liquefaction field stops, in a zone where both processes could be active","AI-detected dark circular features on satellite imagery","Possible hydrocarbon or fluid seepage","Requires ground-truthing verification","Potential subsurface petroleum migration indicators"],"refs":["Behbehani, S. et al. (2019). Deep-seated faults and hydrothermal circulation in the Bahrah area. Marine and Petroleum Geology. DOI: 10.1016/j.marpetgeo.2019.01.003","Bou-Rabee, F., Young, Y.L. & Okal, E.A. (2020). Evidence of prehistoric liquefaction in Kuwait. Natural Hazards. DOI: 10.1007/s11069-020-04013-9","GeoExpro. The Great Burgan Field, Kuwait (history of the Bahrah and Burgan seeps and the 1938 discovery). geoexpro.com/the-great-burgan-field-kuwait","Petrovic, A., Khan, S. & Chafetz, H. (2006). Finding hydrocarbon-induced alterations in Lisbon Valley, Utah: hyperspectral remote sensing and geochemical studies. AAPG Search and Discovery Article #90052."],"ic":"eye","era":"?","te":"The Dark Circles","ta":"الدوائر الداكنة","se":"Satellite images show dark round patches, 10 to 30 metres across, on the pale desert. Could fluids be leaking up from deep below? Nobody has walked out to check yet. Maybe one day you will.","sa":"تُظهر صور الأقمار الصناعية بقعًا دائرية داكنة بقطر 10 إلى 30 مترًا على الصحراء الفاتحة. هل تتسرب سوائل من الأعماق؟ لم يذهب أحد للتحقق بعد. ربما تكون أنت أول من يفعل.","na":"تلال التسرب الداكنة","spec":{"bas":"shape","key":"seeps","sty":"ai-seeps","spot":{"en":"Spotted by its shape on high-resolution satellite imagery: a loose cluster of dark, round patches 10–30 m across on the pale desert south of Subiya. Nobody has checked them on the ground yet.","ar":"رُصد من شكله في صور فضائية عالية الدقة: مجموعة متفرقة من البقع الدائرية الداكنة بقطر 10 إلى 30 مترًا على الصحراء الفاتحة جنوب الصبية. لم يتحقق منها أحد على الأرض بعد."},"lk":[["bahrah-hydrothermal","Deep faults here leak oil and gas towards the surface","صدوع عميقة هنا تسرّب النفط والغاز نحو السطح"],["mud-volcano-z1","Ground that once breathed water and gas","أرض كانت تنفث الماء والغاز يومًا"],["paleo-liquefaction","Earthquake-made sand dikes on the same coast","سدود رملية صنعها زلزال على الساحل نفسه"],["h3-site","Ubaid boat-builders coated reed boats with Kuwaiti bitumen","بناة قوارب العبيد طلوا قوارب القصب بقار كويتي"],["burgan-oil-ecology","Where surface seeps led to the 1938 oil discovery","حيث قادت التسربات السطحية إلى اكتشاف النفط عام 1938"]],"pred":{"en":"The dark material contains bitumen or oil-stained sand, and the soil gas over the circles is richer in methane or helium than the ground around them.","ar":"تحتوي المادة الداكنة على قار أو رمل مشبّع بالنفط، ويكون غاز التربة فوق الدوائر أغنى بالميثان أو الهيليوم من الأرض المحيطة."},"test":{"en":"Walk out, smell and sample the patches; scan them with a portable XRF; auger a metre down; compare soil gas inside and outside the circles.","ar":"الذهاب إلى البقع وشمّها وأخذ عينات منها، وفحصها بجهاز XRF محمول، والحفر بمثقاب يدوي مترًا واحدًا، ومقارنة غاز التربة داخل الدوائر وخارجها."},"wrong":{"en":"If the dark material is burnt camp debris, dark gravel or plant litter with no hydrocarbons, the seep idea fails.","ar":"إذا كانت المادة الداكنة بقايا نار مخيم أو حصى داكنًا أو بقايا نباتية بلا هيدروكربونات، تسقط فكرة التسرب."}},"t0":2580000.0,"t1":0},{"id":"spec-polychrome-escarpment","n":"Jal Az-Zor Polychrome Exposure","c":"speculative","s":"Possible Hydrothermal Alteration","lat":29.62,"lng":48.015,"p":"Eocene–Quaternary","dr":"56 Ma – Present","el":"","desc":"At the Jal Az-Zor escarpment face, satellite imagery reveals dramatic multicolored terrain that is highly unusual for Kuwait’s typically monochrome desert. Bright orange-red terrain grades into grey-purple patches and white-cream bands, with the color zonation following the topographic contours of the escarpment. Dendritic drainage channels cut into the terrain, exposing different colored layers. This polychrome pattern suggests either differential weathering of distinct geological formations or, more intriguingly, hydrothermal alteration of the rock by ascending fluids.","sig":"If the orange-red coloration is confirmed as iron-oxide staining from hydrothermal fluids, this would provide surface evidence of the deep-fault fluid migration system described by Behbehani et al. (2019) manifesting at the Jal Az-Zor escarpment — a location not previously identified as part of this system. The escarpment could serve as a natural geological cross-section exposing the fluid pathways.","ex":"","conf":"Untested AI speculation (shape seen on satellite imagery)","ev":"Satellite imagery shows dramatic color variations (orange-red, grey-purple, white-cream) at the escarpment face. The color banding follows topographic contours. The orange-red is inconsistent with typical aeolian deposits and suggests iron-oxide enrichment.","an":"Similar polychrome escarpment exposures are seen at Jebel Hafeet (UAE) and in the Zagros Mountains (Iran), where different geological formations and hydrothermal alteration create a ‘layer cake’ of colors visible from satellite. Closest documented analogue: bleaching of red beds by hydrocarbon microseepage in Lisbon Valley, Utah, mapped with AVIRIS, ASTER and Hyperion and confirmed geochemically (Petrovic et al. 2006).","val":"Geological mapping traverse along the escarpment face with systematic rock sampling. XRD/XRF analysis to identify mineral composition of each color zone. Thin-section petrography to check for hydrothermal alteration minerals (e.g., hematite, goethite, kaolinite).","disc":["Orange-Red Iron Staining: Bright orange-red terrain visible on satellite imagery, highly unusual for Kuwait’s desert and suggestive of iron-oxide-rich deposits or laterite-like weathering","Grey-Purple Shale Exposure: Patches of grey-purple material that could be exposed Lower Fars Formation shale or clay-rich layers with possible hydrothermal alteration","Multi-Layer Color Banding: The color zonation follows topographic contours, suggesting different geological formations are exposed in a natural cross-section","AI-detected vivid polychrome banding","Possible undocumented mineral assemblages","Potential hydrothermal alteration zones","Enhanced color variation requiring investigation"],"refs":["Behbehani, S. et al. (2019). Deep-seated faults and hydrothermal circulation in the Bahrah area. Marine and Petroleum Geology. DOI: 10.1016/j.marpetgeo.2019.01.003","Khalaf, F.I. & Al-Zamel, A. (2014). Petrography and mineralogy of Quaternary gypcrete. Arabian Journal of Geosciences","Petrovic, A., Khan, S. & Chafetz, H. (2006). Finding hydrocarbon-induced alterations in Lisbon Valley, Utah: hyperspectral remote sensing and geochemical studies. AAPG Search and Discovery Article #90052."],"ic":"eye","era":"?","te":"The Rainbow Cliff","ta":"الجرف الملوّن","se":"One stretch of the great cliff glows with unusually bright orange, red and purple bands. Is hot water from deep faults staining the rock? The answer is waiting to be found.","sa":"جزء من الجرف العظيم يتوهج بأشرطة برتقالية وحمراء وبنفسجية زاهية على غير العادة. هل تصبغ المياه الحارة القادمة من الصدوع العميقة الصخر؟ الجواب ينتظر من يكتشفه.","na":"التكشف متعدد الألوان في جال الزور","spec":{"bas":"shape","key":"colours","sty":"ai-colours","spot":{"en":"Spotted by colour on high-resolution satellite imagery: orange-red, grey-purple and cream bands that follow the contours of the Jal Az-Zor escarpment face, unusual in Kuwait’s mostly single-coloured desert.","ar":"رُصد من لونه في صور فضائية عالية الدقة: أشرطة برتقالية حمراء ورمادية بنفسجية وكريمية تتبع خطوط الكنتور على واجهة جال الزور، وهو أمر غير معتاد في صحراء الكويت ذات اللون الواحد غالبًا."},"lk":[["jal-az-zor","The escarpment where the bands appear","الحافة التي تظهر عليها الأشرطة"],["dextral-slip-fault","A fault zone that could guide rising fluids","نطاق صدعي قد يوجّه السوائل الصاعدة"],["bahrah-hydrothermal","Hot fluids rising from deep below","سوائل حارة صاعدة من الأعماق"],["bahra-1","Ubaid potters about 6 km away who needed pigment","خزّافو العبيد على بعد نحو 6 كم احتاجوا إلى الأصباغ"]],"pred":{"en":"The colour bands match changes in iron and clay minerals; the pale zones line up with faults or fractures and carry traces of hydrocarbons or hydrothermal minerals.","ar":"تتوافق الأشرطة الملونة مع تغيّر في معادن الحديد والطين، وتصطف المناطق الفاتحة على الصدوع أو الشقوق وتحمل آثار هيدروكربونات أو معادن حرارية مائية."},"test":{"en":"Walk a sampling line across the bands; identify the minerals (XRD, XRF); compare satellite and field spectra; compare red-band chemistry with the pigment on Bahra 1 pottery.","ar":"أخذ عينات على خط يعبر الأشرطة، وتحديد المعادن (XRD وXRF)، ومقارنة الطيف الفضائي بالطيف الميداني، ومقارنة كيمياء الشريط الأحمر بأصباغ فخار بحرة 1."},"wrong":{"en":"If each colour is simply a different original sediment layer with no alteration, the seep idea fails (the pigment idea could still stand).","ar":"إذا كان كل لون مجرد طبقة رسوبية أصلية مختلفة بلا تغيّر كيميائي، تسقط فكرة التسرب (وقد تبقى فكرة الصبغة قائمة)."}},"t0":56000000.0,"t1":0},{"id":"spec-submerged-kathma","n":"Submerged Dark Feature (Kathma)","c":"speculative","s":"Possible Submerged Site","lat":29.37,"lng":47.83,"p":"Unknown","dr":"Possibly Holocene","el":"","desc":"In the shallow waters off the western Kuwait Bay coast near Kathma, satellite imagery reveals a large dark oval feature approximately 200 m across, distinctly darker than the surrounding shallow water. The feature sits on a clear paleoshoreline transition zone where the desert surface meets the tidal flat. The water color gradients show beautiful bathymetric detail — turquoise for very shallow areas grading to dark blue for deeper water — and this dark feature stands out as anomalous against the lighter shallow-water background.","sig":"Kathma (Kadhima) is historically one of the most important sites in the Gulf — it was a major pre-Islamic trading port and the site of the Battle of Dhat al-Salasil (630 AD). If this submerged feature is archaeological, it could represent remains of the ancient harbor infrastructure or a submerged settlement from when sea levels were different. If geological, it could be an exposed bedrock outcrop of the Dammam Formation on the seabed.","ex":"","conf":"Untested AI speculation (shape seen on satellite imagery)","ev":"Satellite imagery shows a discrete dark oval ( 200 m) in shallow water near the historically significant Kathma coast. The feature is morphologically distinct from surrounding seabed. Located at a paleoshoreline transition zone.","an":"Similar dark submerged features near known archaeological coasts have been identified as submerged settlement remains at Dwarka (India) and Pavlopetri (Greece). In the Gulf, submerged Neolithic sites have been found off Abu Dhabi. Documented analogue: Atlit-Yam, a 9,000-year-old Pre-Pottery Neolithic village c. 400 m off the Carmel coast, one of 23 submerged prehistoric sites along that coast (Galili et al. 2017; Galili & Horwitz 2025).","val":"Snorkeling or diving survey at low tide to visually inspect the feature. Side-scan sonar to map the seabed morphology. If solid material is found, sediment cores for dating. Drone-based bathymetric LiDAR for high-resolution depth mapping.","disc":["Dark Oval Anomaly: A roughly oval dark feature 200 m across visible in shallow water, distinctly different from surrounding seabed","Paleoshoreline Context: Located at the transition between desert surface and tidal flat, in a zone that would have been dry land during lower sea levels","Historical Significance: Kathma was a major pre-Islamic trading port — any submerged features here have high archaeological potential","AI-detected seafloor dark anomaly near Kadhima","Possible sunken archaeological site","Proximity to historic Kadhima port","High-priority target for underwater investigation"],"refs":["Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record. Geoarchaeology","Carter, R.A. (2006). Boat remains and maritime trade in the Arabian Gulf. Antiquity","Galili, E. et al. (2017). Atlit-Yam: a unique 9000 year old prehistoric village submerged off the Carmel coast. In: Under the Sea: Archaeology and Palaeolandscapes of the Continental Shelf. Coastal Research Library, Springer, 85–102. DOI: 10.1007/978-3-319-53160-1_6"],"ic":"eye","era":"?","te":"The Shadow Under the Sea","ta":"الظل تحت البحر","se":"Near the old caravan port, a dark oval shape lies on the sea floor. It could be a sunken harbour, a natural rock or a seep. Only a dive will tell.","sa":"قرب ميناء القوافل القديم يرقد شكل بيضاوي داكن على قاع البحر. قد يكون مرفأً غارقًا، أو صخرًا طبيعيًا، أو تسربًا. وحدها الغوصة ستكشف الحقيقة.","na":"المعلم المغمور الداكن (كاظمة)","spec":{"bas":"shape","key":"drowned","sty":"ai-drowned","spot":{"en":"Spotted by its shape on high-resolution satellite imagery: a dark oval about 200 m across in the shallow water off Kazma, with a sharper edge than the seabed around it.","ar":"رُصد من شكله في صور فضائية عالية الدقة: شكل بيضاوي داكن بعرض نحو 200 متر في المياه الضحلة قبالة كاظمة، حافته أوضح من قاع البحر المحيط به."},"lk":[["kazma-shoreline","The shoreline of 6,000 years ago on this coast","خط الساحل قبل 6,000 عام على هذا الشاطئ"],["holocene-sea-level","When, and how high, the sea rose","متى ارتفع البحر وإلى أي حد"],["kadhima","A later water-rich hub on the same corner of the bay","مركز لاحق غني بالماء في الركن نفسه من الجون"],["jahra-mudflat-nursery","Living mudflats: another way to darken the seabed","مسطحات طينية حية: سبب آخر لعتمة القاع"]],"pred":{"en":"Sonar will show straight edges or stone alignments, and short cores will hit an old land surface (soil, hearths, tools) beneath the marine mud.","ar":"ستُظهر أجهزة السونار حوافًّا مستقيمة أو صفوفًا من الحجارة، وستصل العينات اللبية القصيرة إلى سطح أرض قديم (تربة أو مواقد أو أدوات) تحت الطين البحري."},"test":{"en":"Snorkel or dive at low tide; run side-scan sonar and a drone survey; take short sediment cores and date any buried soil.","ar":"الغطس عند الجزر، والمسح بالسونار الجانبي وبطائرة مسيّرة، وأخذ عينات لبية قصيرة من الرواسب وتأريخ أي تربة مدفونة."},"wrong":{"en":"If it is a seagrass meadow, a patch of beachrock or dredge spoil, the drowned-site idea fails.","ar":"إذا تبيّن أنه مرج من الأعشاب البحرية أو صخر شاطئي أو ركام تجريف، تسقط فكرة الموقع الغارق."}},"t0":11700,"t1":0},{"id":"spec-failaka-platform","n":"Failaka NW Submerged Platform","c":"speculative","s":"Possible Drowned Coastal Plain","lat":29.465,"lng":48.265,"p":"Early Holocene","dr":"10,000–6,000 BP","el":"","desc":"Satellite imagery reveals a large submerged shallow platform extending northwest from Failaka Island. The water color gradients clearly show a broad area of very shallow water (turquoisegreen) with a sharp drop-off to deeper water (dark blue) to the west and north. The platform has an irregular but roughly arcuate shape. On the adjacent Failaka coast, the Tal Sa’ida Archaeological Site and other antiquities markers confirm the area’s archaeological significance. During the early Holocene when sea level was approximately 15 m lower than present, this entire platform would have been dry land — potentially forming a land bridge or near-connection between Failaka and the mainland.","sig":"This submerged platform may preserve evidence of early Holocene human occupation or migration routes. Rutkowski & Kiersnowski’s (2025) sea-level curve shows that around 8000 BP, sea level was low enough for this platform to be exposed. The Ubaid-period settlers at Bahra 1 (across the bay) could have used this land connection. Any archaeological remains on the platform would predate the known Dilmun-era sites on Failaka by thousands of years.","ex":"","conf":"Untested AI speculation (shape seen on satellite imagery)","ev":"Satellite imagery shows clear bathymetric contrast between a large shallow platform (turquoise) and surrounding deep water (dark blue). The platform extends NW from Failaka where multiple archaeological sites exist. Sea-level reconstructions confirm this area was exposed during early Holocene human occupation.","an":"Similar drowned coastal platforms with archaeological significance include the Doggerland between Britain and Europe, the Sunda Shelf in Southeast Asia, and submerged Neolithic sites off the coast of Israel (Atlit-Yam). Analogues: Doggerland, mapped over c. 45,000 km² from oil-industry seismic reflection data and checked with cores (Gaffney et al. 2007); the Gulf Oasis model, in which the basin was exposed until flooding c. 8,000 years ago and more than 60 coastal sites appear c. 7,500 years ago (Rose 2010).","val":"Multibeam bathymetric survey to map the platform’s detailed morphology. Subbottom profiler to identify buried sediment layers. Grab samples or vibrocores for sediment dating. If shallow enough, systematic diving survey for archaeological material.","disc":["Shallow Platform Morphology: A large area of very shallow water extending NW from Failaka, with a sharp bathymetric drop-off — suggesting a drowned coastal plain or terrace","Proximity to Archaeological Sites: Tal Sa’ida Archaeological Site and other antiquities are located on the adjacent coast, confirming human occupation of this shoreline","Sea-Level Reconstruction: Rutkowski & Kiersnowski’s data shows this platform was dry land during the early Holocene, when Ubaid-period settlers were active in the region","AI-detected submerged platform near Failaka","Possible drowned coastal terrace or harbor structure","4,000-year archaeological context","Potential sea-level highstand marine terrace"],"refs":["Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record. Geoarchaeology","Carter, R.A. & Crawford, H. (2010). Maritime Interactions in the Arabian Neolithic. Brill","Gaffney, V., Thomson, K. & Fitch, S. (eds) (2007). Mapping Doggerland: The Mesolithic Landscapes of the Southern North Sea. Oxford: Archaeopress.","Rose, J.I. (2010). New light on human prehistory in the … Gulf Oasis. Current Anthropology 51(6). DOI: 10.1086/657397"],"ic":"eye","era":"?","te":"The Drowned Shore","ta":"الشاطئ الغارق","se":"A flat platform hides under the water near the island. Eight thousand years ago the sea was low enough for it to be dry land. Did early people walk here?","sa":"منصة مسطحة تختبئ تحت الماء قرب الجزيرة. قبل ثمانية آلاف عام كان البحر منخفضًا بما يكفي لتكون أرضًا يابسة. هل سار عليها البشر الأوائل؟","na":"المنصة المغمورة شمال غرب فيلكا","spec":{"bas":"shape","key":"dogger","sty":"ai-dogger","spot":{"en":"Spotted by water colour on satellite imagery: a broad turquoise shallow platform reaching north-west from Failaka, with a sharp edge against deeper blue water.","ar":"رُصد من لون الماء في الصور الفضائية: رصيف ضحل واسع بلون فيروزي يمتد شمال غرب فيلكا، بحافة حادة أمام الماء الأزرق الأعمق."},"lk":[["failaka-island","The island at the edge of the platform","الجزيرة على حافة الرصيف"],["h3-site","A village from the time new coastal settlements appear","قرية من زمن ظهور المستوطنات الساحلية الجديدة"],["bahra-1","Another Ubaid village of that time","قرية أخرى من عصر العبيد في ذلك الزمن"],["holocene-sea-level","The record of the rising sea","سجل ارتفاع البحر"],["spec-submerged-kathma","Another possible drowned site in the bay","موقع غارق محتمل آخر في الجون"]],"pred":{"en":"Seismic or sub-bottom profiles will show buried river channels and old land surfaces under the platform, and cores from them will hold freshwater shells, plant remains or tools older than 8,000 years.","ar":"ستُظهر المقاطع الزلزالية أو مقاطع ما تحت القاع قنوات أنهار مدفونة وأسطح أرض قديمة تحت الرصيف، وستحمل العينات اللبية منها أصداف مياه عذبة أو بقايا نباتية أو أدوات أقدم من 8,000 عام."},"test":{"en":"Re-use oil-industry and port-survey seismic data, as was done for Doggerland; run sub-bottom profiles; core the channels and date them.","ar":"إعادة استخدام البيانات الزلزالية لصناعة النفط ومسوحات الموانئ كما حدث في دوغرلاند، وإجراء مسوح لما تحت القاع، وأخذ عينات لبية من القنوات وتأريخها."},"wrong":{"en":"If the platform is only a recent sand bank or reef flat with no buried land surface, the drowned-land idea fails here.","ar":"إذا كان الرصيف مجرد ضحل رملي حديث أو سطح شعاب بلا أرض قديمة مدفونة، تسقط فكرة الأرض الغارقة هنا."}},"t0":10000.0,"t1":6000},{"id":"spec-bubiyan-paleotidal","n":"Bubiyan Paleotidal Creek Network","c":"speculative","s":"Paleoenvironmental Archive","lat":29.72,"lng":48.2,"p":"Holocene","dr":"6,000 BP – Present","el":"","desc":"Bubiyan Island’s western surface displays an extraordinary network of tidal creeks and channels visible on satellite imagery. Dense dendritic tidal creek patterns cover the entire flat surface, appearing as darker lines against the tan-pink sabkha. Some channels appear to be abandoned and filled while others remain active. A prominent darker band running east-west across the surface may represent a paleoshoreline or geological contact. This network preserves a multi-layered record of tidal processes operating at different sea-level stages during the Holocene.","sig":"The abandoned tidal creeks on Bubiyan could preserve a continuous record of Holocene sea-level changes. During the highstand (+2–3.5 m, 6000–4000 BP per Rutkowski & Kiersnowski), much more of Bubiyan would have been submerged. The current tidal creek pattern may overprint older channel systems from different sea-level stages, creating a palimpsest that can be ‘read’ through careful geomorphological analysis. This would provide independent validation of the sea-level curve derived from the Al-Subiyah coast.","ex":"","conf":"Untested AI speculation (shape seen on satellite imagery)","ev":"Satellite imagery shows dense dendritic tidal creek patterns with both active and abandoned channels. A prominent E-W dark band suggests a paleoshoreline. The multi-generation creek network is consistent with sea-level fluctuations documented by Rutkowski & Kiersnowski.","an":"Similar paleotidal creek networks have been used to reconstruct Holocene sealevel histories on the Trucial Coast (UAE), in the Mesopotamian marshes (Iraq), and on the Ranns of Kutch (India). Analogue: the Abu Dhabi coastal sabkha and tidal flats, studied since the 1960s as the modern key to ancient carbonate–evaporite successions in the region, some of which host major hydrocarbon reservoirs (Alsharhan & Kendall 2003; Lokier 2013).","val":"High-resolution drone survey to map active vs. abandoned creek channels. Sediment cores at creek intersections to date different channel generations. OSL dating of abandoned channel fills. Comparison with Rutkowski & Kiersnowski’s sea-level curve to correlate channel abandonment with sea-level drops.","disc":["Multi-Generation Creek Network: Satellite imagery reveals both active and abandoned tidal creeks, suggesting the network records multiple sea-level stages","E-W Dark Band: A prominent darker band crossing the surface may represent a paleoshoreline position or a geological contact between different sediment types","Sabkha Surface Patterns: The tan-pink sabkha surface shows differential coloration that may reflect varying mineral compositions related to past tidal inundation levels","AI-detected paleo-tidal channel system","Former tidal pathways from different sea levels","Evidence of island geomorphological evolution","Part of Shatt Al-Arab delta system history"],"refs":["Rutkowski, Ł. & Kiersnowski, H. (2025). Holocene Sea-Level Changes and the Archaeological Record. Geoarchaeology","Duane, M.J. et al. (2015). Mud volcanoes and seismites in sabkhas. Sedimentary Geology","Alsharhan, A.S. & Kendall, C.G.St.C. (2003). Holocene coastal carbonates and evaporites of the southern Arabian Gulf and their ancient analogues. Earth-Science Reviews 61(3–4), 191–243.","Lokier, S.W. (2013). Coastal sabkha preservation in the Arabian Gulf. Geoheritage."],"ic":"eye","era":"?","te":"The Island’s Hidden Veins","ta":"العروق الخفية للجزيرة","se":"From space, Bubiyan is covered in branching channels like veins. Some are alive with the tide, others long abandoned. Together they may record every rise and fall of the sea.","sa":"من الفضاء تبدو بوبيان مغطاة بقنوات متفرعة كالعروق. بعضها حيّ مع المد، وبعضها مهجور منذ زمن. وقد تحفظ معًا كل ارتفاع وانخفاض للبحر.","na":"شبكة المد القديمة في بوبيان","spec":{"bas":"shape","key":"creeks","sty":"ai-creeks","spot":{"en":"Spotted by its pattern on satellite imagery: dense, tree-like tidal creeks across western Bubiyan, some active and some abandoned, crossed by a dark east–west band that may be an old shoreline.","ar":"رُصد من نمطه في الصور الفضائية: خيران مدّية كثيفة متفرعة كالأشجار في غرب بوبيان، بعضها نشط وبعضها مهجور، يقطعها شريط داكن من الشرق إلى الغرب قد يكون خط ساحل قديمًا."},"lk":[["bubiyan-coastal-sabkha","The salt flat these creeks cut through","السبخة التي تشقّها هذه الخيران"],["holocene-sea-level","The highs and falls of the sea the creeks may record","ارتفاعات البحر وانخفاضاته التي قد تسجلها الخيران"],["shell-midden-smq24","Shell gatherers who followed the old shore","جامعو الأصداف الذين تتبعوا الساحل القديم"],["bubiyan-mangrove-plot","A living coast being restored today","ساحل حي يُستعاد اليوم"]],"pred":{"en":"Abandoned creek generations will date to times when the sea fell after its highstands, and shell middens on Bubiyan and Subiya will line the banks of old creeks rather than today’s shore.","ar":"ستعود أجيال الخيران المهجورة إلى أزمنة انخفض فيها البحر بعد ارتفاعه، وستصطف أكوام الأصداف في بوبيان والصبية على ضفاف الخيران القديمة لا على الساحل الحالي."},"test":{"en":"Map active and abandoned channels from drone images; core the channel fills and date them (OSL, radiocarbon); survey old creek banks for shell middens.","ar":"رسم خرائط القنوات النشطة والمهجورة بصور الطائرات المسيّرة، وأخذ عينات لبية من رواسب القنوات وتأريخها (OSL والكربون المشع)، ومسح ضفاف الخيران القديمة بحثًا عن أكوام الأصداف."},"wrong":{"en":"If all the channel generations turn out to be the same age, or younger than the last fall of the sea, they are not a sea-level calendar.","ar":"إذا تبيّن أن أجيال القنوات كلها بالعمر نفسه، أو أحدث من آخر انخفاض للبحر، فهي ليست تقويمًا لمستوى البحر."}},"t0":6000,"t1":0},{"id":"ahmadi-quarry","n":"Al-Ahmadi Quarry (Dammam Formation outcrop)","na":"محجر الأحمدي (تكشّف تكوين الدمام)","c":"geological","s":"Palaeokarst / Reservoir Analogue","lat":29.07,"lng":48.07,"p":"Middle–Late Eocene (Dammam Formation)","dr":"c. 48–34 Ma (rocks); karst formed later","el":"","desc":"A quarry on the top of the Al-Ahmadi ridge, part of the Greater Burgan oil field, exposes the oldest rocks at Kuwait’s surface: Eocene carbonates of the Dammam Formation, overlain along an unconformity by Mio-Pleistocene clastics of the Kuwait Group. The quarry walls cut a palaeokarst zone 2–14 m thick, divided from bottom to top into Chalky Dolostone, Karst Zone, Karst Carapace, Weathered Zone and Residual Clastics. Location shown is approximate (Al-Ahmadi ridge); the studies do not publish exact coordinates.","sig":"Described as a unique geological window into Kuwait’s oldest exposed rocks, and studied as a surface analogue for subsurface carbonate reservoirs. Diagenetic alunite in the karst cavity fills has been interpreted as a sign of hydrocarbon gas seeping up from depth, and later pores have been attributed to meteoric water and/or acidic gases from the maturation of deep source rocks.","ex":"Kuwait University (F. Abdullah, F. Khalaf, I. Gharib) and Kuwait Oil Company geologists; access supported by the Al-Ahmadi quarry management","conf":"","ev":"","an":"","val":"","disc":["Oldest Rocks at the Surface: Eocene Dammam Formation carbonates exposed in the quarry walls, beneath an unconformity with the Kuwait Group.","Five-Unit Palaeokarst Profile: Chalky Dolostone, Karst Zone, Karst Carapace, Weathered Zone and Residual Clastics, 2–14 m thick.","Extreme Porosity: up to about 78% in the Karst Zone and 53% in the chalky dolostone, with permeability up to about 6,000 mD; most pores are isolated moldic and vuggy pores.","Cavity-Fill Dolocretes: hard dolocrete crusts that formed in three stages within the karst dolostone and karst carapace.","Diagenetic Alunite: alunite in karst cavity fills, interpreted as an indicator of hydrocarbon gas seeps from the Burgan field below.","Early Dolomitization: tidal-flat and lagoon muds turned to dolostone early, through sabkha brines mixing with fresh water."],"refs":["Khalaf, F.I., Abdullah, F.A. & Gharib, I.M. (2018). Petrography, diagenesis and isotope geochemistry of dolostones and dolocretes in the Eocene Dammam Formation, Kuwait, Arabian Gulf. Carbonates and Evaporites 33, 87–105.","Abdullah, F.H. (2024). Diagenetic and Petrographic Changes in Carbonate Rocks along Unconformity – Dammam Formation Exposure in Kuwait. First EAGE Workshop on Advances in Carbonate Reservoirs. DOI: 10.3997/2214-4609.2024634055","Porosity and permeability of karst carbonate rocks along an unconformity outcrop: A case study from the Upper Dammam Formation exposure in Kuwait, Arabian Gulf (2021). Heliyon. https://www.sciencedirect.com/science/article/pii/S2405844021015474","Abdullah, F., Khalaf, F. & Gharib, I. (2016). Porosity and permeability study of a karst carbonate rocks along unconformity outcrop: Upper Dammam Formation exposure in Kuwait. 32nd IAS International Meeting of Sedimentology, Marrakech.","Occurrence of diagenetic alunites within karst cavity infill of the Dammam Formation, Ahmadi, Kuwait: an indicator of hydrocarbon gas seeps (2014). Arabian Journal of Geosciences.","Petrography and diagenesis of cavity-fill dolocretes, Kuwait (2013). Geoderma. Kuwait University authors (F. Abdullah, F. Khalaf).","Kuwait Times (6 Oct 2026). Kuwait’s 10 geological systems form open-air natural museum."],"ic":"cliff","era":"D","te":"The Window into Deep Time","ta":"نافذة على الزمن السحيق","se":"In the walls of a quarry on the Ahmadi ridge you can touch the oldest rocks at Kuwait’s surface, laid down in a warm, shallow sea more than 35 million years ago. Water later dissolved holes and caves inside them, leaving rock so full of spaces that in places more than half of it is empty. Geologists come here to understand the hidden rocks that hold oil deep below.","sa":"في جدران محجر على حافة الأحمدي يمكنك أن تلمس أقدم الصخور على سطح الكويت، وقد ترسّبت في بحر دافئ ضحل قبل أكثر من 35 مليون عام. ثم أذاب الماء فيها ثقوبًا وكهوفًا، فصارت الصخور مليئة بالفراغات حتى إن أكثر من نصفها فارغ في بعض الأماكن. ويأتي الجيولوجيون إلى هنا ليفهموا الصخور الخفية التي تحمل النفط في الأعماق.","t0":48000000.0,"t1":34000000.0},{"id":"spec-bahra-quake","n":"Earthquake and the End of Bahra 1","c":"speculative","s":"Cross-category hypothesis","lat":29.641,"lng":47.972,"p":"Ubaid / Middle Holocene","dr":"c. 5000–4800 BC (test window)","el":"","desc":"A connection between two records on this map. Bahra 1, the largest Ubaid-related settlement known outside Mesopotamia, was occupied c. 5500–4900 BC and then abandoned. A few kilometres east, Bou-Rabee, Young & Okal (2020) describe cemented sand and gravel-filled dikes along the Jazirat Dubaij / Jal Az-Zor coast that point to a single large seismic event (strong shaking or seiching) about 7,000 years ago, and note that the work may help explain the disappearance of an ancient population that lived in the region at that time. Earthquake-related seismites and mud volcanoes in the Subiya sabkha (Duane et al. 2015) show that this coast has liquefied more than once.","sig":"If an earthquake ended or hastened the end of Bahra 1, it would be one of the oldest known cases of a settlement abandoned after a seismic event in Arabia, and a direct input to the seismic hazard assessment of northern Kuwait.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Dates: Bahra 1 abandonment c. 4900 BC (c. 6,900 years ago); liquefaction event c. 7,000 years ago (Bou-Rabee et al. 2020). Proximity: liquefaction dikes, seismites and mud-volcano zones lie 5–10 km east of Bahra 1. Mechanism: shaking strong enough to liquefy sand would crack floors and walls on the same coast.","an":"Helike (Gulf of Corinth, Greece) was destroyed by an earthquake and seismic sea wave in 373 BC; cores from the delta later yielded ceramic fragments throughout the upper 12 m, showing that the settlement landscape was buried rather than lost (Soter et al. 2001).","val":"Inspect excavation trenches at Bahra 1 for clastic dikes, sand blows, tilted or fractured floors; date dikes and the layers they cut and seal (OSL, radiocarbon); test for a common fall direction of walls; compare with shoreline (sea-level) and climate records for the same centuries.","disc":["Rival explanation 1: shoreline change during the Holocene transgression moved the coast and resources away from the village.","Rival explanation 2: climatic drying in the mid-Holocene reduced water and grazing.","Rival explanation 3: social or economic change in the Ubaid world, unrelated to the environment."],"refs":["Bou-Rabee, F., Young, Y.L. & Okal, E.A. (2020). Evidence of prehistoric liquefaction in Kuwait and implications for the seismic vulnerability of the Arabian Gulf countries. Natural Hazards 103(1), 799–813. DOI: 10.1007/s11069-020-04013-9","Soter, S., Blackwelder, P., Tziavos, C., Katsonopoulou, D., Hood, T. & Alvarez Zarikian, C.A. (2001). Environmental analysis of cores from the Helike Delta, Gulf of Corinth, Greece. Journal of Coastal Research 17(1), 95–106.","Duane, M.J., Reinink-Smith, L., Eastoe, C. & Al-Mishwat, A.T. (2015). Mud volcanoes and evaporite seismites in a tidal flat of northern Kuwait. Geo-Marine Letters 35, 237–246. DOI: 10.1007/s00367-015-0403-9"],"ic":"spark","era":"?","te":"Did the Earth Shake Bahra Empty?","ta":"هل أفرغ الزلزال بحرة؟","se":"Kuwait’s biggest Ubaid village fell silent about 7,000 years ago, just when an earthquake turned the sand of this coast to liquid. Coincidence, or cause? Nobody has tested it yet.","sa":"صمتت أكبر قرية من عصر العبيد في الكويت قبل نحو 7,000 عام، في الوقت نفسه الذي حوّل فيه زلزالٌ رمالَ هذا الساحل إلى سائل. مصادفة أم سبب؟ لم يختبر أحد ذلك بعد.","na":"الزلزال ونهاية بحرة 1","spec":{"bas":"link","key":"quake","sty":"ai-quake","spot":{"en":"Born from a coincidence of dates on this map. Bahra 1 was abandoned around 4900 BC, about 6,900 years ago. On the same coast, Bou-Rabee and colleagues (2020) found sand dikes made by one large seismic event about 7,000 years ago, and suggested it may help explain why the people who lived here disappeared.","ar":"وُلدت الفكرة من تطابق تواريخ على هذه الخريطة: هُجرت بحرة 1 نحو 4900 ق.م، أي قبل نحو 6,900 عام. وعلى الساحل نفسه وجدت بورابي وزملاؤها (2020) سدودًا رملية صنعها حدث زلزالي واحد كبير قبل نحو 7,000 عام، ورأوا أنه قد يساعد في تفسير اختفاء من عاشوا هنا."},"lk":[["bahra-1","The village that fell silent around 4900 BC","القرية التي صمتت نحو 4900 ق.م"],["paleo-liquefaction","Sand dikes from one large seismic event, c. 7,000 years ago","سدود رملية من حدث زلزالي واحد كبير قبل نحو 7,000 عام"],["sabkha-seismites","Layers deformed by earthquakes in the sabkha","طبقات شوّهتها الزلازل في السبخة"],["mud-volcano-z2","Mud volcanoes squeezed up by shaking","براكين طينية دفعها الاهتزاز إلى السطح"],["holocene-sea-level","The rival explanation: a moving shoreline","التفسير المنافس: ساحل متحرك"]],"pred":{"en":"At Bahra 1, sand dikes or cracked, tilted floors will cut the last occupation layers and be sealed by sediment laid down after people left, and their dates will overlap 4900 BC.","ar":"في بحرة 1 ستقطع السدود الرملية أو الأرضيات المتشققة والمائلة آخر طبقات السكن، وستغطيها رواسب تراكمت بعد رحيل الناس، وستتداخل تواريخها مع 4900 ق.م."},"test":{"en":"Look for liquefaction features in the excavation trenches; date the dikes and the layers they cut; check whether walls fell in one direction; compare with shoreline and climate records of the same centuries.","ar":"البحث عن آثار التسييل في خنادق التنقيب، وتأريخ السدود والطبقات التي تقطعها، والتحقق مما إذا كانت الجدران قد سقطت في اتجاه واحد، والمقارنة بسجلات الساحل والمناخ في القرون نفسها."},"wrong":{"en":"If the dikes are centuries older or younger than the abandonment, or the village faded slowly with no damage, the earthquake idea fails.","ar":"إذا كانت السدود أقدم أو أحدث من الهجر بقرون، أو تلاشت القرية ببطء دون أضرار، تسقط فكرة الزلزال."}},"t0":7500,"t1":6800},{"id":"spec-bitumen-trail","n":"The Bitumen Trail: Burgan to Subiya","c":"speculative","s":"Cross-category hypothesis","lat":29.1,"lng":47.93,"p":"Ubaid to 1938","dr":"c. 5500 BC – AD 1938","el":"","desc":"A connection across 7,000 years. Bitumen on the boat remains at H3 (c. 5500–5000 BC), which carry barnacles on one side and reed-bundle impressions on the other and are the earliest evidence of seagoing vessels, was traced geochemically to Burgan, inland Kuwait (Connan et al. 2005; restated in Connan & Carter 2007). The same Burgan seeps were described by a geologist in 1912 and guided Burgan No. 1, spudded at a seep in 1936 and successful on 23 February 1938. Bahra 1, the larger Ubaid village, lies near a different leak: the Bahrah seeps, surveyed in 1914 and 1917, above the Bahrah deep-fault system.","sig":"Tests whether Kuwait’s Ubaid communities exploited more than one local bitumen source, and whether the Burgan seeps were visited (camps, processing sites) 7,000 years before oil drilling.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"H3 bitumen = Burgan source (Connan & Carter 2007). Bahrah seeps documented historically (GeoExpro). No published source analysis of Bahra 1 bitumen is known to this map.","an":"Within Kuwait: the Burgan seeps guided the 1938 discovery. Regionally, bitumen fingerprinting (biomarkers, isotopes) distinguishes Mesopotamian, Iranian and Kuwaiti sources; Failaka and Umm an-Namel bitumen proved to be imported from Iraq, not local (Connan & Carter 2007).","val":"Biomarker (sterane/terpane) and carbon-isotope fingerprints of Bahra 1 bitumen compared with Bahrah and Burgan oils; survey of surviving ground near the historical Burgan seeps for Ubaid-period sherds, flints or burnt bitumen.","disc":["Outcome A: Bahra 1 bitumen matches Bahrah — two local sources in use.","Outcome B: it matches Burgan — one regional source and an overland or coastal supply line.","Outcome C: it matches Mesopotamian sources — trade outweighed local supply."],"refs":["Carter, R. (2006). Boat remains and maritime trade… during the sixth and fifth millennia BC. Antiquity 80(307), 52–63.","Connan, J. & Carter, R. (2007). A geochemical study of bituminous mixtures from Failaka and Umm an-Namel (Kuwait), from the Early Dilmun to the Early Islamic period. Arabian Archaeology and Epigraphy 18, 139–181. (Restates that the As-Sabiyah boat bitumen came from Burgan.)","GeoExpro. The Great Burgan Field, Kuwait (history of the Bahrah and Burgan seeps and the 1938 discovery). geoexpro.com/the-great-burgan-field-kuwait"],"ic":"spark","era":"?","te":"The First Oil Trade","ta":"أول تجارة نفط","se":"Seven thousand years ago, sailors at Subiya coated their reed boats with bitumen from Burgan. In 1938 the same seeps led to Kuwait’s oil. Did the people of Bahra use their own seep instead?","sa":"قبل سبعة آلاف عام طلى بحّارة الصبية قوارب القصب بقار من برقان. وفي عام 1938 قادت التسربات نفسها إلى نفط الكويت. فهل استخدم أهل بحرة تسرّبهم الخاص بدلًا منه؟","na":"درب القار: من برقان إلى الصبية","spec":{"bas":"link","key":"bitumen","sty":"ai-bitumen","spot":{"en":"Born from two real records on this map: bitumen on the boat remains at H3 (about 5500–5000 BC) was traced chemically to Burgan, inland Kuwait, and the Burgan seeps later guided the 1938 oil discovery.","ar":"وُلدت الفكرة من سجلّين حقيقيين على هذه الخريطة: قار بقايا القوارب في H3 (نحو 5500–5000 ق.م) تُتبّع كيميائيًا إلى برقان في داخل الكويت، وتسربات برقان قادت لاحقًا إلى اكتشاف النفط عام 1938."},"lk":[["h3-site","Boat bitumen traced to Burgan","قار القوارب الذي تُتبّع إلى برقان"],["burgan-oil-ecology","The oil field that grew from the seeps","حقل النفط الذي نشأ من التسربات"],["bahra-1","The nearby Ubaid village: whose bitumen did it use?","قرية العبيد القريبة: أي قار استخدمت؟"],["bahrah-hydrothermal","The Bahrah seeps and deep faults","تسربات بحرة وصدوعها العميقة"],["spec-seepage-mounds","Another possible seep on the Subiya coast","تسرّب محتمل آخر على ساحل الصبية"]],"pred":{"en":"Bitumen from Bahra 1, once analysed, will match the Bahrah seeps rather than Burgan; and Ubaid-period traces (sherds, flints, burnt bitumen) will turn up near the old Burgan seeps.","ar":"حين يُحلَّل قار بحرة 1 سيطابق تسربات بحرة لا برقان، وستظهر آثار من عصر العبيد (كسر فخار أو صوان أو قار محروق) قرب تسربات برقان القديمة."},"test":{"en":"Compare biomarker and isotope fingerprints of Bahra 1 bitumen with Bahrah and Burgan oils; survey surviving ground near the old Burgan seeps for Ubaid-period finds.","ar":"مقارنة البصمات الحيوية والنظيرية لقار بحرة 1 بنفط بحرة وبرقان، ومسح ما بقي من الأرض قرب تسربات برقان القديمة بحثًا عن لُقى من عصر العبيد."},"wrong":{"en":"If Bahra 1’s bitumen also matches Burgan, the local-source idea fails; if no Ubaid traces exist near Burgan, the bitumen was fetched without camps or came by trade.","ar":"إذا طابق قار بحرة 1 برقان أيضًا تسقط فكرة المصدر المحلي، وإن لم توجد آثار للعبيد قرب برقان فقد جُلب القار دون مخيمات أو وصل بالتجارة."}},"t0":7500,"t1":0},{"id":"spec-buried-river","n":"Buried Channels of the Kuwait River","c":"speculative","s":"Cross-category hypothesis","lat":29.32,"lng":47.2,"p":"Early–Middle Holocene (wet phases)","dr":"c. 11,000–5,000 years ago (proposed flow)","el":"","desc":"A connection between the Dibdibba gravels, Wadi Al-Batin and Kuwait’s water. After 1991, Farouk El-Baz noticed smooth granite and basalt pebbles in Kuwait that are abundant only in western Arabia, and traced on satellite images a dry channel from the Hijaz mountains to Kuwait, partly under dunes, which he called the Kuwait River (El-Baz 1993); he suggested it flowed in wetter times. The hypothesis here is that buried channels of this river beneath Kuwait’s sand sheets still steer groundwater, playas, vegetation, wells and routes.","sig":"If buried channels can be mapped, they would guide groundwater management, explain the distribution of playas and freshwater lenses, and point archaeological survey to the most likely camp and well locations.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Exotic shield-derived gravel (Dibdibba) across northern Kuwait; the Wadi Al-Batin valley; playas along the wadi; freshwater lens at Jahra; historic wells at Al-Atraf and Kadhima near the fan margin.","an":"In November 1981 the SIR-A radar on Space Shuttle Columbia penetrated dry sand in the eastern Sahara and revealed buried valleys, some nearly as wide as the Nile; Stone Age artefacts occur in alluvium along them, and the buried drainage explains the positions of many playas and oases (McCauley et al. 1982).","val":"L-band SAR (e.g. ALOS-2, NISAR) processing over north-west Kuwait; mapping of radar-bright buried channels; ground checks with shallow trenches, groundwater levels and salinity; archaeological survey along channel margins.","disc":["Expected radar signature: bright, branching linear features beneath smooth sand sheets.","Expected hydrology: fresher, shallower groundwater along channels.","Expected archaeology: wells, hearths and lithics clustered on channel margins."],"refs":["El-Baz, F. (1993). A river in the desert. Discover, July 1993.","McCauley, J.F. et al. (1982). Subsurface valleys and geoarcheology of the eastern Sahara revealed by shuttle radar. Science 218(4576), 1004–1020."],"ic":"spark","era":"?","te":"The River Under the Sand","ta":"النهر تحت الرمال","se":"Pebbles from the mountains of western Arabia lie in Kuwait’s desert. An ancient river carried them here. Could its buried channels still decide where water, plants and wells are found?","sa":"في صحراء الكويت حصى من جبال غرب الجزيرة العربية حمله إليها نهر قديم. فهل ما زالت قنواته المدفونة تحدد أين نجد الماء والنبات والآبار؟","na":"القنوات المدفونة لنهر الكويت","spec":{"bas":"link","key":"river","sty":"ai-river","spot":{"en":"Born from two real clues: the Dibdibba gravels of northern Kuwait came from the Arabian Shield far to the west, and Farouk El-Baz traced the dry channel of an ancient river, which he called the Kuwait River, across Arabia on satellite images.","ar":"وُلدت الفكرة من دليلين حقيقيين: حصى الدبدبة في شمال الكويت جاء من الدرع العربي في الغرب البعيد، وتتبّع فاروق الباز في الصور الفضائية القناة الجافة لنهر قديم عبر الجزيرة العربية سمّاه نهر الكويت."},"lk":[["wadi-al-batin","The dry valley El-Baz traced","الوادي الجاف الذي تتبّعه الباز"],["dibdibba-alluvial-fan","Gravel the river carried from western Arabia","حصى حمله النهر من غرب الجزيرة العربية"],["wadi-batin-playas","Playas that fill along the wadi","فيضات تمتلئ على امتداد الوادي"],["jahra-freshwater-lens","Fresh water under Jahra","مياه عذبة تحت الجهراء"],["atraf-ancient-wells","Old wells near the edge of the fan","آبار قديمة قرب حافة المروحة"],["kadhima","The caravan stop with sweet water","محطة القوافل ذات الماء العذب"]],"pred":{"en":"Radar that sees through sand (L-band satellites such as ALOS-2 or NISAR) will show buried channels running north-east across Kuwait, and old wells, camps and stone tools will cluster along them.","ar":"سيُظهر الرادار الذي يرى عبر الرمال (أقمار الحزمة L مثل ALOS-2 أو NISAR) قنوات مدفونة تمتد نحو الشمال الشرقي عبر الكويت، وستتجمع الآبار والمخيمات والأدوات الحجرية القديمة على امتدادها."},"test":{"en":"Process L-band radar over north-west Kuwait; map buried channels; check them with shallow trenches and groundwater data; survey the channel banks for artefacts.","ar":"معالجة صور رادار الحزمة L فوق شمال غرب الكويت، ورسم خرائط القنوات المدفونة، والتحقق منها بخنادق ضحلة وبيانات المياه الجوفية، ومسح ضفاف القنوات بحثًا عن اللُّقى."},"wrong":{"en":"If the radar shows no buried channels, or water and wells show no link to them, the buried-river idea fails for Kuwait.","ar":"إذا لم يُظهر الرادار قنوات مدفونة، أو لم تظهر صلة بينها وبين الماء والآبار، تسقط فكرة النهر المدفون في الكويت."}},"t0":11000,"t1":5000},{"id":"spec-elephant-tracks","n":"Possible Miocene Trackways, Northern Kuwait","c":"speculative","s":"Cross-category hypothesis","lat":29.8,"lng":47.67,"p":"Miocene","dr":"c. 20–5 Ma (age of host beds)","el":"","desc":"A connection between Kuwait’s Miocene vertebrate fossils and a discovery elsewhere in Arabia. Deinotherium and other Miocene vertebrates are recorded from Al-Huwaimiliyah in northern Kuwait. At Mleisa 1 in the United Arab Emirates, Late Miocene rocks (6–8 Ma) preserve the trackways of a herd of at least 13 proboscideans and the 260 m trail of a single large individual, mapped with a kite-borne camera because the prints were too small for satellite images (Bibi et al. 2012). The hypothesis: wind-cleaned Miocene bedding surfaces in northern Kuwait could preserve footprints too.","sig":"Footprints record behaviour (herd structure, movement) that bones cannot; a Kuwaiti trackway would add a new kind of geoheritage site and a link between the fossil record and Miocene ecosystems.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Proboscidean fossils at Al-Huwaimiliyah; petrified wood from Kuwait’s greener past; Miocene floodplain and river deposits in the north.","an":"Mleisa 1 (UAE): at least 13 individuals walking together, crossed by a 260 m trackway, the longest continuous fossil trackway known; mapped by stitching overlapping kite photographs into a calibrated mosaic (Bibi et al. 2012).","val":"Low-altitude drone or kite photogrammetry of exposed Miocene surfaces near the fossil localities after windy seasons; 3D models to detect rows of evenly spaced depressions; ground verification of candidate prints.","disc":["Search target: rows of round, evenly spaced depressions on a single bedding plane.","Best timing: after strong winds have cleared loose sand.","Non-target: random pits, nodules or erosion hollows without a stride pattern."],"refs":["Bibi, F., Kraatz, B., Craig, N., Beech, M., Schuster, M. & Hill, A. (2012). Early evidence for complex social structure in Proboscidea from a late Miocene trackway site in the United Arab Emirates. Biology Letters 8(4), 670–673. DOI: 10.1098/rsbl.2011.1185"],"ic":"spark","era":"?","te":"Footprints of Giants?","ta":"آثار أقدام العمالقة؟","se":"Elephant relatives once roamed northern Kuwait; their bones have been found. In the Emirates, a kite camera revealed a whole herd’s footprints. Could Kuwait’s rocks hide tracks too?","sa":"جابت أقرباء الأفيال شمال الكويت يومًا، ووُجدت عظامها. وفي الإمارات كشفت كاميرا معلّقة بطائرة ورقية آثار أقدام قطيع كامل. فهل تخفي صخور الكويت آثارًا أيضًا؟","na":"آثار أقدام ميوسينية محتملة في شمال الكويت","spec":{"bas":"link","key":"tracks","sty":"ai-tracks","spot":{"en":"Born from two real records: Miocene elephant relatives (Deinotherium) are known from Al-Huwaimiliyah in northern Kuwait, and at Mleisa 1 in the United Arab Emirates, rocks from the same epoch preserve the footprints of a whole herd.","ar":"وُلدت الفكرة من سجلّين حقيقيين: أقرباء الأفيال من عصر الميوسين (الدينوثيريوم) معروفون في الحويملية شمال الكويت، وفي موقع مليسا 1 في الإمارات تحفظ صخور من الحقبة نفسها آثار أقدام قطيع كامل."},"lk":[["huwaimiliyah-fossils","Bones and teeth of Deinotherium","عظام وأسنان الدينوثيريوم"],["petrified-wood-field","Forests from Kuwait’s green past","غابات من ماضي الكويت الأخضر"],["lower-fars-marine-bed","Miocene layers of the same era","طبقات ميوسينية من الحقبة نفسها"],["arfaj-steppe-habitat","Today’s desert ecosystem, for contrast","النظام البيئي الصحراوي اليوم، للمقارنة"]],"pred":{"en":"Drone mosaics of wind-cleaned Miocene surfaces in northern Kuwait will show rows of round, evenly spaced depressions on a single bedding plane, like those at Mleisa.","ar":"ستُظهر صور الطائرات المسيّرة المجمّعة لأسطح ميوسينية نظّفتها الرياح في شمال الكويت صفوفًا من الحفر الدائرية المتباعدة بانتظام على سطح طبقة واحدة، كما في مليسا."},"test":{"en":"Fly drone or kite photo surveys over exposed Miocene beds near the fossil sites after windy seasons; build 3D models; check candidate prints on the ground.","ar":"تصوير الطبقات الميوسينية المكشوفة قرب مواقع الأحافير بطائرات مسيّرة أو كاميرات معلّقة بطائرات ورقية بعد مواسم الرياح، وبناء نماذج ثلاثية الأبعاد، والتحقق من الآثار المرشحة على الأرض."},"wrong":{"en":"If careful surveys find only random pits or erosion hollows with no stride pattern, there is no trackway here, at least not yet.","ar":"إذا لم تجد المسوح الدقيقة سوى حفر عشوائية أو تجاويف تعرية بلا نمط خطوات، فلا آثار أقدام هنا، على الأقل حتى الآن."}},"t0":20000000.0,"t1":5000000.0},{"id":"spec-stone-ships","n":"Boat-Shaped Platforms and the Bronze Age Shore","c":"speculative","s":"Cross-category hypothesis","lat":29.651,"lng":48.092,"p":"Bronze Age","dr":"c. 3000–1500 BC","el":"","desc":"A connection between the 21 linear stone platforms of Al-Subiyah, whose silhouette from above resembles a longboat or spearhead, the Bronze Age tumuli on the same terraces (built by people with close ties to the sea, at the time of the highest Holocene sea levels in Kuwait Bay), and H3, which holds the world’s oldest evidence of seagoing boats. The hypothesis: the platforms are boat-shaped monuments oriented to the sea of their time.","sig":"Would identify a monument type expressing maritime identity in Bronze Age Kuwait, and give a new tool (orientation and elevation relative to the palaeoshoreline) for dating undated stone structures.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Platforms: 21 along 16 km, 6–21 m long, under 2 m wide, curb of vertical slabs, one broad rounded end and one pointed end. Tumuli: radiocarbon dates from the end of the 4th to the mid-2nd millennium BC, coinciding with the Kuwait Bay highstand.","an":"Stone ship settings of the Baltic, built c. 3,000 years ago especially on Gotland, contain burials in some cases and hearths and traces of gatherings in others (Wehlin, reported 2013). Ale’s Stones (Sweden) is a 67 m stone ship of 59 boulders dated c. 1,400 years ago.","val":"Drone and RTK-GPS mapping of all platforms (orientation of the pointed end, base elevation); comparison with the reconstructed highstand shoreline; excavation and dating of one undisturbed platform.","disc":["Test 1: are the pointed ends consistently oriented relative to the old shore?","Test 2: do base elevations cluster just above the highstand line?","Test 3: is there anything beneath (burial, offering, hearth)?"],"refs":["Live Science (2013). Ancient stone ships reveal life and death in the Bronze Age (on J. Wehlin’s research, University of Gothenburg).","Swedish National Heritage Board: Ales stenar (Ale’s Stones), a 67 m stone ship of 59 boulders, dated to c. 1,400 years ago."],"ic":"spark","era":"?","te":"Stone Boats by an Old Shore?","ta":"قوارب حجرية على ساحل قديم؟","se":"Along the Subiya coast, long stone platforms look like boats from above. Bronze Age people here lived close to the sea. Were these stone boats facing the water of their time?","sa":"على ساحل الصبية تبدو منصات حجرية طويلة من الأعلى كأنها قوارب. وعاش أهل العصر البرونزي هنا قريبين من البحر. فهل كانت قوارب حجرية تواجه ماء زمانها؟","na":"منصات على شكل قوارب وساحل العصر البرونزي","spec":{"bas":"link","key":"ships","sty":"ai-ships","spot":{"en":"Born from a shape: from above, the 21 stone platforms of Al-Subiyah look like longboats or spearheads, and they lie near Bronze Age burial mounds built by people with close ties to the sea.","ar":"وُلدت الفكرة من شكل: من الأعلى تبدو منصات الصبية الحجرية الإحدى والعشرون كقوارب طويلة أو رؤوس رماح، وهي تقع قرب مدافن من العصر البرونزي بناها شعب وثيق الصلة بالبحر."},"lk":[["stone-platforms","The boat-shaped platforms themselves","المنصات ذات الشكل القاربي نفسها"],["subiyah-tumuli","Bronze Age burial mounds of a sea-linked people","مدافن العصر البرونزي لشعب مرتبط بالبحر"],["holocene-sea-level","The high shoreline they may face","خط الساحل المرتفع الذي قد تواجهه"],["h3-site","The world’s oldest seagoing boats","أقدم قوارب بحرية في العالم"]],"pred":{"en":"The platforms’ pointed ends will face a consistent direction relative to the ancient shoreline, they will sit just above the Bronze Age high-sea line, and excavation will find burials, offerings or hearths beneath or beside them.","ar":"ستتجه الأطراف المدببة للمنصات اتجاهًا ثابتًا بالنسبة إلى خط الساحل القديم، وستقع فوق خط البحر المرتفع في العصر البرونزي مباشرة، وسيكشف التنقيب عن مدافن أو قرابين أو مواقد تحتها أو بجوارها."},"test":{"en":"Map every platform’s orientation and height with a drone and GPS; compare with the reconstructed high shoreline; excavate one undisturbed platform and date it.","ar":"رسم اتجاه كل منصة وارتفاعها بطائرة مسيّرة وجهاز GPS، والمقارنة بخط الساحل المرتفع المعاد بناؤه، وتنقيب منصة واحدة سليمة وتأريخها."},"wrong":{"en":"If the orientations are random, the heights unrelated to the old shore, or the platforms prove recent, the boat-monument idea fails.","ar":"إذا كانت الاتجاهات عشوائية، أو الارتفاعات بلا صلة بالساحل القديم، أو تبيّن أن المنصات حديثة، تسقط فكرة النُّصب القاربية."}},"t0":5000,"t1":3500},{"id":"spec-fault-water","n":"Fault-Guided Groundwater and Spring Greenness","c":"speculative","s":"Cross-category hypothesis","lat":29.505,"lng":47.772,"p":"Active / Ongoing","dr":"5 Ma – present (faults); seasonal (greenness)","el":"","desc":"A connection between the structural and ecological records along Jal Az-Zor. The Khabra iris meadow shows a high-NDVI green anomaly on spring satellite imagery and sits where the escarpment changes strike; a positive flower structure records strike-slip compression south-west towards Jahra; sinkholes have opened at Had Safah. The hypothesis: faults along Jal Az-Zor act as groundwater barriers or conduits, so spring greenness, wet ground, sinkholes and productive wells align with fault traces.","sig":"Would make spring greenness a cheap, repeatable tracer of active structure and groundwater in Kuwait, useful for well siting, conservation planning and sinkhole hazard.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Co-location of a vegetation anomaly with a change in escarpment strike; mapped strike-slip deformation; recent sinkholes nearby.","an":"At Desert Hot Springs (San Andreas system, California) the Mission Creek fault zone is a groundwater barrier: the water table changes by about 60 m across a 200 m wide zone of faulting (Catchings et al. 2009). Springs along San Andreas strands support fan palm oases in the Coachella Valley. Fracture traces mapped on aerial photographs have long been used to site wells (Lattman & Parizek 1964, reviewed by Sander 2007).","val":"Multi-year spring NDVI composites overlaid on mapped faults with a statistical alignment test; paired well water levels across a fault; shallow seismic or electrical resistivity profiles across fault traces.","disc":["Expected: green patches and sinkholes elongated parallel to faults.","Expected: a step in the water table across at least one fault.","Caution: lineament studies can mislead without ground checks (Sander 2007)."],"refs":["Catchings, R.D., Rymer, M.J., Goldman, M.R. & Gandhok, G. (2009). San Andreas fault geometry at Desert Hot Springs, California, and its effects on earthquake hazards and groundwater. Bulletin of the Seismological Society of America 99(4), 2190–2207. DOI: 10.1785/0120080117","Sander, P. (2007). Lineaments in groundwater exploration: a review of applications and limitations. Hydrogeology Journal 15(1), 71–74. DOI: 10.1007/s10040-006-0138-9"],"ic":"spark","era":"?","te":"Do Faults Water the Desert?","ta":"هل تسقي الصدوع الصحراء؟","se":"Each spring, a meadow on Jal Az-Zor turns green where the cliff bends, close to a fault. In California, palm oases line up along the San Andreas Fault. Do Kuwait’s faults guide its hidden water?","sa":"كل ربيع يخضرّ مرج على جال الزور حيث ينعطف الجرف قرب صدع. وفي كاليفورنيا تصطف واحات النخيل على صدع سان أندرياس. فهل توجّه صدوع الكويت مياهها الخفية؟","na":"مياه جوفية توجهها الصدوع وخضرة الربيع","spec":{"bas":"link","key":"faults","sty":"ai-faults","spot":{"en":"Born from three records on this map: a pressure ridge squeezed up by a strike-slip fault, a spring meadow whose green shows on satellite images where the escarpment bends, and new sinkholes nearby.","ar":"وُلدت الفكرة من ثلاثة سجلات على هذه الخريطة: حيد ضغطي رفعه صدع انزلاقي، ومرج ربيعي تظهر خضرته في الصور الفضائية حيث تنعطف الحافة، وحفر انهيارية جديدة بالقرب."},"lk":[["iris-playa-meadow","Spring green where the escarpment bends","خضرة ربيعية حيث تنعطف الحافة"],["positive-flower-structure","A pressure ridge squeezed up by the fault","حيد ضغطي رفعه الصدع"],["dextral-slip-fault","The fault zone along Jal Az-Zor","نطاق الصدع على امتداد جال الزور"],["had-safah-sinkholes","Ground giving way nearby","أرض تنهار بالقرب"],["arfaj-steppe-habitat","Steppe plants that might follow the water","نباتات السهوب التي قد تتبع الماء"]],"pred":{"en":"On a map, spring greenness, wet ground and sinkholes will line up along fault traces more often than chance, and the water table will step across the faults.","ar":"على الخريطة ستصطف خضرة الربيع والأرض الرطبة والحفر الانهيارية على امتداد الصدوع أكثر مما تسمح به المصادفة، وسيتغير منسوب المياه الجوفية فجأة عبر الصدوع."},"test":{"en":"Overlay years of spring satellite greenness with mapped faults and test the alignment statistically; measure water levels in wells on both sides of a fault; run a shallow seismic or electrical survey across it.","ar":"مطابقة خضرة الربيع في صور فضائية لسنوات عدة مع خرائط الصدوع واختبار الاصطفاف إحصائيًا، وقياس منسوب الماء في آبار على جانبي صدع، وإجراء مسح زلزالي أو كهربائي ضحل عبره."},"wrong":{"en":"If the green patches follow only clay-floored hollows with no link to faults, or water levels match on both sides, the fault-water idea fails.","ar":"إذا تبعت البقع الخضراء المنخفضات ذات القاع الطيني وحدها دون صلة بالصدوع، أو تساوى منسوب الماء على الجانبين، تسقط فكرة الصدوع والماء."}},"t0":5000000.0,"t1":0}],"stops":[{"id":"stop-1","n":"Stop 1","lat":29.6089,"lng":48.0485,"par":"paleo-liquefaction","obs":"Southernmost field stop near Jazirat Dubaij — cemented sand dikes and gravel-filled features in loose Pleisto-Holocene sand."},{"id":"stop-2","n":"Stop 2","lat":29.6108,"lng":48.0462,"par":"paleo-liquefaction","obs":"Cemented sand and gravel-filled dikes with significant age difference from surrounding loose sand."},{"id":"stop-3","n":"Stop 3 (Well)","lat":29.6116,"lng":48.0439,"par":"paleo-liquefaction","obs":"Field stop at a well location — sandstone pipe features and liquefaction evidence near water source."},{"id":"stop-4","n":"Stop 4","lat":29.6119,"lng":48.043,"par":"paleo-liquefaction","obs":"Additional cemented dike features consistent with single large seismic event origin."},{"id":"stop-5","n":"Stop 5","lat":29.6202,"lng":48.0333,"par":"paleo-liquefaction","obs":"Sand dike features in the central section of the study transect."},{"id":"stop-6","n":"Stop 6","lat":29.6215,"lng":48.0326,"par":"paleo-liquefaction","obs":"Liquefaction features with spatial distribution suggesting a single catastrophic event."},{"id":"stop-7","n":"Stop 7","lat":29.6194,"lng":48.0229,"par":"paleo-liquefaction","obs":"Northern section field stop with cemented sand dikes in loose sand matrix."},{"id":"stop-8","n":"Stop 8","lat":29.6278,"lng":48.0194,"par":"paleo-liquefaction","obs":"Northernmost field stop — sand boils and cemented dikes near the Jal Az-Zor escarpment. 7 Data provenance and notes The catalog is a direct scientific-data export from the GeoHeritage Arabia Kuwait dataset. Text is preserved from the application data files; no game mechanics or child-oriented challenge text is included. Some records contain hypotheses derived from satellite interpretation. Those records are retained for research transparency and are marked with confidence, evidence, analog, and validation fields. References are reproduced as stored in the source dataset and may include DOI identifiers where available."}]})}catch(e){console.error("D",String(e).slice(0,80))}
